window.VOCAB_CLASSROOM = [{"id":"praeteritum","number":1,"added":"2026-11-07","level":"B1.1","title":"Präteritum","title_en":"Le passé simple : pour les récits et les comptes rendus","summary":"Raconter par écrit ce qui s'est passé (*Der Zug kam um 8 Uhr an.*) : les verbes réguliers avec *-te*, les verbes irréguliers avec un nouveau radical, et pourquoi les Suisses ne l'emploient presque jamais à l'oral.","purpose":["Le Präteritum est le **passé simple** : un seul mot, sans auxiliaire. *Ich **ging** nach Hause.* (Je suis rentré à la maison.) Il a le même sens que le Perfekt (*Ich **bin** nach Hause **gegangen***). La différence tient surtout à l'**endroit** où on l'emploie.","Vous en avez besoin pour **lire et écrire** : récits, comptes rendus, articles de journal, CV, e-mail qui raconte ce qui s'est passé. Dans la **conversation**, la plupart des gens emploient le Perfekt, sauf pour *war*, *hatte* et les verbes de modalité (*konnte, musste, wollte* …), qui sont aussi courants à l'oral."],"logic":["Trois sortes de verbes, trois schémas : les verbes **réguliers** ajoutent *-te* (*machen → machte*), les verbes **irréguliers** changent de radical (*gehen → ging*) et les verbes **mixtes** font les deux (*denken → dachte*).","**ich** et **er / sie / es** ont la même forme, **sans terminaison** : *ich ging, er ging* ; *ich machte, sie machte*.","Les autres personnes ajoutent les terminaisons *du -(e)st, wir -(e)n, ihr -(e)t, sie / Sie -(e)n* : *du gingst, wir gingen* ; *du machtest, wir machten*. Les verbes forts dont le radical se termine par *-t* ou *-d* ajoutent un *e* : *du fandest, ihr fandet*.","Apprenez chaque verbe irrégulier avec ses trois formes : *gehen – ging – gegangen*. On ne peut pas déduire le radical du Präteritum à partir de l'infinitif.","Les temps allemands n'expriment pas l'aspect. Le Präteritum n'est **pas** l'*imperfetto* italien, l'*imparfait* français ou l'*imperfecto* espagnol : il s'emploie aussi pour des événements uniques et terminés (*Der Zug **kam** um 8 Uhr **an**.*).","Dans la conversation, employez le Perfekt pour la plupart des verbes. *war*, *hatte* et les verbes de modalité (*konnte, musste, wollte* …) sont normaux au Präteritum, à l'oral aussi : *Ich **war** krank und **konnte** nicht kommen.*"],"rules":[{"title":"Verbes réguliers : radical + -te","text":"Prenez le radical (*machen → mach-*) et ajoutez **-te** plus la terminaison. Si le radical se termine par **-d** ou **-t**, ajoutez **-ete** pour pouvoir le prononcer : *arbeiten → arbeitete*, *reden → redete*.","table":{"caption":"Präteritum des verbes réguliers","head":["","machen","arbeiten"],"rows":[["ich","**machte**","**arbeitete**"],["du","machtest","arbeitetest"],["er / sie / es","**machte**","**arbeitete**"],["wir","machten","arbeiteten"],["ihr","machtet","arbeitetet"],["sie / Sie","machten","arbeiteten"]]},"examples":[{"de":"Früher **wohnte** ich in Basel.","en":"Avant, j'habitais à Bâle."},{"de":"Der Techniker **reparierte** den Drucker in zehn Minuten.","en":"Le technicien a réparé l'imprimante en dix minutes."},{"de":"Wir **warteten** eine halbe Stunde auf das Tram.","en":"Nous avons attendu le tram une demi-heure.","note":"*warten* se termine par *-t*, donc *-ete-*."}],"source":"schwach"},{"title":"Verbes irréguliers : un nouveau radical, sans terminaison pour ich et er","text":"Les verbes irréguliers (forts) changent la voyelle du radical et ne prennent **pas de -te**. *ich* et *er / sie / es* n'ajoutent **rien** au nouveau radical ; les autres personnes prennent les terminaisons normales.","table":{"caption":"Präteritum des verbes irréguliers","head":["","gehen","kommen","fahren"],"rows":[["ich","**ging**","**kam**","**fuhr**"],["du","gingst","kamst","fuhrst"],["er / sie / es","**ging**","**kam**","**fuhr**"],["wir","gingen","kamen","fuhren"],["ihr","gingt","kamt","fuhrt"],["sie / Sie","gingen","kamen","fuhren"]]},"examples":[{"de":"Am Montag **fuhr** ich mit dem Velo ins Büro.","en":"Lundi, j'ai pris le vélo pour aller au bureau."},{"de":"Die Gäste **kamen** um 19 Uhr.","en":"Les invités sont arrivés à 19 heures."}],"source":"flexion"},{"title":"Verbes irréguliers courants : apprendre trois formes","text":"Le nouveau radical n'est pas prévisible : apprenez donc chaque verbe irrégulier comme un ensemble : infinitif, Präteritum, Perfekt.","table":{"caption":"Verbes irréguliers dont vous avez souvent besoin","head":["infinitif","Präteritum","Perfekt"],"rows":[["bleiben","**blieb**","ist geblieben"],["essen","**ass**","hat gegessen"],["finden","**fand**","hat gefunden"],["geben","**gab**","hat gegeben"],["lesen","**las**","hat gelesen"],["nehmen","**nahm**","hat genommen"],["schlafen","**schlief**","hat geschlafen"],["schreiben","**schrieb**","hat geschrieben"],["sprechen","**sprach**","hat gesprochen"],["treffen","**traf**","hat getroffen"]]},"examples":[{"de":"Ich **traf** meine Kollegin am Bahnhof.","en":"J'ai rencontré ma collègue à la gare."},{"de":"Nach dem Essen **schrieb** sie noch zwei E-Mails.","en":"Après le repas, elle a encore écrit deux e-mails."}],"source":"stammformen"},{"title":"Verbes mixtes : -te et un nouveau radical","text":"Quelques verbes ajoutent *-te* comme les verbes réguliers, mais changent aussi de radical comme les verbes irréguliers : *denken → **dachte***, *bringen → **brachte***, *kennen → **kannte***, *nennen → **nannte***, *rennen → **rannte*** et *wissen → **wusste***. Le Partizip II change de la même façon : *gedacht, gebracht, gekannt, gewusst*.","examples":[{"de":"Ich **dachte** lange über das Angebot **nach**.","en":"J'ai longuement réfléchi à l'offre.","note":"*nachdenken* est mixte et à particule séparable : *dachte … nach*."},{"de":"Wir **kannten** niemanden in Zürich.","en":"Nous ne connaissions personne à Zurich."},{"de":"Sie **wusste** die Antwort sofort.","en":"Elle a su la réponse tout de suite."}],"source":"schwach"},{"title":"Verbes de modalité : -te et sans Umlaut","text":"Les verbes de modalité ajoutent *-te* et **perdent l'Umlaut** : *können → konnte*, *müssen → musste*, *dürfen → durfte*. *mögen* change aussi le *g* en *ch* : *mochte*. Avec l'Umlaut (*könnte, müsste, dürfte*), c'est le Konjunktiv II, qui a un autre sens.","table":{"caption":"Präteritum des verbes de modalité","head":["","können","müssen","dürfen","wollen","sollen","mögen"],"rows":[["ich / er / sie / es","**konnte**","**musste**","**durfte**","**wollte**","**sollte**","**mochte**"],["du","konntest","musstest","durftest","wolltest","solltest","mochtest"],["wir / sie / Sie","konnten","mussten","durften","wollten","sollten","mochten"],["ihr","konntet","musstet","durftet","wolltet","solltet","mochtet"]]},"examples":[{"de":"Ich **konnte** gestern nicht zum Kurs kommen.","en":"Hier, je n'ai pas pu venir au cours."},{"de":"Wir **mussten** lange auf den Bus warten.","en":"Nous avons dû attendre longtemps le bus."},{"de":"Als Kind **mochte** ich keinen Spinat.","en":"Enfant, je n'aimais pas les épinards."}],"source":"stammformen"},{"title":"sein, haben, werden","text":"Apprenez ces trois verbes par cœur. *haben* est presque régulier, mais attention au double *t* : *hatte*. *werden* a un *-e* même pour *ich* et *er* : *wurde*.","table":{"caption":"Präteritum de sein, haben et werden","head":["","sein","haben","werden"],"rows":[["ich","**war**","**hatte**","**wurde**"],["du","warst","hattest","wurdest"],["er / sie / es","**war**","**hatte**","**wurde**"],["wir","waren","hatten","wurden"],["ihr","wart","hattet","wurdet"],["sie / Sie","waren","hatten","wurden"]]},"examples":[{"de":"Gestern **war** ich in Bern.","en":"Hier, j'étais à Berne."},{"de":"Der Zug **hatte** zwanzig Minuten Verspätung.","en":"Le train avait vingt minutes de retard."},{"de":"Es **wurde** kalt, und wir gingen nach Hause.","en":"Il s'est mis à faire froid, et nous sommes rentrés à la maison."}],"source":"stammformen"},{"title":"Verbes à particule séparable : la particule va à la fin","text":"Les verbes à particule séparable se séparent au Präteritum comme au présent : le verbe est en position 2, la particule à la fin. Dans une subordonnée (avec *weil, dass, als* …), le verbe va à la fin et s'écrit de nouveau en un seul mot.","examples":[{"de":"Der Zug **kam** um 8 Uhr **an**.","en":"Le train est arrivé à 8 heures.","note":"*ankommen → kam … an*"},{"de":"Gestern **rief** mich meine Kollegin **an**.","en":"Hier, ma collègue m'a téléphoné."},{"de":"Wir waren nervös, weil der Zug so spät **ankam**.","en":"Nous étions nerveux parce que le train arrivait si tard.","note":"Subordonnée : un seul mot, à la fin."}],"source":"praeverb"},{"title":"Quand l'employer : écrit ou oral","text":["**À l'écrit :** les récits, comptes rendus, articles de journal et textes sur le passé emploient surtout le Präteritum.","**À l'oral :** dans la conversation, la plupart des gens emploient le Perfekt : *Was **hast** du am Wochenende **gemacht**?*","Plus la situation est formelle, plus on entend le Präteritum."],"examples":[{"de":"Am Montag **fuhr** Herr Keller wie immer mit der S-Bahn nach Zürich.","en":"Lundi, M. Keller a pris comme toujours le S-Bahn pour Zurich.","note":"Un récit écrit : Präteritum."},{"de":"Was **hast** du am Samstag **gemacht**? – Ich **bin** wandern **gegangen**.","en":"Qu'est-ce que tu as fait samedi ? – J'ai fait une randonnée.","note":"Une conversation : Perfekt."},{"de":"Ich **war** gestern krank und **konnte** nicht arbeiten.","en":"Hier, j'étais malade et je n'ai pas pu travailler.","note":"*war* et les verbes de modalité sont aussi courants dans la conversation."}],"source":"schrift"}],"exceptions":[{"title":"Suisse allemand : pas de Präteritum en dialecte","text":["Le suisse allemand, comme les autres dialectes du Sud (haut allemand), n'a pratiquement pas de Präteritum : il emploie le Perfekt pour tout événement passé. Les Suisses disent donc rarement *ging* ou *kam*, même quand ils parlent l'allemand standard.","En allemand standard **écrit**, en revanche, le Präteritum est partout : dans le journal, au travail, dans les livres. Vous devez le lire couramment et l'employer dans vos propres textes."],"examples":[{"de":"Ich **bin** gestern in Bern **gewesen**.","en":"Hier, j'étais à Berne.","note":"Ce que dit typiquement un Suisse."},{"de":"Ich **war** gestern in Bern.","en":"Hier, j'étais à Berne.","note":"Ce que vous écririez."}],"source":"praet"},{"title":"-ete après une consonne + n ou m","text":"Les verbes réguliers prennent aussi **-ete** quand le radical se termine par une consonne plus *n* ou *m*, pour être plus faciles à prononcer : *öffnen → öffnete*, *rechnen → rechnete*, *regnen → es regnete*, *atmen → atmete*. **Mais** après *r*, *l* ou *h* + *n*, il n'y a pas de *e* en plus : *lernen → lernte*, *wohnen → wohnte*.","examples":[{"de":"Es **regnete** den ganzen Tag, deshalb blieben wir zu Hause.","en":"Il a plu toute la journée, c'est pourquoi nous sommes restés à la maison."},{"de":"Die Chefin **öffnete** das Fenster.","en":"La cheffe a ouvert la fenêtre."}],"source":"schwach"},{"title":"Le Perfekt à l'écrit quand cela compte encore maintenant","text":"Même dans un texte écrit, passez au Perfekt quand vous voulez souligner qu'un fait passé a encore un effet maintenant.","examples":[{"de":"Die SBB **hat** den Fahrplan **geändert**: Ab Montag fährt der Zug um 7.32 Uhr.","en":"Les CFF ont modifié l'horaire : dès lundi, le train part à 7 h 32."}],"source":"gebrauch"}],"mistakes":[{"wrong":"Er gehte nach Hause.","right":"Er **ging** nach Hause.","why":"*gehen* est irrégulier : nouveau radical, pas de *-te*. Les apprenants qui connaissent le *-ed* anglais ont tendance à ajouter *-te* à tous les verbes, mais les verbes irréguliers doivent être appris."},{"wrong":"Sie gingt ins Büro.","right":"Sie **ging** ins Büro.","why":"*er / sie / es* n'a pas de terminaison au Präteritum. Le *-t* appartient au présent (*sie geht*)."},{"wrong":"Ich denkte an dich.","right":"Ich **dachte** an dich.","why":"*denken* est un verbe mixte : *-te* et un nouveau radical, *dachte*."},{"wrong":"Gestern arbeitet sie bis 20 Uhr.","right":"Gestern **arbeitete** sie bis 20 Uhr.","why":"Après *-t* ou *-d*, le passé ajoute *-ete*. *arbeitet* est le présent."},{"wrong":"Ich könnte gestern nicht kommen.","right":"Ich **konnte** gestern nicht kommen.","why":"Les verbes de modalité perdent l'Umlaut au Präteritum. *könnte* est le Konjunktiv II (pourrait)."},{"wrong":"Ich möchte dich gestern anrufen.","right":"Ich **wollte** dich gestern anrufen.","why":"*möchte* n'a pas de forme passée propre. Pour le passé, employez *wollte*."},{"wrong":"Der Zug ankam um 8 Uhr.","right":"Der Zug **kam** um 8 Uhr **an**.","why":"Les verbes à particule séparable se séparent aussi au Präteritum : la particule va à la fin."},{"wrong":"Sahst du gestern das Spiel? (im Chat mit einem Freund)","right":"**Hast** du gestern das Spiel **gesehen**?","why":"En anglais (*Did you see …?*) et en espagnol (*¿Viste …?*), le passé simple est normal dans la conversation. En allemand, comme en français avec le passé composé, la conversation préfère le Perfekt ; le Präteritum sonne comme un livre."}],"examples":[{"de":"Die Sitzung **begann** um 9 Uhr und **dauerte** zwei Stunden.","en":"La séance a commencé à 9 heures et a duré deux heures."},{"de":"Früher **wohnten** wir in Bern, dann **zogen** wir nach Zürich.","en":"Avant, nous habitions à Berne, puis nous avons déménagé à Zurich."},{"de":"Ich **wusste** nicht, dass der Laden am Sonntag geschlossen war.","en":"Je ne savais pas que le magasin était fermé le dimanche."},{"de":"Der Chef **brachte** am Freitag Gipfeli für alle **mit**.","en":"Vendredi, le chef a apporté des croissants pour tout le monde.","note":"*mitbringen* est mixte et à particule séparable : *brachte … mit*."},{"de":"Als Kind **wollte** ich Lokführerin werden.","en":"Enfant, je voulais devenir mécanicienne de locomotive."},{"de":"Wir **stiegen** in Olten **um** und **kamen** pünktlich in Bern **an**.","en":"Nous avons changé de train à Olten et sommes arrivés à l'heure à Berne."},{"de":"Es **regnete**, aber wir **hatten** keinen Schirm.","en":"Il pleuvait, mais nous n'avions pas de parapluie."},{"de":"Sie **nahm** das Tram und **war** in zehn Minuten im Büro.","en":"Elle a pris le tram et était au bureau en dix minutes."}],"later":"Le Präteritum au passif (*Die Brücke **wurde** 1950 **gebaut**.*) viendra avec le thème du passif. Les formes anciennes qu'on ne rencontre que dans les livres (*du kamest*) n'ont pas besoin d'être apprises.","selfcheck":{"types":{"form":{"label":"Forme du Präteritum","instruction":"Écrivez le verbe entre parenthèses au Präteritum, à la bonne personne. Écrivez un seul mot.","example":{"q":"Wir ___ am Montag bis 20 Uhr. (arbeiten)","a":"arbeiteten","why":"Verbe régulier, radical en *-t* : *arbeit-ete-*, plus *-n* pour *wir*."}},"rewrite":{"label":"Présent → passé","instruction":"Réécrivez la phrase au Präteritum. Gardez le même ordre des mots. Écrivez toute la phrase.","example":{"q":"Das Meeting fängt um 9 Uhr an.","a":"Das Meeting fing um 9 Uhr an.","why":"*anfangen* est irrégulier et à particule séparable : *fing … an*."}},"pick":{"label":"Oral ou écrit ?","instruction":"Lisez la situation (en allemand simple) et les deux versions. Les deux sont de l'allemand correct. Écrivez **a** ou **b** pour celle qui sonne le plus naturel dans cette situation.","example":{"q":"Du erzählst deiner Mitbewohnerin, was heute Morgen passiert ist. a) Ich habe meinen Schlüssel verloren. b) Ich verlor meinen Schlüssel.","a":"a","why":"Conversation : Perfekt. Le Präteritum *verlor* sonne comme un récit écrit."}}},"items":[{"type":"form","q":"Gestern ___ ich bis 19 Uhr im Büro. (bleiben)","a":["blieb"],"why":"Irrégulier : *bleiben – blieb – geblieben*, sans terminaison pour *ich*."},{"type":"form","q":"Die Chefin ___ uns am Morgen eine Mail. (schicken)","a":["schickte"],"why":"Régulier : *schick-* + *-te*, sans terminaison en plus pour *sie*."},{"type":"form","q":"Anna ___ den Bericht kurz vor Mitternacht. (beenden)","a":["beendete"],"why":"Régulier, radical en *-d* : *-ete*."},{"type":"form","q":"Er ___ die ganze Nacht an die Prüfung. (denken)","a":["dachte"],"why":"Verbe mixte : *denken – dachte – gedacht*."},{"type":"form","q":"Wir ___ leider nicht zur Sitzung kommen. (können)","a":["konnten"],"why":"Verbe de modalité : pas d'Umlaut au Präteritum. *könnten* serait le Konjunktiv II."},{"type":"form","q":"Ich ___ nicht, dass das Büro am Montag geschlossen war. (wissen)","a":["wusste"],"why":"*wissen – wusste – gewusst*, sans terminaison pour *ich*."},{"type":"form","q":"Ihr ___ gestern sehr spät zu Hause. (sein)","a":["wart"],"why":"*sein* au Präteritum : *ihr wart*."},{"type":"rewrite","q":"Der Bus fährt um 7 Uhr ab.","a":["Der Bus fuhr um 7 Uhr ab."],"why":"*abfahren* est irrégulier et à particule séparable : *fuhr … ab*."},{"type":"rewrite","q":"Ich rufe meine Mutter am Abend an.","a":["Ich rief meine Mutter am Abend an."],"why":"*anrufen – rief an – angerufen*, la particule à la fin."},{"type":"pick","q":"Du erzählst einer Kollegin an der Kaffeemaschine von deinem Wochenende. a) Am Samstag bin ich nach Luzern gefahren. b) Am Samstag fuhr ich nach Luzern.","a":["a"],"why":"Conversation : Perfekt. *fuhr* a sa place dans un texte écrit."},{"type":"pick","q":"Du schreibst eine kurze Geschichte für die Kurszeitung. a) Es hat geregnet, und Lea hat am Bahnhof Bern auf ihren Bruder gewartet. b) Es regnete, und Lea wartete am Bahnhof Bern auf ihren Bruder.","a":["b"],"why":"Un récit écrit : Präteritum."},{"type":"pick","q":"Du schreibst einem Freund eine Chatnachricht. a) Sahst du gestern das Spiel? b) Hast du gestern das Spiel gesehen?","a":["b"],"why":"Un chat ressemble à une conversation : Perfekt. *Sahst du …?* sonne comme un livre."}]},"sources":[{"id":"praet","title":"grammis: Präteritum (passé simple ; remplacé par le Perfekt dans les dialectes du Sud)","url":"https://grammis.ids-mannheim.de/terminologie/211"},{"id":"flexion","title":"grammis: Verbflexion nach Tempus und Modus (formes verbales selon le temps et le mode)","url":"https://grammis.ids-mannheim.de/progr@mm/4047"},{"id":"schwach","title":"grammis: Schwache Verben (verbes réguliers, -te / -ete, verbes mixtes)","url":"https://grammis.ids-mannheim.de/progr@mm/4073"},{"id":"stammformen","title":"grammis: Verbale Stammformen (radicaux des verbes : verbes forts, mixtes, de modalité et auxiliaires)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2769"},{"id":"praeverb","title":"grammis: Präverbfügung (verbes à particule séparable)","url":"https://grammis.ids-mannheim.de/terminologie/1185"},{"id":"schrift","title":"grammis: Präteritum versus Präsensperfekt (emploi à l'oral et à l'écrit)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4206"},{"id":"gebrauch","title":"grammis: Die Vorstellung hat bereits begonnen oder begann bereits? Präteritum ou Perfekt","url":"https://grammis.ids-mannheim.de/fragen/3287"}]},{"id":"als-wenn","number":2,"added":"2026-11-07","level":"B1.1","title":"als / wenn","title_en":"Dire « quand » : als, wenn et wann","summary":"Employez *als* pour une seule fois dans le passé, *wenn* pour chaque fois et pour le présent ou l'avenir, et *wann* pour les questions.","purpose":["L'anglais n'a qu'un mot, *when*. L'allemand en a trois : **als**, **wenn** et **wann**. En français, *quand* sert pour les trois, tout comme *quando* en italien et *cuando* en espagnol : ce choix est donc nouveau pour presque tout le monde.","Vous en avez besoin chaque fois que vous racontez un épisode de votre vie (*Als ich in die Schweiz kam, …*), que vous parlez d'habitudes (*Wenn ich Frühschicht habe, …*) ou que vous demandez un moment (*Wann beginnt der Kurs?*)."],"logic":["Posez-vous deux questions. **Est-ce une question sur un moment ?** Alors *wann*. **Est-ce une seule fois dans le passé ?** Alors *als*. Tout le reste, c'est *wenn*.","**als** = **un** événement ou **une période** dans le passé : *Als ich ankam, …* (un moment), *Als ich ein Kind war, …* (l'enfance n'a eu lieu qu'une fois, même si elle a duré des années).","**wenn** = **chaque fois**, au passé, au présent ou au futur, et aussi **si** : *(Immer) wenn ich nach Bern fahre, …*, *Wenn es morgen regnet, …*","**wann** = **à quel moment ?**, dans les questions directes et indirectes : *Wann kommst du?* *Ich weiss nicht, wann er kommt.*","*als* et *wenn* introduisent une subordonnée : le verbe conjugué va donc à la **fin**. Si cette subordonnée vient en premier, la principale **commence par son verbe** : *Als ich ankam, **regnete** es.*"],"rules":[{"title":"Vue d'ensemble : als, wenn ou wann ?","text":"Deux critères décident : est-ce **une seule fois** ou **chaque fois**, et est-ce au **passé** ou au **présent / futur** ? Les questions sur un moment prennent toujours *wann*.","table":{"caption":"Quel mot pour « quand » ?","head":["","passé","présent / futur"],"rows":[["une seule fois","**als**","**wenn**"],["chaque fois (répété)","**wenn**","**wenn**"],["question : à quel moment ?","**wann**","**wann**"]]},"examples":[{"de":"**Als** ich gestern ins Büro kam, war der Kaffee schon fertig.","en":"Quand je suis arrivé au bureau hier, le café était déjà prêt.","note":"Une seule fois dans le passé → *als*."},{"de":"**Wenn** ich ins Büro komme, trinke ich zuerst einen Kaffee.","en":"Quand j'arrive au bureau, je bois d'abord un café.","note":"Chaque fois, au présent → *wenn*."},{"de":"**Wann** kommst du ins Büro?","en":"Quand est-ce que tu viens au bureau ?","note":"Une question → *wann*."}],"source":"temporal"},{"title":"als : un événement ou une période dans le passé","text":["Employez **als** pour une chose qui s'est produite **une seule fois** dans le passé : un moment (*Als das Telefon klingelte, …*) ou une période unique (*Als ich in Genf wohnte, …*, *Als ich ein Kind war, …*).","La principale peut décrire des choses qui se sont souvent produites pendant cette période : *Als ich ein Kind war, spielte ich jeden Tag Fussball.* La subordonnée en *als* désigne quand même une seule période, elle garde donc *als*."],"examples":[{"de":"**Als** ich 2019 nach Winterthur zog, kannte ich niemanden.","en":"Quand j'ai déménagé à Winterthour en 2019, je ne connaissais personne."},{"de":"**Als** ich ein Kind war, spielte ich jeden Tag Fussball.","en":"Quand j'étais enfant, je jouais au football tous les jours.","note":"*jeden Tag* est dans la principale. L'enfance est une seule période, la subordonnée prend donc *als*."},{"de":"Ich war gerade unter der Dusche, **als** das Telefon klingelte.","en":"J'étais justement sous la douche quand le téléphone a sonné."}],"source":"als"},{"title":"wenn : chaque fois, même dans le passé","text":"Pour une chose qui s'est produite **encore et encore** dans le passé, employez **wenn**, pas *als*. Des mots comme *immer* (toujours) ou *jedes Mal* (chaque fois) le rendent clair : *Immer wenn …*, *Jedes Mal, wenn …*","examples":[{"de":"**Immer wenn** ich meine Grossmutter besuchte, backte sie einen Kuchen.","en":"Chaque fois que je rendais visite à ma grand-mère, elle faisait un gâteau."},{"de":"**Wenn** wir früher Ferien hatten, fuhren wir ans Meer.","en":"Autrefois, quand nous avions des vacances, nous allions à la mer."},{"de":"**Jedes Mal, wenn** ich den Zug nahm, hatte er Verspätung.","en":"Chaque fois que je prenais le train, il avait du retard."}],"source":"wenn-temporal"},{"title":"wenn : au présent et au futur, et = si","text":"Au présent et au futur, **wenn** correspond à la fois à *quand* et à *si*. Il sert pour les habitudes (*Wenn ich im Homeoffice arbeite, …*), pour un événement à venir (*Wenn das Paket kommt, …*) et pour les conditions (*Wenn es regnet, …*).","examples":[{"de":"**Wenn** ich im Homeoffice arbeite, mache ich mittags einen Spaziergang.","en":"Quand je travaille en télétravail, je fais une promenade à midi."},{"de":"**Wenn** das Paket morgen kommt, rufe ich dich an.","en":"Quand le colis arrivera demain, je t'appellerai.","note":"Le français choisit entre *quand* et *si*. L'allemand emploie *wenn* pour les deux."},{"de":"**Wenn** es morgen regnet, bleiben wir zu Hause.","en":"S'il pleut demain, nous restons à la maison."}],"source":"wenn"},{"title":"wann : questions directes et indirectes","text":["**wann** demande un moment. Dans une question directe, le verbe vient en position 2 : *Wann **fährt** der Bus?*","Dans une question indirecte, après *Weisst du, …*, *Ich weiss nicht, …* ou *Können Sie mir sagen, …*, c'est toujours *wann*, et le verbe va à la **fin**."],"examples":[{"de":"**Wann** fährt der nächste Bus nach Wil?","en":"Quand part le prochain bus pour Wil ?"},{"de":"Weisst du, **wann** das Meeting **beginnt**?","en":"Tu sais quand la réunion commence ?"},{"de":"Ich weiss noch nicht, **wann** ich Ferien **nehme**.","en":"Je ne sais pas encore quand je prendrai mes vacances."}],"source":"w"},{"title":"Ordre des mots : verbe à la fin, puis verbe en tête","text":"Dans la subordonnée en *als* ou en *wenn*, le verbe conjugué va à la **fin**. La subordonnée peut venir en premier ou en second. Si elle vient en premier, elle occupe la position 1 : la principale **commence donc par son verbe**.","table":{"caption":"La même phrase dans les deux ordres","head":["","partie 1","partie 2"],"rows":[["subordonnée en premier","**Als** ich nach Hause **kam**,","**war** niemand da."],["subordonnée en second","Niemand **war** da,","**als** ich nach Hause **kam**."]]},"examples":[{"de":"**Wenn** ich müde **bin**, **trinke** ich einen Kaffee.","en":"Quand je suis fatigué, je bois un café."},{"de":"Ich trinke einen Kaffee, **wenn** ich müde **bin**.","en":"Je bois un café quand je suis fatigué."},{"de":"**Als** wir in Genf **angekommen sind**, **hat** es geregnet.","en":"Quand nous sommes arrivés à Genève, il pleuvait.","note":"Avec deux parties verbales, la partie conjuguée (*sind*) vient en dernier."}],"source":"integration"}],"exceptions":[{"title":"als signifie aussi « que » (comparaison)","text":["Après un comparatif (*grösser, älter, mehr, lieber*), **als** signifie *que*. Cela n'a rien à voir avec le temps.","Avec la forme simple de l'adjectif, employez **so … wie** (aussi … que) : *so gross wie*. Dans la langue de tous les jours, surtout dans le Sud, on entend aussi *grösser wie*. À l'écrit et à l'examen, employez *grösser als*."],"examples":[{"de":"Zürich ist **grösser als** Bern.","en":"Zurich est plus grande que Berne."},{"de":"Ich trinke **lieber** Tee **als** Kaffee.","en":"Je préfère boire du thé plutôt que du café."},{"de":"Das neue Büro ist **so gross wie** das alte.","en":"Le nouveau bureau est aussi grand que l'ancien."}],"source":"vergleich"},{"title":"als + nom signifie « comme, en tant que »","text":"*als* + un nom, sans verbe, indique un rôle : *als Lehrerin* (comme enseignante), *als Kind* (enfant, quand j'étais enfant). *Als Kind* est une façon courte de dire *Als ich ein Kind war*.","examples":[{"de":"Sie arbeitet **als** Pflegefachfrau im Spital.","en":"Elle travaille comme infirmière à l'hôpital."},{"de":"**Als** Kind wohnte ich in Lugano.","en":"Enfant, j'habitais à Lugano.","note":"*Als Kind* occupe la position 1, le verbe (*wohnte*) vient donc juste après."}],"source":"als"}],"mistakes":[{"wrong":"Wenn ich gestern nach Hause kam, war niemand da.","right":"**Als** ich gestern nach Hause kam, war niemand da.","why":"Une seule fois dans le passé → *als*. L'anglais *when*, le français *quand*, l'italien *quando* et l'espagnol *cuando* ne font pas cette distinction, d'où le réflexe de prendre *wenn*."},{"wrong":"Immer als ich Kopfweh hatte, nahm ich eine Tablette.","right":"Immer **wenn** ich Kopfweh hatte, nahm ich eine Tablette.","why":"*immer* montre que cela s'est produit encore et encore. Répété → *wenn*, même au passé."},{"wrong":"Wenn kommst du?","right":"**Wann** kommst du?","why":"Une question sur un moment prend *wann*. L'anglais *when?*, le français *quand ?*, l'italien *quando?* et l'espagnol *¿cuándo?* emploient le même mot que dans les affirmations, d'où la confusion."},{"wrong":"Ich weiss nicht, wenn der Zug fährt.","right":"Ich weiss nicht, **wann** der Zug fährt.","why":"Une question indirecte sur un moment prend toujours *wann*, tout comme « je ne sais pas quand » est aussi une question en français."},{"wrong":"Ich weiss nicht, wenn er heute kommt. (= whether)","right":"Ich weiss nicht, **ob** er heute kommt.","why":"L'anglais *if*, le français *si*, l'italien *se* et l'espagnol *si* signifient aussi « est-ce que » dans une question indirecte. L'allemand emploie *ob* dans ce cas ; *wenn* ne signifie « si » que dans une condition."},{"wrong":"Als ich war ein Kind, …","right":"Als ich ein Kind **war**, …","why":"*als* et *wenn* envoient le verbe conjugué à la fin de leur subordonnée."},{"wrong":"Als ich ein Kind war, ich wohnte in Lugano.","right":"Als ich ein Kind war, **wohnte ich** in Lugano.","why":"Après la subordonnée, la principale commence par son verbe. L'anglais et le français mettent ici le sujet en premier, c'est donc une erreur de transfert fréquente."},{"wrong":"Wo ich klein war, …","right":"**Als** ich klein war, …","why":"En dialecte suisse allemand, on entend souvent *wo* dans ce rôle. En allemand standard, écrivez et dites *als*."}],"examples":[{"de":"**Als** ich in die Schweiz kam, sprach ich kein Wort Deutsch.","en":"Quand je suis arrivé en Suisse, je ne parlais pas un mot d'allemand."},{"de":"**Als** meine Tochter geboren wurde, wohnten wir noch in Basel.","en":"Quand ma fille est née, nous habitions encore à Bâle."},{"de":"**Wenn** ich Frühschicht habe, stehe ich um fünf Uhr auf.","en":"Quand je travaille en équipe du matin, je me lève à cinq heures."},{"de":"Früher sind wir jedes Wochenende in die Berge gefahren, **wenn** das Wetter schön war.","en":"Avant, nous allions à la montagne chaque week-end quand il faisait beau."},{"de":"**Wenn** du am Bahnhof bist, schreib mir kurz.","en":"Quand tu es à la gare, envoie-moi un petit message."},{"de":"**Wann** hast du morgen Feierabend?","en":"À quelle heure tu finis le travail demain ?"},{"de":"Können Sie mir sagen, **wann** die Post am Samstag schliesst?","en":"Pouvez-vous me dire quand la poste ferme le samedi ?"},{"de":"Mein Bruder ist drei Jahre jünger **als** ich.","en":"Mon frère a trois ans de moins que moi."}],"later":"D'autres mots de temps qui introduisent une subordonnée suivent le même ordre des mots (verbe à la fin) et viendront dans des leçons ultérieures : *nachdem* (après que), *bevor* (avant que), *während* (pendant que), *seit* (depuis que), *bis* (jusqu'à ce que), *sobald* (dès que). *als ob* (comme si) viendra aussi plus tard.","selfcheck":{"types":{"choose":{"label":"als, wenn ou wann ?","instruction":"Écrivez le mot qui manque : *als*, *wenn* ou *wann*. Écrivez un seul mot. Demandez-vous : est-ce une question sur un moment, une seule fois dans le passé, ou chaque fois / maintenant / plus tard ? Dans une phrase, le trou est une comparaison (« que »).","example":{"q":"___ ich gestern nach Hause kam, war niemand da.","a":"Als","why":"*gestern* = une seule fois dans le passé → *als*."}},"join":{"label":"Relier les phrases","instruction":"Reliez les deux phrases avec *als* ou *wenn*. Choisissez le mot vous-même. Mettez le verbe de la subordonnée en *als*/*wenn* à la fin. Vous pouvez commencer par *als*/*wenn* (la principale commence alors par son verbe) ou mettre la subordonnée en second. Gardez les temps tels quels. Écrivez toute la phrase.","example":{"q":"Ich kam ins Büro. Das Telefon klingelte. (ein Moment, gestern)","a":"Als ich ins Büro kam, klingelte das Telefon.","why":"Une seule fois dans le passé → *als*. *kam* va à la fin, et la principale commence par son verbe (*klingelte*)."}}},"items":[{"type":"choose","q":"___ ich 18 war, habe ich die Autoprüfung gemacht.","a":["Als"],"why":"Avoir 18 ans, c'est arrivé une seule fois, dans le passé → *als*."},{"type":"choose","q":"Jedes Mal, ___ ich in Italien war, habe ich meine Grosseltern besucht.","a":["wenn"],"why":"*Jedes Mal* = répété, donc *wenn*, même au passé."},{"type":"choose","q":"___ beginnt der Deutschkurs?","a":["Wann"],"why":"Une question sur un moment → *wann*."},{"type":"choose","q":"___ du morgen Zeit hast, können wir zusammen essen.","a":["Wenn"],"why":"Futur, et aussi une condition (si) → *wenn*."},{"type":"choose","q":"Weisst du, ___ der letzte Zug nach Luzern fährt?","a":["wann"],"why":"Une question indirecte sur un moment → *wann*, avec le verbe (*fährt*) à la fin."},{"type":"choose","q":"___ wir letzten Winter in Davos waren, hat es die ganze Woche geschneit.","a":["Als"],"why":"Un seul séjour, l'hiver dernier → une seule fois dans le passé → *als*."},{"type":"choose","q":"Mein Handy klingelt immer, ___ ich in einer Sitzung bin.","a":["wenn"],"why":"*immer*, au présent → chaque fois → *wenn*."},{"type":"choose","q":"Meine Schwester ist zwei Jahre älter ___ ich.","a":["als"],"why":"Après un comparatif (*älter*), *als* signifie « que »."},{"type":"join","q":"Ich war 20. Ich zog nach Zürich.","a":["Als ich 20 war, zog ich nach Zürich.","Ich zog nach Zürich, als ich 20 war.","Als ich nach Zürich zog, war ich 20.","Ich war 20, als ich nach Zürich zog."],"why":"Avoir 20 ans, c'était une seule fois dans le passé → *als*. *war* va à la fin ; si la subordonnée vient en premier, la principale commence par *zog*."},{"type":"join","q":"Es regnet. Ich nehme das Tram.","a":["Wenn es regnet, nehme ich das Tram.","Immer wenn es regnet, nehme ich das Tram.","Wenn es regnet, nehme ich immer das Tram.","Ich nehme das Tram, wenn es regnet.","Ich nehme immer das Tram, wenn es regnet."],"why":"Présent, chaque fois qu'il pleut → *wenn*. *regnet* va à la fin ; après la subordonnée, la principale commence par *nehme*."}]},"sources":[{"id":"als","title":"grammis, dictionnaire des connecteurs: als (subjonction temporelle, verbe à la fin ; aussi als + nom)","url":"https://grammis.ids-mannheim.de/konnektoren/407056"},{"id":"wenn","title":"grammis, dictionnaire des connecteurs: wenn (temporel et conditionnel, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"wenn-temporal","title":"grammis: Konditionalsätze (y compris wenn temporel pour les événements répétés et uniques)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2101"},{"id":"temporal","title":"grammis: Temporalsätze (subordonnées de temps avec als, während, nachdem, bevor, seit)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2104"},{"id":"w","title":"grammis: Termsatzeinleitende W-Elemente (wann, wo, warum … dans les questions indirectes)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2093"},{"id":"integration","title":"grammis: Integration der Nebensätze (une subordonnée en première position)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1948"},{"id":"vergleich","title":"grammis: Grösser als oder grösser wie? (als et wie dans les comparaisons)","url":"https://grammis.ids-mannheim.de/fragen/134"}]},{"id":"plusquamperfekt","number":3,"added":"2026-11-07","level":"B1.1","title":"Plusquamperfekt","title_en":"Le plus-que-parfait : ce qui s'était passé avant","summary":"Dire ce qui s'était déjà passé avant autre chose dans le passé (*Als ich ankam, war der Zug schon abgefahren.*), surtout après *nachdem*.","purpose":["Le Plusquamperfekt montre qu'une chose s'est produite **avant** un autre événement passé. Il vous fait remonter d'un cran dans le temps : *Als ich am Bahnhof ankam, **war** der Zug schon **abgefahren**.* (Quand je suis arrivé à la gare, le train était déjà parti.)","Il fonctionne comme le plus-que-parfait français : *avais / étais* + participe passé (*était parti*). On le trouve surtout dans les récits et les comptes rendus, à côté du Präteritum, et après *nachdem* (après que)."],"logic":["Forme : prenez le Perfekt et mettez l'auxiliaire au Präteritum : *habe gegessen → **hatte** gegessen*, *bin gefahren → **war** gefahren*.","Même parenthèse verbale qu'au Perfekt : *hatte / war* en position 2, le Partizip II à la fin. Dans une subordonnée, les deux vont à la fin : *…, weil ich den Bus **verpasst hatte**.*","Pensez à une ligne du temps : **Plusquamperfekt** (avant) → **Präteritum / Perfekt** (après) → **maintenant**.","Employez-le seulement quand vous faites un saut en arrière dans le temps. Si vous racontez les événements dans l'ordre où ils se sont produits, le Präteritum ou le Perfekt suffit.","Mots signaux typiques : *nachdem* (après que), *schon* / *bereits* (déjà), *vorher* / *zuvor* (auparavant), *noch nie* (jamais encore).","Attention à l'Umlaut : *ich **hatte** das gemacht* (j'avais fait cela) est le Plusquamperfekt ; *ich **hätte** das gemacht* (j'aurais fait cela) est le Konjunktiv II."],"rules":[{"title":"Forme : hatte / war + Partizip II","text":"Le Plusquamperfekt, c'est le Präteritum de *haben* ou *sein* plus le Partizip II du verbe principal.","table":{"caption":"Plusquamperfekt avec hatte et war","head":["","arbeiten (haben)","fahren (sein)"],"rows":[["ich","**hatte** gearbeitet","**war** gefahren"],["du","hattest gearbeitet","warst gefahren"],["er / sie / es","**hatte** gearbeitet","**war** gefahren"],["wir","hatten gearbeitet","waren gefahren"],["ihr","hattet gearbeitet","wart gefahren"],["sie / Sie","hatten gearbeitet","waren gefahren"]]},"examples":[{"de":"Ich **hatte** den Termin **vergessen**.","en":"J'avais oublié le rendez-vous."},{"de":"Wir **waren** schon nach Hause **gegangen**.","en":"Nous étions déjà rentrés à la maison."}],"source":"plqpf"},{"title":"hatte ou war ? Le même choix qu'au Perfekt","text":["Si un verbe forme son Perfekt avec *sein*, son Plusquamperfekt prend **war**. S'il prend *haben*, il prend **hatte**.","**war:** déplacement d'un point A à un point B (*fahren, gehen, kommen, einsteigen*), changement d'état (*einschlafen, aufwachen, passieren*), et *sein, bleiben, werden*.","**hatte:** verbes avec un complément à l'accusatif (*essen, kaufen, schreiben*), la plupart des autres verbes (*arbeiten, schlafen, warten*) et les verbes de modalité."],"examples":[{"de":"Die Kinder **waren** schon **eingeschlafen**.","en":"Les enfants s'étaient déjà endormis.","note":"*einschlafen* est un changement d'état : *ist eingeschlafen*, donc *war*."},{"de":"Er **hatte** schlecht **geschlafen**.","en":"Il avait mal dormi.","note":"*schlafen* prend *haben* : *hat geschlafen*, donc *hatte*."},{"de":"Ich **war** noch nie in Genf **gewesen**.","en":"Je n'étais encore jamais allé à Genève."}],"source":"hilfsverb"},{"title":"Sens : un cran plus loin dans le passé","text":"Le Plusquamperfekt situe un événement **avant** un moment qui est déjà dans le passé. On l'emploie surtout à côté d'événements racontés au Präteritum.","examples":[{"de":"Lisa **hatte** ihr Handy zu Hause **vergessen**, deshalb konnte sie nicht anrufen.","en":"Lisa avait oublié son portable à la maison, c'est pourquoi elle n'a pas pu appeler."},{"de":"Der Film **hatte** schon **angefangen**, als wir ins Kino kamen.","en":"Le film avait déjà commencé quand nous sommes arrivés au cinéma."}],"source":"praetperf"},{"title":"nachdem : l'événement antérieur","text":["La subordonnée en *nachdem* décrit ce qui s'est passé **en premier**. Son verbe va à la fin. Quand la subordonnée en *nachdem* vient en premier, la principale commence par le verbe.","Si la principale est au **passé** (Präteritum, ou Perfekt à l'oral), la subordonnée en *nachdem* prend le **Plusquamperfekt**.","Si la principale est au **présent**, la subordonnée en *nachdem* prend le **Perfekt**."],"table":{"caption":"Les temps avec nachdem","head":["","subordonnée en nachdem (avant)","principale (après)"],"rows":[["au passé","Plusquamperfekt: *gegessen hatte*","Präteritum : *ging* (à l'oral : *bin gegangen*)"],["au présent","Perfekt: *gegessen habe*","Präsens: *gehe*"]]},"examples":[{"de":"Nachdem ich die E-Mail **geschrieben hatte**, ging ich nach Hause.","en":"Après avoir écrit l'e-mail, je suis rentré à la maison."},{"de":"Nachdem sie in Olten **umgestiegen war**, las sie die Zeitung.","en":"Après avoir changé de train à Olten, elle a lu le journal."},{"de":"Nachdem wir **angekommen waren**, sind wir ins Hotel gegangen.","en":"Après être arrivés, nous sommes allés à l'hôtel.","note":"À l'oral : principale au Perfekt."},{"de":"Nachdem ich **gegessen habe**, gehe ich spazieren.","en":"Après avoir mangé, je vais me promener.","note":"Principale au présent : Perfekt après *nachdem*."}],"source":"temporal"},{"title":"bevor : la subordonnée en bevor est l'événement postérieur","text":"Avec *bevor* (avant que), c'est l'inverse : la subordonnée en *bevor* se produit **plus tard**. En général, les deux propositions prennent le même temps du passé. Vous pouvez employer le Plusquamperfekt dans la principale pour souligner que c'était terminé avant l'événement postérieur.","examples":[{"de":"Bevor ich ins Büro fuhr, **trank** ich einen Kaffee.","en":"Avant d'aller au bureau en voiture, j'ai bu un café."},{"de":"Bevor sie nach Zürich zog, **hatte** sie drei Jahre in Basel **gewohnt**.","en":"Avant de déménager à Zurich, elle avait habité trois ans à Bâle."}],"source":"temporal"},{"title":"schon, vorher, zuvor : un retour en arrière clair","text":"L'allemand n'a pas de concordance des temps fixe : on choisit le temps selon le sens. Quand *schon*, *vorher* ou *zuvor* renvoie à un moment **avant** un moment passé, employez le Plusquamperfekt.","examples":[{"de":"Ich machte mir keine Sorgen, weil ich solche Schmerzen schon vorher **gehabt hatte**.","en":"Je ne m'inquiétais pas, parce que j'avais déjà eu de telles douleurs auparavant."},{"de":"Als die Chefin kam, **hatten** wir die Präsentation schon **vorbereitet**.","en":"Quand la cheffe est arrivée, nous avions déjà préparé la présentation."}],"source":"zeitenfolge"}],"exceptions":[{"title":"À l'oral en Suisse : ich habe gegessen gehabt","text":["Le suisse allemand et d'autres dialectes du Sud n'ont pratiquement pas de Präteritum : pour le passé antérieur, les locuteurs partent donc du Perfekt : *ich habe gegessen gehabt* au lieu de *ich hatte gegessen*. Vous l'entendrez en Suisse, même en allemand standard.","Cette forme double ne fait pas partie du système standard des temps et elle est rare dans les textes écrits. À l'écrit, employez **hatte / war** + Partizip II."],"examples":[{"de":"Ich habe schon gegessen gehabt, als du angerufen hast.","en":"J'avais déjà mangé quand tu as appelé.","note":"Forme orale en Suisse ; à éviter à l'écrit."},{"de":"Ich **hatte** schon **gegessen**, als du anriefst.","en":"J'avais déjà mangé quand tu as appelé.","note":"Allemand standard écrit."}],"source":"doppel"},{"title":"hatte gehabt et war gewesen sont corrects","text":"Le Plusquamperfekt de *haben* et de *sein* eux-mêmes est de l'allemand standard normal : *hatte … gehabt*, *war … gewesen*. Ne les confondez pas avec les formes doubles suisses.","examples":[{"de":"Ich **hatte** an dem Tag keine Zeit **gehabt**.","en":"Ce jour-là, je n'avais pas eu de temps."},{"de":"Er **war** eine Woche krank **gewesen**.","en":"Il avait été malade pendant une semaine."}],"source":"kontrast"},{"title":"Les événements dans l'ordre n'en ont pas besoin","text":"Quand vous racontez les événements dans l'ordre où ils se sont produits, chacun suit simplement le précédent. Le Präteritum (ou le Perfekt) suffit.","examples":[{"de":"Ich **stand** um 6 Uhr **auf**, **duschte** und **fuhr** ins Büro.","en":"Je me suis levé à 6 heures, je me suis douché et je suis allé au bureau."}],"source":"zeitenfolge"}],"mistakes":[{"wrong":"Nachdem ich gegessen habe, ging ich ins Bett.","right":"Nachdem ich gegessen **hatte**, ging ich ins Bett.","why":"La principale est au passé (*ging*), donc l'événement antérieur en *nachdem* prend le Plusquamperfekt. *gegessen habe* ne va qu'avec une principale au présent (*…, gehe ich ins Bett*)."},{"wrong":"Gestern hatte ich im Homeoffice gearbeitet. (du erzählst nur, was du gemacht hast)","right":"Gestern **habe** ich im Homeoffice **gearbeitet**.","why":"Le Plusquamperfekt a besoin d'un événement passé plus tardif à partir duquel on regarde en arrière. L'italien, le français et l'espagnol emploient le plus-que-parfait plus librement, par exemple *te l'avevo detto / je te l'avais dit / te lo había dicho*. L'allemand emploie normalement le Perfekt dans ce cas : *Ich habe es dir doch gesagt!*"},{"wrong":"Als ich ankam, hatte der Zug schon abgefahren.","right":"Als ich ankam, **war** der Zug schon **abgefahren**.","why":"*abfahren* est un déplacement : Perfekt avec *sein* (*ist abgefahren*), donc *war*."},{"wrong":"Ich war den Bericht schon geschrieben.","right":"Ich **hatte** den Bericht schon **geschrieben**.","why":"*schreiben* a un complément à l'accusatif : Perfekt avec *haben*, donc *hatte*."},{"wrong":"Nachdem ich hatte gegessen, ging ich ins Bett.","right":"Nachdem ich **gegessen hatte**, ging ich ins Bett.","why":"*nachdem* envoie le verbe à la fin : d'abord le Partizip II, puis *hatte*. L'anglais (*after I had eaten*) et le français (« après que j'avais mangé ») gardent l'ordre inverse, d'où l'erreur."},{"wrong":"Nachdem wir gegessen hatten, wir gingen spazieren.","right":"Nachdem wir gegessen hatten, **gingen wir** spazieren.","why":"Après une subordonnée en *nachdem*, la principale commence par le verbe. L'anglais et le français mettent ici le sujet en premier, c'est donc un piège fréquent."},{"wrong":"Nachdem dem Essen gingen wir spazieren.","right":"**Nach** dem Essen gingen wir spazieren.","why":"*nachdem* relie deux propositions ; *nach* + datif va avec un nom. En anglais, *after* remplit les deux rôles ; en français, on distingue « après » et « après que »."},{"wrong":"Ich habe schon gegessen gehabt, als du anriefst. (in einem E-Mail)","right":"Ich **hatte** schon **gegessen**, als du anriefst.","why":"Le double Perfekt appartient à l'oral suisse et du sud de l'Allemagne. En allemand standard écrit, employez *hatte / war* + Partizip II."}],"examples":[{"de":"Als ich am Bahnhof ankam, **war** der Zug schon **abgefahren**.","en":"Quand je suis arrivé à la gare, le train était déjà parti."},{"de":"Nachdem wir das Projekt **abgeschlossen hatten**, gingen wir zusammen essen.","en":"Après avoir terminé le projet, nous sommes allés manger ensemble."},{"de":"Sie war müde, weil sie die ganze Nacht nicht **geschlafen hatte**.","en":"Elle était fatiguée parce qu'elle n'avait pas dormi de la nuit."},{"de":"Ich **hatte** meinen Pass zu Hause **vergessen** und musste zurückfahren.","en":"J'avais oublié mon passeport à la maison et j'ai dû y retourner."},{"de":"Die Sitzung **hatte** schon **begonnen**, als ich ins Zimmer kam.","en":"La séance avait déjà commencé quand je suis entré dans la salle."},{"de":"Bis letzten Sommer **war** er noch nie mit dem Glacier Express **gefahren**.","en":"Jusqu'à l'été dernier, il n'avait encore jamais voyagé dans le Glacier Express."},{"de":"Nachdem es den ganzen Tag **geregnet hatte**, schien am Abend endlich die Sonne.","en":"Après une journée entière de pluie, le soleil est enfin apparu le soir."},{"de":"Wir **hatten** einen Tisch **reserviert**, aber das Restaurant war geschlossen.","en":"Nous avions réservé une table, mais le restaurant était fermé."}],"later":"Le Plusquamperfekt au passif (*Das Haus **war** renoviert **worden**.*) et avec les verbes de modalité (*Ich **hatte** nicht kommen **können**.*) viendront plus tard, au niveau B2.","selfcheck":{"types":{"aux":{"label":"hatte ou war ?","instruction":"Écrivez la bonne forme de *hatte* ou *war* dans le trou. Écrivez un seul mot. Vérifiez la personne : *wir hatten*, *wir waren*.","example":{"q":"Ich ___ den Film schon gesehen.","a":"hatte","why":"*sehen* forme son Perfekt avec *haben* (*habe gesehen*), donc *hatte gesehen*."}},"story":{"label":"Raconter l'histoire","instruction":"Les items sont des phrases d'une courte histoire écrite sur Sara. Mettez le verbe entre parenthèses au bon temps : **Präteritum** pour les événements principaux, **Plusquamperfekt** pour ce qui s'est passé avant eux, **Perfekt** pour ce que les personnes disent «entre guillemets». N'écrivez que ce qui va dans le trou (un ou deux mots).","example":{"q":"Paul war hungrig, weil er den ganzen Tag nichts ___. (essen)","a":"gegessen hatte","why":"Ne rien manger est venu avant la faim : Plusquamperfekt. Après *weil*, les deux parties vont à la fin, *hatte* en dernier."}},"join":{"label":"Relier avec nachdem","instruction":"Reliez les deux phrases avec *nachdem*. La première phrase s'est produite en premier : mettez-la dans la subordonnée en *nachdem*, au Plusquamperfekt. Gardez la seconde au Präteritum et supprimez *dann*. Écrivez toute la phrase et commencez par *Nachdem*.","example":{"q":"Er duschte. Dann frühstückte er.","a":"Nachdem er geduscht hatte, frühstückte er.","why":"*duschen* prend *haben* : *geduscht hatte* à la fin. La principale commence par le verbe."}}},"items":[{"type":"aux","q":"Als ich zur Haltestelle kam, ___ der Bus schon abgefahren.","a":["war"],"why":"*abfahren* est un déplacement : *ist abgefahren*, donc *war abgefahren*."},{"type":"aux","q":"Tom ___ sein Portemonnaie zu Hause vergessen, deshalb konnte er nicht bezahlen.","a":["hatte"],"why":"*vergessen* a un complément à l'accusatif : *hat vergessen*, donc *hatte vergessen*."},{"type":"aux","q":"Wir ___ gerade ins Tram eingestiegen, als es zu regnen begann.","a":["waren"],"why":"*einsteigen* est un déplacement : *sind eingestiegen*, donc *wir waren*."},{"type":"aux","q":"Er war müde, weil er schlecht geschlafen ___.","a":["hatte"],"why":"*schlafen* prend *haben* (*hat geschlafen*). Seul *einschlafen* prend *sein*."},{"type":"aux","q":"Sie ___ schon zweimal in Bern gewesen, bevor sie dort eine Stelle fand.","a":["war"],"why":"*sein* forme son Perfekt avec *sein* : *ist gewesen*, donc *war gewesen*."},{"type":"story","q":"Am Freitag ___ Sara erst um 22 Uhr nach Hause. (kommen)","a":["kam"],"why":"Un événement principal de l'histoire : Präteritum, *kommen – kam*."},{"type":"story","q":"Sie war sehr müde, weil sie vorher zwölf Stunden ___. (arbeiten)","a":["gearbeitet hatte"],"why":"Le travail est venu avant la fatigue : Plusquamperfekt, les deux parties à la fin après *weil*."},{"type":"story","q":"Vor der Haustür merkte sie, dass sie ihren Schlüssel im Büro ___. (vergessen)","a":["vergessen hatte"],"why":"Elle a oublié la clé avant de s'en rendre compte : Plusquamperfekt."},{"type":"story","q":"Sie ___ ihre Mitbewohnerin an. (anrufen)","a":["rief"],"why":"L'événement principal suivant : Präteritum. *anrufen* se sépare : *rief … an*."},{"type":"story","q":"Sara sagte: «Ich stehe draussen, weil ich meinen Schlüssel ___.» (vergessen)","a":["vergessen habe"],"why":"Sara parle du moment présent, donc Perfekt, comme dans la conversation."},{"type":"story","q":"Nachdem die Mitbewohnerin die Tür ___, ging Sara sofort ins Bett. (öffnen)","a":["geöffnet hatte"],"why":"*nachdem* + principale au passé : Plusquamperfekt. *öffnen* prend *haben*."},{"type":"join","q":"Wir assen zu Mittag. Dann gingen wir spazieren.","a":["Nachdem wir zu Mittag gegessen hatten, gingen wir spazieren."],"why":"*essen* prend *haben* : *gegessen hatten* pour *wir*. Ensuite, la principale commence par le verbe : *gingen wir*."},{"type":"join","q":"Sie stieg in Olten aus. Dann wartete sie auf den Bus.","a":["Nachdem sie in Olten ausgestiegen war, wartete sie auf den Bus."],"why":"*aussteigen* est un déplacement : *ausgestiegen war*. Ensuite *wartete sie*."}]},"sources":[{"id":"plqpf","title":"grammis: Plusquamperfekt (forme : Präteritum de haben ou sein + Partizip II)","url":"https://grammis.ids-mannheim.de/vggf/2228?termini=term"},{"id":"praetperf","title":"grammis: Präteritumperfekt (le Plusquamperfekt : avant un moment passé)","url":"https://grammis.ids-mannheim.de/terminologie/192"},{"id":"hilfsverb","title":"grammis: Ich bin geschwommen oder ich habe geschwommen? Perfekt avec sein ou haben","url":"https://grammis.ids-mannheim.de/fragen/86"},{"id":"perfektformen","title":"grammis: Perfektformen (Perfekt et Plusquamperfekt partagent le choix entre haben et sein)","url":"https://grammis.ids-mannheim.de/vggf/2226?termini=term"},{"id":"temporal","title":"grammis: Temporalsätze (nachdem, bevor, als)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2104"},{"id":"zeitenfolge","title":"grammis: Gibt es im Deutschen eine normierte Zeitenfolge? (choisir le temps selon le sens)","url":"https://grammis.ids-mannheim.de/fragen/165"},{"id":"kontrast","title":"grammis: Das Präteritumperfekt (exemples, y compris war gewesen)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4181"},{"id":"doppel","title":"grammis: Warum haben wir das Plusquamperfekt, wenn es nie benutzt wird? (y compris les formes doubles)","url":"https://grammis.ids-mannheim.de/fragen/6706"},{"id":"sued","title":"grammis: Präteritum versus Präsensperfekt (formes doubles du Sud : ich habe gegessen gehabt)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/4206"}]},{"id":"relativsatz","number":4,"added":"2026-11-07","level":"B1.1","title":"Relativpronomen und Relativsatz","title_en":"Les subordonnées relatives : la collègue qui …, la ville où …","summary":"Décrire plus précisément une personne ou une chose avec une subordonnée relative (*die Kollegin, **mit der** ich arbeite*), et employer *wo* et *was* aux bons endroits.","purpose":["Une subordonnée relative ajoute une information sur un nom **sans commencer une nouvelle phrase** : *Das ist die Kollegin. Ich arbeite mit ihr.* devient *Das ist die Kollegin, **mit der** ich arbeite.* (C'est la collègue avec qui je travaille.)","Vous l'employez pour dire **quelle** personne ou quelle chose vous voulez dire, ou pour ajouter un détail. Vous en aurez besoin dans les descriptions, les e-mails, les offres d'emploi (*Wir suchen eine Person, **die** gern im Team arbeitet.*) et à l'examen B1."],"logic":["La subordonnée relative vient en général **juste après le nom** qu'elle décrit. Elle commence par un **pronom relatif** : *der, die, das* et leurs formes selon le cas.","Posez-vous deux questions. **Quel nom ?** Il donne le genre et le nombre (masculin, féminin, neutre, pluriel). **Quel rôle le pronom joue-t-il dans la subordonnée relative ?** Cela donne le cas (nominatif, accusatif, datif, génitif).","Les formes sont celles de l'article défini, avec trois exceptions : **denen** (datif pluriel) et **dessen / deren** (génitif, *dont*).","Une subordonnée relative est une subordonnée : le verbe conjugué va à la **fin**, et des **virgules** marquent où la subordonnée commence et où elle finit.","L'allemand ne supprime **jamais** le pronom relatif. L'anglais peut dire *the man I met* ; l'allemand doit dire *der Mann, **den** ich getroffen habe*, comme le français dit « l'homme que j'ai rencontré »."],"rules":[{"title":"Les formes du pronom relatif","text":"Partez de l'article défini. Seuls le datif pluriel et le génitif sont différents : **denen**, **dessen**, **deren**. Dans le tableau, ils sont en gras.","table":{"caption":"Pronoms relatifs","head":["","masculin","neutre","féminin","pluriel"],"rows":[["nominatif","der","das","die","die"],["accusatif","den","das","die","die"],["datif","dem","dem","der","**denen**"],["génitif","**dessen**","**dessen**","**deren**","**deren**"]]},"examples":[{"de":"Das ist das Büro, **das** wir gemietet haben.","en":"Voici le bureau que nous avons loué."},{"de":"Die Kunden, **denen** wir das Angebot geschickt haben, haben schon geantwortet.","en":"Les clients à qui nous avons envoyé l'offre ont déjà répondu."}],"source":"formen"},{"title":"Le genre et le nombre viennent du nom, le cas vient de la subordonnée relative","text":["Le **nom** avant la virgule décide entre **der, die, das** ou le pluriel. Le **verbe ou la préposition dans la subordonnée relative** décide du cas.","Le cas du nom dans la principale ne compte donc pas. Regardez seulement la subordonnée relative : le pronom est-il le sujet (nominatif), le complément d'un verbe comme *sehen, anrufen* (accusatif) ou le complément d'un verbe comme *helfen, danken, geben jemandem* (datif) ?"],"examples":[{"de":"Das ist der Kollege, **der** neben mir sitzt.","en":"Voici le collègue qui est assis à côté de moi.","note":"Nominatif : *der Kollege sitzt neben mir*."},{"de":"Das ist der Kollege, **den** ich gestern angerufen habe.","en":"Voici le collègue que j'ai appelé hier.","note":"Accusatif : *ich habe den Kollegen angerufen*."},{"de":"Das ist der Kollege, **dem** ich beim Umzug geholfen habe.","en":"Voici le collègue que j'ai aidé à déménager.","note":"Datif : *ich habe dem Kollegen geholfen*."},{"de":"Ich kenne den Mann, **der** in der Kantine arbeitet.","en":"Je connais l'homme qui travaille à la cantine.","note":"*den Mann* est à l'accusatif dans la principale, mais dans la subordonnée relative, l'homme est le sujet : **der**."}],"source":"attribut"},{"title":"Le verbe va à la fin","text":"Une subordonnée relative fonctionne comme une subordonnée en *weil* ou en *dass* : le verbe conjugué se place en **dernier**. Avec un verbe de modalité ou un temps composé, le verbe conjugué vient après l'infinitif ou le Partizip II.","examples":[{"de":"Ich suche eine Stelle, die mir Spass **macht**.","en":"Je cherche un emploi qui me plaise."},{"de":"Die Wohnung, die wir gestern besichtigt **haben**, ist leider zu teuer.","en":"L'appartement que nous avons visité hier est malheureusement trop cher."},{"de":"Das ist ein Kurs, den man auch online besuchen **kann**.","en":"C'est un cours qu'on peut aussi suivre en ligne."}],"source":"rel"},{"title":"Les virgules autour de la subordonnée relative","text":"Mettez une virgule **avant** la subordonnée relative. Si la principale continue après elle, mettez aussi une virgule **après**. Si une préposition commence la subordonnée relative, la virgule se place avant la préposition : *die Firma**,** bei der ich arbeite*.","examples":[{"de":"Der Zug**,** den ich jeden Morgen nehme**,** hatte heute Verspätung.","en":"Le train que je prends tous les matins avait du retard aujourd'hui."},{"de":"Die Leute**,** mit denen ich wandern gehe**,** kommen aus dem Aargau.","en":"Les gens avec qui je fais de la randonnée viennent d'Argovie."}],"source":"komma"},{"title":"Préposition + pronom relatif","text":"Si le verbe demande une préposition (*arbeiten bei, sprechen über, sich freuen auf*), la préposition vient **en premier**, devant le pronom. C'est alors la **préposition** qui décide du cas : *mit* + datif, *für* + accusatif, etc.","examples":[{"de":"Das ist die Kollegin, **mit der** ich das Projekt mache.","en":"Voici la collègue avec qui je fais le projet.","note":"*mit* + datif, féminin : *der*."},{"de":"Die Firma, **bei der** ich arbeite, hat 50 Mitarbeitende.","en":"L'entreprise pour laquelle je travaille a 50 collaborateurs."},{"de":"Der Kurs, **für den** ich mich angemeldet habe, beginnt im Januar.","en":"Le cours auquel je me suis inscrit commence en janvier.","note":"*für* + accusatif, masculin : *den*."},{"de":"Das sind die Nachbarn, **von denen** ich dir erzählt habe.","en":"Ce sont les voisins dont je t'ai parlé.","note":"*von* + datif pluriel : *denen*."}],"source":"rel"},{"title":"dessen et deren : dont","text":["**dessen** renvoie à un nom masculin ou neutre, **deren** à un nom féminin ou pluriel. Le choix dépend du **possesseur** (le nom avant la virgule), pas de la chose possédée.","Le nom après *dessen / deren* n'a **pas d'article** : *der Nachbar, dessen Hund …* (jamais *dessen der Hund*)."],"examples":[{"de":"Ich habe einen Nachbarn, **dessen** Hund jede Nacht bellt.","en":"J'ai un voisin dont le chien aboie toutes les nuits."},{"de":"Das ist die Kollegin, **deren** Mann in Basel arbeitet.","en":"Voici la collègue dont le mari travaille à Bâle."},{"de":"Eltern, **deren** Kinder in die Krippe gehen, müssen früh aufstehen.","en":"Les parents dont les enfants vont à la crèche doivent se lever tôt."}],"source":"attribut"},{"title":"wo pour les lieux","text":"Après un nom de lieu, vous pouvez employer **wo** au lieu de préposition + pronom : *die Stadt, **wo** ich wohne* = *die Stadt, **in der** ich wohne*. Les deux sont corrects. *wo* est plus simple et courant à l'oral.","examples":[{"de":"Kennst du ein Restaurant, **wo** man gut Fondue essen kann?","en":"Tu connais un restaurant où l'on mange une bonne fondue ?"},{"de":"Das ist das Dorf, **in dem** meine Grosseltern wohnen.","en":"Voici le village où habitent mes grands-parents.","note":"*wo* est aussi correct ici : *das Dorf, wo …*"}],"source":"wo"},{"title":"was après alles, etwas, nichts, das et après une proposition entière","text":["Employez **was** après les pronoms **alles, etwas, nichts** (*das* est aussi possible ici, mais bien plus rare) et après **das** au sens de « ce que, ce qui ».","Employez aussi **was** quand la subordonnée relative commente **toute la principale**, et non un seul nom : *…, **was** mich freut* (…, ce qui me fait plaisir)."],"examples":[{"de":"**Alles, was** du für den Kurs brauchst, findest du im Intranet.","en":"Tout ce dont tu as besoin pour le cours se trouve sur l'intranet."},{"de":"Gibt es **etwas, was** ich für dich tun kann?","en":"Est-ce qu'il y a quelque chose que je peux faire pour toi ?"},{"de":"Ich kaufe nur **das, was** ich wirklich brauche.","en":"Je n'achète que ce dont j'ai vraiment besoin."},{"de":"Am Freitag haben wir frei, **was** mich sehr freut.","en":"Vendredi, nous avons congé, ce qui me fait très plaisir.","note":"*was* renvoie à toute la première proposition."}],"source":"was"}],"exceptions":[{"title":"Noms de lieux : seulement wo","text":"Après un nom de lieu sans article, comme une ville (*Luzern*) ou la plupart des pays (*Italien*), employez **wo**. Préposition + pronom ne fonctionne pas ici. Avec un article, si : *in der Schweiz, **in der** …*","examples":[{"de":"Ich arbeite in Luzern, **wo** auch meine Schwester wohnt.","en":"Je travaille à Lucerne, où habite aussi ma sœur.","note":"Pas : *Luzern, in dem …*"}],"source":"wo"},{"title":"das Buch, was … : oral, pas standard","text":["À l'oral, on entend souvent *was* après un nom neutre : *das Buch, **was** ich lese*. Ce n'est pas considéré comme standard. À l'écrit et à l'examen, employez **das** après un nom : *das Buch, **das** ich lese*.","Après un adjectif neutre employé comme nom, surtout un superlatif, **was** est normal : *das Beste, **was** …* (la meilleure chose qui …)."],"examples":[{"de":"Das ist das Beste, **was** mir dieses Jahr passiert ist.","en":"C'est la meilleure chose qui me soit arrivée cette année."},{"de":"Das Geschenk, **das** du mir gegeben hast, gefällt mir sehr.","en":"Le cadeau que tu m'as donné me plaît beaucoup.","note":"Après le nom *das Geschenk* : **das**, pas *was*."}],"source":"dasoderwas"},{"title":"La subordonnée relative peut se trouver à l'intérieur de la principale","text":"Si le nom est au début, la subordonnée relative vient juste après lui, et la principale continue après la deuxième virgule. Gardez la subordonnée relative à côté de son nom. Seule la dernière partie du verbe peut se placer entre les deux : *Ich habe den Film gesehen, **den** du mir empfohlen hast.* (J'ai vu le film que tu m'as recommandé.)","examples":[{"de":"Die Sitzung, **die** um 9 Uhr beginnt, dauert zwei Stunden.","en":"La séance qui commence à 9 heures dure deux heures."}],"source":"rel"}],"mistakes":[{"wrong":"Der Mann ich gestern getroffen habe, ist Arzt.","right":"Der Mann, **den** ich gestern getroffen habe, ist Arzt.","why":"L'anglais peut supprimer le pronom relatif (*the man I met*). L'allemand, jamais (le français non plus)."},{"wrong":"die Kollegin, die ich geholfen habe","right":"die Kollegin, **der** ich geholfen habe","why":"*helfen* se construit avec le datif : le datif féminin est *der*. En anglais, en français, en italien et en espagnol, « aider » prend un complément direct (*que j'ai aidée, che ho aiutato, a la que ayudé*), d'où le choix de l'accusatif *die*."},{"wrong":"Ich kenne den Mann, den in der Kantine arbeitet.","right":"Ich kenne den Mann, **der** in der Kantine arbeitet.","why":"Le cas vient de la subordonnée relative, pas de la principale. Ici, l'homme est le sujet de *arbeitet* : nominatif."},{"wrong":"die Kunden, mit die ich spreche","right":"die Kunden, mit **denen** ich spreche","why":"Le datif pluriel est *denen*, pas *die* ni *den*."},{"wrong":"das Buch, was ich lese","right":"das Buch, **das** ich lese","why":"Après un nom, employez *der, die, das*. *was* vient après *alles, etwas, nichts, das*, après un superlatif comme *das Beste* ou après une proposition entière."},{"wrong":"die Wohnung, die wir haben gemietet","right":"die Wohnung, die wir gemietet **haben**","why":"Le verbe conjugué va à la fin de la subordonnée relative. L'anglais, le français, l'italien et l'espagnol gardent ici l'ordre normal des mots."},{"wrong":"die Firma, die ich arbeite","right":"die Firma, **bei der** ich arbeite","why":"La préposition ne peut ni disparaître ni aller à la fin (comme en anglais *the company I work for*). Elle vient en premier : *bei der*."},{"wrong":"die Kollegin, dessen Mann in Basel arbeitet","right":"die Kollegin, **deren** Mann in Basel arbeitet","why":"*dessen / deren* s'accordent avec le possesseur (*die Kollegin*, féminin), pas avec la chose possédée. L'italien *il cui* et l'espagnol *cuyo* s'accordent avec la chose possédée, d'où ce piège fréquent."}],"examples":[{"de":"Wie heisst die Frau, **die** am Empfang arbeitet?","en":"Comment s'appelle la femme qui travaille à la réception ?"},{"de":"Das ist der Laptop, **den** ich vom Geschäft bekommen habe.","en":"C'est l'ordinateur portable que j'ai reçu de mon travail."},{"de":"Der Zug, **mit dem** ich nach Bern fahre, ist immer voll.","en":"Le train que je prends pour aller à Berne est toujours plein."},{"de":"Die Kinder, **denen** ich Nachhilfe gebe, sind sehr motiviert.","en":"Les enfants à qui je donne des cours d'appui sont très motivés."},{"de":"Ich habe eine Nachbarin, **deren** Tochter in Lausanne studiert.","en":"J'ai une voisine dont la fille fait ses études à Lausanne."},{"de":"Das Team, **für das** ich arbeite, ist sehr international.","en":"L'équipe pour laquelle je travaille est très internationale."},{"de":"Wir wohnen in einem Quartier, **wo** es viele Spielplätze gibt.","en":"Nous habitons dans un quartier où il y a beaucoup de places de jeux."},{"de":"Alles, **was** im Kühlschrank ist, darfst du essen.","en":"Tu peux manger tout ce qu'il y a dans le frigo."},{"de":"Der Bus hatte zwanzig Minuten Verspätung, **was** in der Schweiz selten ist.","en":"Le bus avait vingt minutes de retard, ce qui est rare en Suisse."}],"later":"Les relatives sans antécédent avec **wer** et **was**, qui n'ont pas de nom devant elles (*Wer zu spät kommt, muss warten.* – Celui qui arrive en retard doit attendre. *Was du sagst, stimmt.* – Ce que tu dis est vrai.), le pronom relatif soutenu **welcher** (*der Kollege, welcher …*) et la forme de génitif **derer** viendront au niveau B2.","selfcheck":{"types":{"fill":{"label":"Compléter le trou","instruction":"Écrivez le mot relatif qui manque : *der, die, das, den, dem, denen, dessen, deren*, ou *was* ou *wo*. Écrivez un seul mot. Regardez le nom avant la virgule pour le genre et le nombre, et la subordonnée relative pour le cas.","example":{"q":"Der Kurs, ___ ich besuche, ist am Abend.","a":"den","why":"*der Kurs* est masculin, et *besuchen* se construit avec l'accusatif : *ich besuche den Kurs*."}},"prep":{"label":"Préposition + pronom","instruction":"La préposition est donnée entre parenthèses. Écrivez la préposition et le pronom relatif, dans cet ordre (deux mots).","example":{"q":"Die Firma, ___ ich arbeite, ist in Winterthur. (bei)","a":"bei der","why":"*bei* + datif, *die Firma* est féminin : *bei der*."}},"join":{"label":"Relier les phrases","instruction":"Reliez les deux phrases en une seule. Transformez la deuxième phrase en subordonnée relative et placez-la juste après le nom qu'elle décrit. Écrivez toute la nouvelle phrase.","example":{"q":"Ich habe einen Bruder. Er wohnt in Genf.","a":"Ich habe einen Bruder, der in Genf wohnt.","why":"*Er* est le sujet, donc nominatif masculin : *der*. Le verbe *wohnt* va à la fin."}}},"items":[{"type":"fill","q":"Der Mann, ___ dort am Fenster steht, ist mein Chef.","a":["der"],"why":"L'homme est le sujet de *steht* : nominatif masculin, *der*."},{"type":"fill","q":"Der Mann, ___ ich gestern angerufen habe, ist mein Chef.","a":["den"],"why":"*anrufen* se construit avec l'accusatif : *ich habe den Mann angerufen*."},{"type":"fill","q":"Der Mann, ___ ich die Unterlagen gegeben habe, ist mein Chef.","a":["dem"],"why":"*geben* + datif pour la personne : *ich habe dem Mann die Unterlagen gegeben*."},{"type":"fill","q":"Die Kunden, ___ wir eine E-Mail geschickt haben, haben noch nicht geantwortet.","a":["denen"],"why":"*schicken* + datif pour la personne, au pluriel : *denen*, pas *die*."},{"type":"fill","q":"Ich kenne die Frau, ___ Auto vor unserem Haus steht.","a":["deren"],"why":"Le possesseur est *die Frau* (féminin) : *deren*. *Auto* n'a pas d'article."},{"type":"fill","q":"Das ist das Haus, ___ meine Grosseltern gebaut haben.","a":["das"],"why":"Après le nom *das Haus* : *das*, accusatif neutre. Pas *was*, parce qu'il y a un nom."},{"type":"fill","q":"Das ist das Dorf, ___ meine Grosseltern wohnen.","a":["wo","in dem"],"why":"Un lieu : *wo*. *in dem* est aussi correct."},{"type":"fill","q":"Es gibt nichts, ___ ich lieber esse als Rösti.","a":["was","das"],"why":"Après *nichts* : *was*. *das* est aussi correct, mais bien plus rare."},{"type":"prep","q":"Die Kollegen, ___ ich zu Mittag esse, sind sehr nett. (mit)","a":["mit denen"],"why":"*mit* + datif pluriel : *denen*."},{"type":"prep","q":"Das Projekt, ___ wir gerade sprechen, ist sehr wichtig. (über)","a":["über das"],"why":"*sprechen über* + accusatif, *das Projekt* est neutre : *über das*."},{"type":"join","q":"Das ist meine Kollegin. Ich gehe oft mit ihr joggen.","a":["Das ist meine Kollegin, mit der ich oft joggen gehe."],"why":"*mit* + datif féminin : *mit der*. Le verbe conjugué *gehe* va à la fin."},{"type":"join","q":"Der Bus hat Verspätung. Ich nehme ihn jeden Morgen.","a":["Der Bus, den ich jeden Morgen nehme, hat Verspätung."],"why":"*ihn* est à l'accusatif, donc *den*. La subordonnée relative vient juste après *der Bus*, avec une virgule de chaque côté."}]},"sources":[{"id":"formen","title":"grammis: Flexion der Pronomina (formes de der, die, das, denen, dessen)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/3673","note":"Tableau du pronom der/die/das, dont grammis indique qu'il a les mêmes formes que le pronom relatif. Comme pronom relatif, le génitif féminin et pluriel est deren (voir la page sur les subordonnées attributives)."},{"id":"rel","title":"grammis: Relativsätze mit den Pronomen der, die, das (relatives avec der, die, das)","url":"https://grammis.ids-mannheim.de/progr@mm/6867"},{"id":"attribut","title":"grammis: Erweiterung von Nominalphrasen mit Attributsätzen (genre d'après le nom, cas d'après la relative ; dessen, deren)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1643"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (virgules et subordonnées)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"wo","title":"grammis: Relativsätze mit wo (relatives avec wo)","url":"https://grammis.ids-mannheim.de/progr@mm/6868"},{"id":"was","title":"grammis: Relativsätze mit was (relatives avec was)","url":"https://grammis.ids-mannheim.de/progr@mm/6869"},{"id":"dasoderwas","title":"grammis: Das Geheimnis, das oder was du mir verraten hast? (das ou was comme pronom relatif)","url":"https://grammis.ids-mannheim.de/fragen/131"}]},{"id":"weil-obwohl-deshalb-trotzdem","number":5,"added":"2026-11-07","level":"B1.1","title":"weil / obwohl / deshalb / trotzdem","title_en":"Causes, conséquences et surprises : weil, denn, deshalb, obwohl, trotzdem","summary":"Donner une cause (*weil, denn*), une conséquence (*deshalb*) ou une surprise (*obwohl, trotzdem*), avec le verbe à la bonne place.","purpose":["Ces mots relient deux idées : **pourquoi** quelque chose se produit (la cause), **ce qui en découle** (la conséquence), ou le fait que quelque chose se produise **bien que** l'on s'attende au contraire (une surprise).","Vous les employez sans cesse pour expliquer, vous excuser et argumenter : *Ich komme später, **weil** der Zug Verspätung hat.* Les lettres, les discussions et l'examen B1 en ont tous besoin, avec le bon ordre des mots."],"logic":["Choisissez d'abord le **sens** : cause, conséquence ou surprise.","La cause et la conséquence sont les deux faces d'un même lien. *Ich bin krank* (cause) → *ich bleibe zu Hause* (conséquence). **weil** et **denn** introduisent la cause ; **deshalb** introduit la conséquence.","La surprise fonctionne de la même façon : **obwohl** introduit l'obstacle (*obwohl ich krank bin*), **trotzdem** introduit la conséquence surprenante (*trotzdem gehe ich arbeiten*).","Ensuite, c'est le **type de mot** qui décide de la place du verbe. **weil** et **obwohl** envoient le verbe à la **fin**. **denn** se place en dehors de la proposition (position 0), l'ordre normal suit donc : verbe en position 2.","**deshalb**, **deswegen**, **darum** et **trotzdem** sont des adverbes. En position 1, le **verbe vient juste après eux** : *Deshalb **bleibe** ich zu Hause.* Ils peuvent aussi se placer au milieu : *Ich bleibe **deshalb** zu Hause.*"],"rules":[{"title":"Vue d'ensemble : attendu ou inattendu ?","text":["Normalement, une cause entraîne la conséquence attendue : *krank → zu Hause bleiben*. Employez **weil / denn** pour la cause et **deshalb** pour la conséquence.","Parfois, la conséquence attendue ne se produit **pas** : *krank → trotzdem arbeiten*. Employez **obwohl** pour l'obstacle et **trotzdem** pour la conséquence surprenante."],"table":{"caption":"Quel mot ? Ce que le mot introduit × attendu ou non","head":["","attendu","inattendu"],"rows":[["il introduit la cause ou l'obstacle","**weil**, **denn**","**obwohl**"],["il introduit la conséquence","**deshalb** (*deswegen, darum*)","**trotzdem**"]]},"examples":[{"de":"Ich bleibe zu Hause, **weil** ich krank bin.","en":"Je reste à la maison parce que je suis malade."},{"de":"Ich bin krank. **Deshalb** bleibe ich zu Hause.","en":"Je suis malade. C'est pourquoi je reste à la maison."},{"de":"Ich gehe zur Arbeit, **obwohl** ich krank bin.","en":"Je vais travailler bien que je sois malade."},{"de":"Ich bin krank. **Trotzdem** gehe ich zur Arbeit.","en":"Je suis malade. Je vais quand même travailler."}],"source":"konzessiv"},{"title":"La cause avec weil : verbe à la fin","text":["**weil** introduit une subordonnée : le verbe conjugué va à la **fin**. Avec deux parties verbales, la partie conjuguée vient en dernier : *weil ich arbeiten **muss***.","La subordonnée en *weil* peut venir en premier. Alors, la principale **commence par son verbe**. Une subordonnée en *weil* seule répond aussi à une question en *warum?*."],"examples":[{"de":"Ich komme heute später, **weil** der Zug Verspätung **hat**.","en":"J'arrive plus tard aujourd'hui parce que le train a du retard."},{"de":"**Weil** ich krank **bin**, **bleibe** ich zu Hause.","en":"Comme je suis malade, je reste à la maison."},{"de":"Warum lernst du Deutsch? – **Weil** ich in der Schweiz arbeiten **möchte**.","en":"Pourquoi est-ce que tu apprends l'allemand ? – Parce que j'aimerais travailler en Suisse."}],"source":"weil"},{"title":"La cause avec denn : ordre normal des mots","text":"**denn** donne aussi une cause, mais il ne change pas l'ordre des mots. Il se place en **position 0**, entre les deux phrases : le verbe reste donc en **position 2**, comme dans toute phrase normale.","examples":[{"de":"Wir nehmen das Velo, **denn** die Parkplätze in der Stadt **sind** teuer.","en":"Nous prenons le vélo, car les places de parc en ville sont chères."},{"de":"Ich komme nicht mit, **denn** ich **habe** keine Zeit.","en":"Je ne viens pas, car je n'ai pas le temps.","note":"La partie avec *denn* vient toujours après la phrase qu'elle explique. Pour mettre la cause en premier, ou pour répondre à *Warum?*, employez *weil*."}],"source":"denn"},{"title":"La conséquence avec deshalb, deswegen, darum","text":["**deshalb**, **deswegen** et **darum** ont le même sens : *c'est pourquoi, donc*. Ils introduisent la **conséquence** et renvoient à la cause qui précède.","Ce sont des adverbes : ils comptent comme un seul élément de la phrase. En position 1, le **verbe vient juste après eux**. Ils peuvent aussi se placer au milieu de la phrase, après le verbe."],"table":{"caption":"Deux places pour deshalb","head":["place","exemple"],"rows":[["position 1, le verbe juste après","Der Bus hatte Verspätung. **Deshalb bin** ich zu spät gekommen."],["au milieu, après le verbe","Der Bus hatte Verspätung. Ich **bin deshalb** zu spät gekommen."]]},"examples":[{"de":"Mein Kollege ist krank. **Deshalb muss** ich seine Kunden anrufen.","en":"Mon collègue est malade. C'est pourquoi je dois appeler ses clients."},{"de":"Die Miete ist hoch. Wir suchen **deswegen** eine kleinere Wohnung.","en":"Le loyer est élevé. Nous cherchons donc un appartement plus petit."},{"de":"Im Zug kann ich lesen. **Darum fahre** ich lieber mit dem Zug als mit dem Auto.","en":"Dans le train, je peux lire. C'est pour ça que je préfère prendre le train plutôt que la voiture."}],"source":"adverb"},{"title":"La surprise avec obwohl : verbe à la fin","text":"**obwohl** (bien que) introduit l'**obstacle** : ce qui aurait dû empêcher la conséquence. Il fonctionne comme *weil* : verbe à la **fin**, et si la subordonnée vient en premier, la principale commence par son verbe.","examples":[{"de":"Sie ist pünktlich gekommen, **obwohl** ihr Bus Verspätung **hatte**.","en":"Elle est arrivée à l'heure bien que son bus ait eu du retard."},{"de":"**Obwohl** ich seit drei Jahren in Bern **wohne**, **verstehe** ich Berndeutsch noch nicht gut.","en":"Bien que j'habite à Berne depuis trois ans, je ne comprends toujours pas bien le bernois."}],"source":"obwohl"},{"title":"La surprise avec trotzdem : le verbe juste après","text":"**trotzdem** (quand même, pourtant) introduit la **conséquence surprenante**. C'est un adverbe, comme *deshalb* : en position 1, le verbe vient juste après lui ; il peut aussi se placer au milieu de la phrase.","examples":[{"de":"Der Chef war gestern krank. **Trotzdem hat** er an der Sitzung teilgenommen.","en":"Le chef était malade hier. Il a quand même participé à la séance."},{"de":"Ich habe wenig geschlafen. Ich bin **trotzdem** fit.","en":"J'ai peu dormi. Je suis quand même en forme."}],"source":"trotzdem"},{"title":"trotz, obwohl, trotzdem : une idée, trois types de mots","text":["La même surprise peut se dire de trois façons. **trotz** est une préposition et se construit avec un **nom** au génitif (voir le thème sur le génitif). **obwohl** se construit avec une **proposition** au verbe final. **trotzdem** commence une **principale**, avec le verbe juste après lui.","La cause a le même trio : **wegen** + nom, **weil** + proposition, **deshalb** + principale."],"table":{"caption":"Même sens, ordre des mots différent","head":["mot","type","ce qui suit","exemple"],"rows":[["**trotz**","préposition","un nom (génitif)","**Trotz des Regens** gehen wir wandern."],["**obwohl**","conjonction","une proposition, verbe à la fin","**Obwohl** es **regnet**, gehen wir wandern."],["**trotzdem**","adverbe","le verbe juste après","Es regnet. **Trotzdem gehen** wir wandern."]]},"examples":[{"de":"**Trotz des Regens** gehen wir wandern.","en":"Malgré la pluie, nous partons en randonnée."},{"de":"**Obwohl** es regnet, gehen wir wandern.","en":"Bien qu'il pleuve, nous partons en randonnée."},{"de":"Es regnet. **Trotzdem** gehen wir wandern.","en":"Il pleut. Nous partons quand même en randonnée."}],"source":"trotzdem"}],"exceptions":[{"title":"weil avec le verbe en position 2 : seulement à l'oral","text":["Dans la langue de tous les jours, on entend souvent *weil* avec le verbe en position 2, en général après une courte pause : *…, weil – ich hab keine Zeit.* À l'oral, c'est presque aussi courant que le verbe à la fin, et grammis dit que ce n'est pas simplement faux.","À l'écrit, c'est considéré comme une faute. Dans les e-mails, les lettres et à l'examen, mettez le verbe à la fin."],"examples":[{"de":"Ich komme nicht mit, weil ich hab keine Zeit. (gesprochen)","en":"Je ne viens pas, parce que j'ai pas le temps.","note":"*hab* est la forme courte orale de *habe*."},{"de":"Ich komme nicht mit, **weil** ich keine Zeit **habe**. (geschrieben)","en":"Je ne viens pas, parce que je n'ai pas le temps."}],"source":"verbstellung"},{"title":"trotzdem comme conjonction : à éviter","text":"Vous pourrez lire ou entendre *trotzdem* employé comme *obwohl*, avec le verbe à la fin : *trotzdem es regnet*. grammis signale que l'allemand standard évite cet emploi. Employez *obwohl* pour la subordonnée et gardez *trotzdem* comme adverbe.","examples":[{"de":"Trotzdem es regnet, gehen wir wandern. (avoid)","en":"Bien qu'il pleuve, nous partons en randonnée."},{"de":"**Obwohl** es regnet, gehen wir wandern. (standard)","en":"Bien qu'il pleuve, nous partons en randonnée."}],"source":"konzessiv"},{"title":"Obwohl, … pour se corriger","text":"À l'oral, *obwohl* suivi d'une pause et de l'ordre normal des mots peut corriger ce qu'on vient de dire, comme « quoique … » ou « remarque … » en français. C'est un emploi à part ; pour relier deux idées, le verbe va toujours à la fin.","examples":[{"de":"Ich nehme das Auto. Obwohl – mit dem Zug bin ich schneller.","en":"Je prends la voiture. Quoique – en train, je vais plus vite."}],"source":"obwohl"}],"mistakes":[{"wrong":"Ich komme nicht, weil ich habe keine Zeit.","right":"Ich komme nicht, weil ich keine Zeit **habe**.","why":"*weil* envoie le verbe à la fin. L'anglais *because*, le français *parce que*, l'italien *perché* et l'espagnol *porque* ne changent pas l'ordre des mots, on l'oublie donc facilement. Le verbe en position 2 après *weil* n'existe qu'à l'oral."},{"wrong":"Deshalb ich bleibe zu Hause.","right":"Deshalb **bleibe ich** zu Hause.","why":"*deshalb* occupe la position 1, le verbe vient donc juste après. L'anglais *so I stay* et le français *c'est pourquoi je reste* mettent le sujet en premier ; l'allemand non."},{"wrong":"Ich bin müde, trotzdem ich gehe joggen.","right":"Ich bin müde, trotzdem **gehe ich** joggen.","why":"*trotzdem* fonctionne comme *deshalb* : le verbe vient juste après lui."},{"wrong":"…, denn ich keine Zeit habe.","right":"…, denn ich **habe** keine Zeit.","why":"*denn* ne change pas l'ordre des mots : le verbe reste en position 2. Parmi les mots de cause, seul *weil* l'envoie à la fin."},{"wrong":"Denn ich krank war, bin ich zu Hause geblieben.","right":"**Weil** ich krank war, bin ich zu Hause geblieben.","why":"Une partie avec *denn* ne peut pas venir en premier. Pour mettre la cause en premier, employez *weil*."},{"wrong":"Ich gehe joggen, trotzdem ich müde bin.","right":"Ich gehe joggen, **obwohl** ich müde bin.","why":"Pour une subordonnée avec le verbe à la fin, employez *obwohl*. L'allemand standard évite *trotzdem* comme conjonction."},{"wrong":"Obwohl es regnet, wir gehen wandern.","right":"Obwohl es regnet, **gehen wir** wandern.","why":"Quand la subordonnée en *obwohl* ou en *weil* vient en premier, la principale commence par son verbe. L'anglais et le français mettent ici le sujet en premier, c'est donc une erreur de transfert fréquente."},{"wrong":"Ich habe viel gelernt. Trotzdem habe ich die Prüfung bestanden.","right":"Ich habe viel gelernt. **Deshalb** habe ich die Prüfung bestanden.","why":"Réussir est la conséquence attendue quand on a étudié, il faut donc *deshalb*. *trotzdem* sert seulement pour une surprise : *Ich habe wenig gelernt. Trotzdem habe ich bestanden.*"}],"examples":[{"de":"Ich rufe dich später an, **weil** ich gerade in einer Sitzung bin.","en":"Je te rappelle plus tard parce que je suis en séance."},{"de":"Ich nehme einen Regenschirm mit, **denn** am Nachmittag soll es regnen.","en":"Je prends un parapluie, car il paraît qu'il va pleuvoir l'après-midi."},{"de":"Die Kita schliesst um sechs. **Deshalb** muss ich pünktlich gehen.","en":"La crèche ferme à six heures. C'est pourquoi je dois partir à l'heure."},{"de":"Ich hatte Fieber. Ich bin **deswegen** nicht zur Arbeit gegangen.","en":"J'avais de la fièvre. C'est pour ça que je ne suis pas allé travailler."},{"de":"**Obwohl** die Wohnung klein ist, ist sie sehr teuer.","en":"Bien que l'appartement soit petit, il est très cher."},{"de":"Er spricht gut Deutsch, **obwohl** er erst seit einem Jahr hier lebt.","en":"Il parle bien allemand, bien qu'il n'habite ici que depuis un an."},{"de":"Das Wetter war schlecht. **Trotzdem** sind wir auf den Pilatus gefahren.","en":"Il faisait mauvais. Nous sommes quand même montés au Pilate."},{"de":"Ich mag meinen Job. **Darum** bleibe ich in der Firma.","en":"J'aime mon travail. C'est pour ça que je reste dans l'entreprise."}],"later":"D'autres mots de liaison viendront plus tard : *da* (comme, puisque : soutenu, verbe à la fin), *daher* (= *deshalb*, plus soutenu), *sodass* (si bien que : conséquence, verbe à la fin), *dennoch* (= *trotzdem*, plus soutenu) et *zwar … aber* (certes … mais).","selfcheck":{"types":{"choose":{"label":"Quel mot ?","instruction":"Écrivez le mot qui manque : *weil*, *denn*, *deshalb*, *obwohl* ou *trotzdem*. Écrivez un seul mot. Servez-vous de deux indices : le sens (cause, conséquence ou surprise) et la place du verbe (à la fin, en position 2 ou juste après le trou). Là où *deshalb* convient, *deswegen* et *darum* sont aussi justes.","example":{"q":"Ich trinke viel Wasser, ___ es heiss ist.","a":"weil","why":"Une cause, et le verbe *ist* est à la fin → *weil*."}},"join":{"label":"Relier les phrases","instruction":"Reliez les deux phrases avec le mot entre parenthèses. Changez l'ordre des mots là où le mot l'exige, et employez un pronom si le nom se répète. Une subordonnée en *weil* ou en *obwohl* peut venir en premier ou en second ; *denn* relie toujours la deuxième phrase ; *deshalb* et *trotzdem* peuvent se placer en position 1 ou après le verbe. Écrivez toute la nouvelle phrase.","example":{"q":"Ich habe Hunger. Ich esse ein Sandwich. (deshalb)","a":"Ich habe Hunger, deshalb esse ich ein Sandwich.","why":"*deshalb* introduit la conséquence, et le verbe vient juste après lui : *esse ich*."}}},"items":[{"type":"choose","q":"Ich mache einen Deutschkurs, ___ ich die B1-Prüfung bestehen will.","a":["weil"],"why":"Une cause, et le verbe (*will*) est à la fin → *weil*."},{"type":"choose","q":"Ich mache einen Deutschkurs, ___ ich will die B1-Prüfung bestehen.","a":["denn"],"why":"Une cause, mais le verbe (*will*) reste en position 2 → *denn*."},{"type":"choose","q":"Ich will die B1-Prüfung bestehen. ___ mache ich einen Deutschkurs.","a":["Deshalb","Deswegen","Darum"],"why":"Le cours est la conséquence, et le verbe vient juste après le trou → *deshalb* (ou *deswegen*, *darum*)."},{"type":"choose","q":"___ es schon spät ist, arbeitet mein Chef noch.","a":["Obwohl"],"why":"Il est tard, on s'attendrait donc à ce qu'il arrête : c'est un obstacle. Le verbe (*ist*) est à la fin → *obwohl*."},{"type":"choose","q":"Es ist schon spät. ___ arbeitet mein Chef noch.","a":["Trotzdem"],"why":"Une conséquence surprenante, et le verbe vient juste après le trou → *trotzdem*."},{"type":"choose","q":"Es gab einen Stau. Ich bin ___ zu spät zur Sitzung gekommen.","a":["deshalb","deswegen","darum"],"why":"Être en retard est la conséquence attendue d'un bouchon → *deshalb*, ici au milieu de la phrase."},{"type":"choose","q":"Er ist zur Arbeit gegangen, ___ er Fieber hatte.","a":["obwohl"],"why":"La fièvre aurait dû le retenir à la maison : c'est un obstacle. Le verbe (*hatte*) est à la fin → *obwohl*."},{"type":"join","q":"Das Restaurant ist teuer. Wir essen oft dort. (trotzdem)","a":["Das Restaurant ist teuer, trotzdem essen wir oft dort.","Das Restaurant ist teuer, wir essen trotzdem oft dort.","Das Restaurant ist teuer und trotzdem essen wir oft dort.","Das Restaurant ist teuer und wir essen trotzdem oft dort.","Das Restaurant ist teuer, trotzdem essen wir dort oft.","Das Restaurant ist teuer, wir essen dort trotzdem oft.","Das Restaurant ist teuer und trotzdem essen wir dort oft.","Das Restaurant ist teuer und wir essen dort trotzdem oft.","Das Restaurant ist teuer, aber trotzdem essen wir oft dort.","Das Restaurant ist teuer, aber wir essen trotzdem oft dort."],"why":"*trotzdem* introduit la conséquence surprenante ; le verbe vient juste après lui (*essen wir*), ou *trotzdem* se place au milieu."},{"type":"join","q":"Ich kann nicht kommen. Ich muss arbeiten. (weil)","a":["Ich kann nicht kommen, weil ich arbeiten muss.","Weil ich arbeiten muss, kann ich nicht kommen."],"why":"*weil* envoie le verbe conjugué (*muss*) à la fin, après *arbeiten*."},{"type":"join","q":"Ich nehme ein Taxi. Es ist schon sehr spät. (denn)","a":["Ich nehme ein Taxi, denn es ist schon sehr spät."],"why":"*denn* garde l'ordre normal des mots : *es ist …*, verbe en position 2. La partie avec *denn* vient en second."},{"type":"join","q":"Wir nehmen die Wohnung. Die Wohnung ist teuer. (obwohl)","a":["Wir nehmen die Wohnung, obwohl sie teuer ist.","Obwohl die Wohnung teuer ist, nehmen wir sie.","Obwohl sie teuer ist, nehmen wir die Wohnung.","Wir nehmen die Wohnung, obwohl die Wohnung teuer ist."],"why":"*obwohl* introduit l'obstacle (*teuer*), avec le verbe (*ist*) à la fin. Si la subordonnée vient en premier, la principale commence par *nehmen*."}]},"sources":[{"id":"konzessiv","title":"grammis: Konzessivsätze (concession ; trotzdem comme conjonction est évité en allemand standard)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2109"},{"id":"weil","title":"grammis, dictionnaire des connecteurs: weil (subjonction causale, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs: denn (causal, position 0, le verbe reste en 2e position)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"adverb","title":"grammis: Nicht nacherstfähige Adverbkonnektoren (deshalb, darum, trotzdem : position 1 ou champ central)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1279"},{"id":"deshalb","title":"grammis, dictionnaire des connecteurs: deshalb (conséquence ; synonymes daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs: deswegen (conséquence)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"darum","title":"grammis, dictionnaire des connecteurs: d(a)rum (conséquence)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"obwohl","title":"grammis, dictionnaire des connecteurs: obwohl (subjonction concessive, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406906"},{"id":"trotzdem","title":"grammis, dictionnaire des connecteurs: trotzdem (adverbe concessif ; comparer avec trotz + génitif)","url":"https://grammis.ids-mannheim.de/konnektoren/406981"},{"id":"verbstellung","title":"grammis: Verbstellung nach weil, obwohl, wobei (verbe en 2e position à l'oral)","url":"https://grammis.ids-mannheim.de/fragen/133"}]},{"id":"passiv-praesens","number":6,"added":"2026-11-07","level":"B1.1","title":"Passiv Präsens","title_en":"Le passif : ce qui est fait, pas qui le fait","summary":"Dire ce qui se passe sans dire qui le fait (*Das Altpapier **wird** am Dienstag **abgeholt**.*), aussi avec les verbes de modalité (*Das Formular **muss** bis Freitag **ausgefüllt werden**.*).","purpose":["Le passif met l'**action** au centre, et non la personne qui la fait : *Das Altpapier **wird** am Dienstag **abgeholt**.* (Le vieux papier est ramassé le mardi.) Qui le ramasse n'a pas d'importance, ou tout le monde le sait.","Vous le rencontrez partout en Suisse : avis dans la cage d'escalier, formulaires, modes d'emploi, calendriers de ramassage des déchets, annonces des CFF et e-mails professionnels (*Die Rechnung **wird** morgen **verschickt**.*)."],"logic":["Le passif, c'est **werden + Partizip II**. *werden* est conjugué et se place en position 2. Le Partizip II va à la **fin** : *Die Heizung **wird** heute **repariert**.*","De l'actif au passif, le **complément à l'accusatif devient le sujet** (nominatif) : *Man repariert **den** Lift.* → **Der** *Lift wird repariert.*","En général, celui qui fait l'action disparaît. Si vous en avez besoin, ajoutez-le avec **von** + datif : *vom Hauswart*.","Avec un **verbe de modalité**, le verbe de modalité est en position 2, et **Partizip II + werden** vont à la fin : *Das Formular **muss** ausgefüllt **werden**.*","Dans une subordonnée (*dass, weil, ob* …), le verbe conjugué va en **dernier** : *…, dass das Formular ausgefüllt werden **muss**.*"],"rules":[{"title":"werden + Partizip II","text":"Conjuguez *werden* selon le sujet et placez le Partizip II à la fin. Le Partizip II ne change jamais.","table":{"caption":"Passiv Präsens de fragen (demander)","head":["","werden","exemple"],"rows":[["ich","**werde**","Ich **werde** oft **gefragt**."],["du","**wirst**","Du **wirst** oft **gefragt**."],["er / sie / es","**wird**","Sie **wird** oft **gefragt**."],["wir","**werden**","Wir **werden** oft **gefragt**."],["ihr","**werdet**","Ihr **werdet** oft **gefragt**."],["sie / Sie","**werden**","Sie **werden** oft **gefragt**."]]},"examples":[{"de":"Das Altpapier **wird** am Dienstag **abgeholt**.","en":"Le vieux papier est ramassé le mardi."},{"de":"Die Pakete **werden** morgen **geliefert**.","en":"Les colis seront livrés demain."},{"de":"In diesem Büro **wird** Französisch **gesprochen**.","en":"Dans ce bureau, on parle français."}],"source":"aktivpassiv"},{"title":"De l'actif au passif : le complément à l'accusatif devient le sujet","text":["Prenez le **complément à l'accusatif** de la phrase active et faites-en le **sujet** (nominatif). *werden* s'accorde avec ce nouveau sujet : singulier *wird*, pluriel *werden*.","Le sujet de la phrase active disparaît. Si c'est *man*, il disparaît toujours. Un complément au datif reste au datif : *Man hilft **den Kunden** sofort.* → **Den Kunden** *wird sofort geholfen.*"],"examples":[{"de":"**Der Lift wird** heute **repariert**.","en":"L'ascenseur est réparé aujourd'hui.","note":"Actif : *Man repariert **den Lift** heute.* Accusatif *den Lift* → nominatif *der Lift*."},{"de":"**Die Rechnungen werden** am Monatsende **verschickt**.","en":"Les factures sont envoyées à la fin du mois.","note":"Actif : *Wir verschicken die Rechnungen am Monatsende.* Sujet au pluriel, donc *werden*."}],"source":"subjekt"},{"title":"L'auteur de l'action avec von, un moyen ou une cause avec durch","text":["La plupart des phrases passives ne nomment pas l'auteur de l'action. Si vous voulez le nommer, employez **von** + datif pour la personne ou l'organisation qui fait l'action : *von der Chefin, von der Gemeinde, vom Hauswart* (*vom* = *von dem*).","Pour un **moyen** ou une **cause**, employez **durch** + accusatif : *durch eine Wärmepumpe, durch den Lärm*."],"examples":[{"de":"Die Sitzung **wird von der Chefin geleitet**.","en":"La séance est dirigée par la cheffe."},{"de":"Die Lernenden **werden von einer erfahrenen Fachperson betreut**.","en":"Les apprentis sont encadrés par une personne de métier expérimentée."},{"de":"Die Wohnung **wird durch eine Wärmepumpe geheizt**.","en":"L'appartement est chauffé par une pompe à chaleur."},{"de":"Der Verkehr **wird durch die Baustelle behindert**.","en":"La circulation est gênée par le chantier."}],"source":"agens"},{"title":"Passif sans sujet : Hier wird nicht geraucht.","text":["Certaines phrases passives n'ont **pas de sujet** du tout. Elles disent ce que les gens font (ou ne font pas) en général, souvent avec des verbes employés sans complément : *arbeiten, rauchen, essen, tanzen, lachen*. *werden* est toujours **wird**.","Si rien d'autre n'occupe la position 1, **es** la remplit : *Es wird viel gelacht.* Si un autre mot est en position 1, *es* disparaît : *Bei uns wird viel gelacht.*"],"examples":[{"de":"Hier **wird** nicht **geraucht**.","en":"Ici, on ne fume pas."},{"de":"Am Sonntag **wird** nicht **gearbeitet**.","en":"Le dimanche, on ne travaille pas."},{"de":"In unserem Team **wird** viel **gelacht**.","en":"Dans notre équipe, on rit beaucoup."},{"de":"**Es wird** um 12 Uhr **gegessen**.","en":"On mange à midi."}],"source":"subjektlos"},{"title":"Passif avec verbes de modalité : muss … ausgefüllt werden","text":"Le **verbe de modalité** (*muss, kann, darf, soll*) est conjugué et se place en position 2. À la fin viennent le **Partizip II** puis **werden** (à l'infinitif, il ne change jamais). C'est ce que les avis et les formulaires emploient tout le temps.","examples":[{"de":"Das Formular **muss** bis Freitag **ausgefüllt werden**.","en":"Le formulaire doit être rempli d'ici vendredi."},{"de":"Velos **dürfen** hier nicht **abgestellt werden**.","en":"Il est interdit de garer des vélos ici."},{"de":"Der Termin **kann** auch online **verschoben werden**.","en":"Le rendez-vous peut aussi être déplacé en ligne."},{"de":"Hunde **müssen** an der Leine **geführt werden**.","en":"Les chiens doivent être tenus en laisse."}],"source":"modal"},{"title":"Dans une subordonnée, le verbe conjugué va en dernier","text":"Après *dass, weil, ob, wenn* et dans les subordonnées relatives, tout le groupe verbal va à la fin, et le verbe **conjugué** est le tout dernier mot : *… repariert **wird***, *… ausgefüllt werden **muss***.","examples":[{"de":"Wir informieren Sie, dass das Wasser am Montag **abgestellt wird**.","en":"Nous vous informons que l'eau sera coupée lundi."},{"de":"Weisst du, ob das Paket heute **geliefert wird**?","en":"Tu sais si le colis est livré aujourd'hui ?"},{"de":"Bitte beachten Sie, dass der Antrag **unterschrieben werden muss**.","en":"Veuillez noter que la demande doit être signée."}],"source":"klammer"}],"exceptions":[{"title":"ist geöffnet (l'état) ou wird geöffnet (l'action) ?","text":["**sein + Partizip II** décrit un **état**, le résultat d'une action : *Der Laden **ist** geöffnet.* (Le magasin est ouvert.) On l'appelle le *Zustandspassiv* (passif d'état).","**werden + Partizip II** décrit l'**action** elle-même, ce qui se passe : *Die Türen **werden** um 19 Uhr **geöffnet**.* (Les portes sont ouvertes à 19 heures, c'est-à-dire qu'on les ouvre à ce moment-là.)"],"examples":[{"de":"Die Post **ist** am Samstag bis 12 Uhr **geöffnet**.","en":"Le samedi, la poste est ouverte jusqu'à midi.","note":"Heures d'ouverture : un état, donc *ist*."},{"de":"Die Türen **werden** um 19 Uhr **geöffnet**.","en":"Les portes ouvrent à 19 heures.","note":"Quelqu'un les ouvre à ce moment-là : une action, donc *werden*."},{"de":"Das Formular **ist** schon **ausgefüllt**.","en":"Le formulaire est déjà rempli.","note":"L'action est terminée ; c'est le résultat."}],"source":"zustand"},{"title":"werden a trois rôles","text":["**werden + Partizip II** = passif : *Ich werde morgen **angerufen**.* (On m'appelle demain.)","**werden + infinitif** = futur : *Ich werde morgen **anrufen**.* (J'appellerai demain.)","**werden** seul = devenir : *Sie wird Pflegefachfrau.* (Elle devient infirmière.)","Quand *werden* est le verbe conjugué, regardez donc le verbe à la fin : un Partizip II (*gemacht*) signifie passif, un infinitif (*machen*) signifie futur."],"examples":[{"de":"Die Heizung **wird** morgen **repariert**.","en":"Le chauffage sera réparé demain.","note":"Passif : Partizip II."},{"de":"Der Techniker **wird** morgen **kommen**.","en":"Le technicien viendra demain.","note":"Futur : infinitif."}],"source":"hilfsverb"}],"mistakes":[{"wrong":"Das Formular muss werden ausgefüllt.","right":"Das Formular muss **ausgefüllt werden**.","why":"L'anglais *must be filled in*, le français *doit être rempli*, l'italien *deve essere compilato* et l'espagnol *debe ser rellenado* mettent « être » en premier. L'allemand met *werden* en dernier."},{"wrong":"Das Formular muss bis Freitag ausgefüllt.","right":"Das Formular muss bis Freitag ausgefüllt **werden**.","why":"Avec un verbe de modalité, le passif a toujours besoin de *werden* à la fin."},{"wrong":"Die Briefe sind jeden Tag verteilt.","right":"Die Briefe **werden** jeden Tag verteilt.","why":"Une action qui se produit demande *werden*. L'anglais *are*, le français *sont*, l'italien *sono* et l'espagnol *son* poussent vers *sind*, mais *sein* + Partizip II ne décrit qu'un état."},{"wrong":"Die Sitzung wird bei der Chefin geleitet.","right":"Die Sitzung wird **von** der Chefin geleitet.","why":"*bei* ressemble à l'anglais *by*, mais il signifie « chez » ou « auprès de ». L'auteur de l'action prend *von* (en français : « par »)."},{"wrong":"Die Sitzung wird von die Chefin geleitet.","right":"Die Sitzung wird von **der** Chefin geleitet.","why":"*von* est toujours suivi du datif. (*durch* est suivi de l'accusatif : *durch den Lärm*.)"},{"wrong":"Den Lift wird repariert.","right":"**Der** Lift wird repariert.","why":"Le complément à l'accusatif de la phrase active devient le sujet : il passe donc au nominatif."},{"wrong":"Hier werden nicht geraucht.","right":"Hier **wird** nicht geraucht.","why":"Un passif sans sujet prend toujours *wird*, le singulier."},{"wrong":"…, dass das Formular muss ausgefüllt werden.","right":"…, dass das Formular ausgefüllt werden **muss**.","why":"Dans une subordonnée en *dass*, le verbe conjugué (le verbe de modalité) va tout à la fin."}],"examples":[{"de":"Glas **wird** nach Farben **getrennt**.","en":"Le verre est trié par couleur."},{"de":"Die Reisenden **werden gebeten**, in Fahrtrichtung rechts auszusteigen.","en":"Les voyageurs sont priés de descendre à droite dans le sens de la marche."},{"de":"In Schweizer Zügen **wird** nicht **geraucht**.","en":"Dans les trains suisses, on ne fume pas."},{"de":"Die Mitarbeitenden **werden** per E-Mail **informiert**.","en":"Les collaborateurs sont informés par e-mail."},{"de":"Leere Batterien **können** im Laden **abgegeben werden**.","en":"Les piles usagées peuvent être rapportées au magasin."},{"de":"Die Steuererklärung **muss** bis Ende März **eingereicht werden**.","en":"La déclaration d'impôts doit être déposée d'ici fin mars."},{"de":"Ich habe gehört, dass das Büro im Januar **renoviert wird**.","en":"J'ai entendu dire que le bureau sera rénové en janvier."},{"de":"Der Laden **ist** am Sonntag **geschlossen**.","en":"Le magasin est fermé le dimanche.","note":"Un état : *sein* + Partizip II."}],"later":"**Passif au Präteritum** : *wurde* + Partizip II, pour le passé (*Das Schulhaus **wurde** 1905 **gebaut**.* – Le collège a été construit en 1905.). Vous le lirez dans des textes sur le passé. Le **passif au Perfekt** (*ist gebaut worden*) et le passif avec *bekommen* (*Ich bekomme das Paket geliefert.* – On me livre le colis.) viendront dans une leçon ultérieure.","selfcheck":{"types":{"choose":{"label":"wird, werden ou ist ?","instruction":"Choisissez le mot entre parenthèses qui convient au trou. Écrivez un seul mot.","example":{"q":"Das Museum ___ heute bis 20 Uhr geöffnet. (wird / ist)","a":"ist","why":"Les heures d'ouverture décrivent un état : *ist geöffnet*."}},"end":{"label":"Compléter la fin","instruction":"Mettez le verbe entre parenthèses au passif (Präsens). Écrivez tous les mots qui vont dans le trou, dans le bon ordre. Si un verbe de modalité figure entre parenthèses, employez-le aussi, à la bonne forme.","example":{"q":"Ich hoffe, dass mein Velo bald ___ (reparieren).","a":"repariert wird","why":"Passif : *repariert* + *wird*. Dans une subordonnée en *dass*, le verbe conjugué va en dernier."}},"rewrite":{"label":"Actif → passif","instruction":"Réécrivez la phrase au passif (Präsens). Si le sujet de la phrase active est *man*, supprimez-le. Tout autre auteur de l'action s'ajoute avec *von*. Écrivez toute la phrase.","example":{"q":"Man repariert die Strasse.","a":"Die Strasse wird repariert.","why":"*die Strasse* devient le sujet ; *man* disparaît."}},"which":{"label":"Passif ou futur ?","instruction":"Dans cette phrase, *werden* sert-il au passif ou au futur ? Écrivez **Passiv** ou **Futur**.","example":{"q":"Ich werde dich morgen anrufen.","a":"Futur","why":"*werden* + infinitif (*anrufen*) = futur (**Futur**)."}}},"items":[{"type":"choose","q":"Das Altpapier ___ jeden zweiten Dienstag abgeholt. (wird / ist)","a":["wird"],"why":"Une chose qui se produit régulièrement est une action : *wird abgeholt*."},{"type":"choose","q":"Keine Sorge, das Formular ___ schon ausgefüllt. Ich habe es gestern gemacht. (wird / ist)","a":["ist"],"why":"Le travail a été fait hier ; maintenant, c'est un état, le résultat : *ist ausgefüllt*."},{"type":"choose","q":"Die Briefe ___ jeden Morgen verteilt. (wird / werden)","a":["werden"],"why":"*die Briefe* est au pluriel, donc *werden*."},{"type":"end","q":"Velos dürfen im Treppenhaus nicht ___ (abstellen).","a":["abgestellt werden"],"why":"Verbe de modalité en position 2, puis Partizip II + *werden* à la fin."},{"type":"end","q":"Im Brief steht, dass die Miete bis Ende Monat ___ (bezahlen, müssen).","a":["bezahlt werden muss"],"why":"Dans une subordonnée en *dass* : Partizip II, *werden*, et le verbe de modalité conjugué *muss* en dernier."},{"type":"end","q":"Weisst du, ob die Pakete heute ___ (liefern)?","a":["geliefert werden"],"why":"*die Pakete* est au pluriel : *werden*, à la fin à cause de *ob*."},{"type":"rewrite","q":"Man sammelt die Batterien im Laden.","a":["Die Batterien werden im Laden gesammelt.","Im Laden werden die Batterien gesammelt."],"why":"*die Batterien* devient le sujet (pluriel, donc *werden*) ; *man* disparaît."},{"type":"rewrite","q":"Der Hauswart repariert die Waschmaschine.","a":["Die Waschmaschine wird vom Hauswart repariert.","Die Waschmaschine wird von dem Hauswart repariert.","Vom Hauswart wird die Waschmaschine repariert."],"why":"L'auteur de l'action revient avec *von* + datif : *vom Hauswart*."},{"type":"rewrite","q":"Man muss den Antrag online ausfüllen.","a":["Der Antrag muss online ausgefüllt werden.","Online muss der Antrag ausgefüllt werden."],"why":"*den Antrag* devient *der Antrag* (nominatif). Verbe de modalité + Partizip II + *werden*."},{"type":"rewrite","q":"Man arbeitet am Sonntag nicht.","a":["Am Sonntag wird nicht gearbeitet.","Es wird am Sonntag nicht gearbeitet."],"why":"Pas de complément, donc pas de sujet : *wird* + Partizip II, avec *es* seulement si la position 1 est vide."},{"type":"which","q":"Der Techniker wird am Montag kommen.","a":["Futur"],"why":"*werden* + infinitif (*kommen*) = futur (**Futur**)."},{"type":"which","q":"Die Heizung wird am Montag repariert.","a":["Passiv"],"why":"*werden* + Partizip II (*repariert*) = passif (**Passiv**)."}]},"sources":[{"id":"aktivpassiv","title":"grammis: Aktiv und Passiv (actif et passif : werden + Partizip II)","url":"https://grammis.ids-mannheim.de/progr@mm/6723"},{"id":"subjekt","title":"grammis: Werden-Passiv mit Subjekt (le complément à l'accusatif devient le sujet)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/930"},{"id":"agens","title":"grammis: Die Formulierung der Agens-Rolle in Aktiv- und Passivsätzen (l'auteur de l'action avec von ou durch)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1361"},{"id":"praep","title":"grammis: Präpositionalphrase (von + datif, durch + accusatif)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"},{"id":"subjektlos","title":"grammis: Subjektloses werden-Passiv (passif sans sujet)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1068"},{"id":"modal","title":"grammis: Fehlende Passivierbarkeit (verbes de modalité avec un infinitif passif)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1616"},{"id":"klammer","title":"grammis: Wortstellung in der Satzklammer (ordre des verbes à la fin de la proposition)","url":"https://grammis.ids-mannheim.de/progr@mm/6840"},{"id":"zustand","title":"grammis: Vertiefung: sein-Passiv (l'état : ist geöffnet)","url":"https://grammis.ids-mannheim.de/progr@mm/6724"},{"id":"hilfsverb","title":"grammis: Hilfsverben im Verbalkomplex (werden pour le futur et pour le passif)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5856"},{"id":"werdenpassiv","title":"grammis: Werden-Passiv (formes à tous les temps, p. ex. wurde verhaftet)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/929"}]},{"id":"genitiv","number":7,"added":"2026-11-06","level":"B1.1","title":"Genitiv","title_en":"Le génitif : à qui est-ce ?","summary":"Indiquer à qui appartient quelque chose (*das Büro des Chefs*) et employer *wegen, trotz, während, statt* à l'écrit.","purpose":["Le génitif indique que quelque chose **appartient à** quelqu'un ou à quelque chose : *das Büro **des Chefs*** (le bureau du chef), *der Sitz **der Firma*** (le siège de l'entreprise).","À l'oral, on dit souvent *von* + datif à la place : *das Büro **vom Chef***. Vous avez quand même besoin du génitif pour lire, écrire des e-mails, parler dans un registre soutenu et passer l'examen B1, ainsi qu'après quelques prépositions comme *wegen* (à cause de) et *trotz* (malgré)."],"logic":["Le groupe au génitif vient **après** le nom qu'il décrit : *das Auto **meiner Schwester***, mot à mot *la voiture de ma sœur*. C'est le même ordre qu'en français avec « de ».","Seuls les **noms propres** se placent devant : *Annas Wohnung* (l'appartement d'Anna). Il n'y a pas d'apostrophe.","Le signal se trouve surtout dans l'**article**. Le masculin et le neutre prennent **des / eines**, et le nom ajoute **-s** ou **-es**. Le féminin et le pluriel prennent **der**, et le nom ne change pas.","*der* a donc un troisième rôle : nominatif masculin, datif féminin et **génitif féminin ou pluriel**. La place dans la phrase vous indique lequel.","Le mot interrogatif est **wessen?** (à qui ?). À l'oral, *wem gehört …?* (à qui appartient … ?) est plus courant."],"rules":[{"title":"Les déterminants au génitif","text":"Apprenez les quatre colonnes comme un schéma : **des / des / der / der**. Les possessifs (*mein, dein, unser* …) et *kein* se déclinent comme *ein*. Le pluriel n'a pas d'article indéfini : on emploie alors *von* + datif (voir Exceptions).","table":{"caption":"Formes du génitif","head":["","masculin","neutre","féminin","pluriel"],"rows":[["défini","**des** Chef**s**","**des** Kind**es**","**der** Firma","**der** Kunden"],["indéfini","**eines** Chef**s**","**eines** Kind**es**","**einer** Firma","—"],["possessif","**meines** Chef**s**","**meines** Kind**es**","**meiner** Firma","**meiner** Kunden"],["négatif","**keines** Chef**s**","**keines** Kind**es**","**keiner** Firma","**keiner** Kunden"]]},"examples":[{"de":"Das ist das Büro **des Chefs**.","en":"C'est le bureau du chef."},{"de":"Die Mitarbeitenden **der Firma** arbeiten oft im Homeoffice.","en":"Les collaborateurs de l'entreprise travaillent souvent en télétravail."},{"de":"Die Wünsche **unserer Kunden** sind uns wichtig.","en":"Les souhaits de nos clients sont importants pour nous."}],"source":"kasus"},{"title":"Les noms masculins et neutres ajoutent -s ou -es","text":["Employez **-es** après un son s (*-s, -ss, -z, -tz, -x*) : *des Hauses, des Platzes, des Fusses*. Les noms en *-nis* doublent le s : *des Ergebnisses*.","Employez **-s** après *-el, -en, -er, -chen, -ling* et après une voyelle : *des Computers, des Mädchens, des Autos*.","Beaucoup de noms d'une syllabe acceptent les deux, et **-es** sonne plus soutenu : *des Tages* (bien plus courant que *des Tags*), *des Kindes* ou *des Kinds*."],"examples":[{"de":"Am Ende **des Monats** bekomme ich meinen Lohn.","en":"À la fin du mois, je reçois mon salaire."},{"de":"Die Ergebnisse **des Projekts** sind sehr gut.","en":"Les résultats du projet sont très bons.","note":"*des Projektes* est aussi correct."},{"de":"Die Miete **des Hauses** ist gestiegen.","en":"Le loyer de la maison a augmenté."}],"source":"s-es"},{"title":"Les masculins faibles prennent -n ou -en, jamais -s","text":"Un groupe de noms masculins, presque tous des personnes ou des animaux, se terminent en **-(e)n** à tous les cas sauf au nominatif : *der Kollege → des Kollegen*. Terminaisons typiques : *-e* (*Kollege, Kunde, Junge*), *-ent* et *-ant* (*Student, Praktikant*), *-ist* (*Polizist*), ainsi que *Mensch, Herr* (*des Herrn*) et *Nachbar*.","examples":[{"de":"Ich habe die Telefonnummer **des Kunden** nicht.","en":"Je n'ai pas le numéro de téléphone du client."},{"de":"Das ist der Laptop **meines Kollegen**.","en":"C'est l'ordinateur portable de mon collègue."}],"source":"weak"},{"title":"Les noms propres se placent devant et ajoutent -s","text":"Placez le nom propre devant le nom et ajoutez **-s**, sans apostrophe : *Peters Büro*. Si le nom propre se termine déjà par un son s (*-s, -ss, -z, -x*), écrivez seulement une apostrophe : *Thomas' Auto*, *Max' Fahrrad*. Le nom qui suit ne prend pas d'article.","examples":[{"de":"**Wessen** Jacke ist das? – Das ist **Marias** Jacke.","en":"À qui est cette veste ? – C'est la veste de Maria."},{"de":"**Thomas'** Präsentation war am besten.","en":"La présentation de Thomas était la meilleure."}],"source":"s-es"},{"title":"Les prépositions suivies du génitif","text":"Ces prépositions sont suivies du génitif à l'écrit : **wegen** (à cause de), **trotz** (malgré), **während** (pendant), **statt** (au lieu de), **innerhalb** (en l'espace de, à l'intérieur de) et **ausserhalb** (en dehors de).","examples":[{"de":"**Wegen einer Störung** fahren heute keine Züge nach Bern.","en":"À cause d'une panne, aucun train ne circule vers Berne aujourd'hui."},{"de":"**Trotz des schlechten Wetters** gehen wir am Wochenende wandern.","en":"Malgré le mauvais temps, nous partons en randonnée ce week-end.","note":"Après un article, les adjectifs au génitif se terminent en **-en** : *des schlechten Wetters*."},{"de":"**Während der Sitzung** bitte keine Handys.","en":"Pas de portables pendant la séance, s'il vous plaît."},{"de":"**Statt eines Taxis** nehmen wir das Tram.","en":"Au lieu d'un taxi, nous prenons le tram."},{"de":"**Innerhalb einer Woche** bekommen Sie eine Antwort.","en":"Vous recevrez une réponse dans un délai d'une semaine."}],"source":"prep"}],"exceptions":[{"title":"wegen + datif à l'oral","text":["À l'oral, beaucoup de gens disent *wegen **dem** Regen* au lieu de *wegen **des** Regens*. C'est très répandu et à peine considéré comme une faute à l'oral, mais à l'écrit *wegen des Regens* reste bien plus courant et c'est le choix sûr. *Trotz* garde plus fermement le génitif.","Avec les pronoms, le datif est normal : *wegen mir* (à cause de moi). L'ancienne forme *meinetwegen* signifie aujourd'hui surtout « ça me va »."],"examples":[{"de":"Wegen **dem** Regen sind wir zu Hause geblieben. (gesprochen)","en":"À cause de la pluie, nous sommes restés à la maison."},{"de":"Wegen **des Regens** sind wir zu Hause geblieben. (geschrieben)","en":"À cause de la pluie, nous sommes restés à la maison."},{"de":"Kommst du **wegen mir**? – Ja, **meinetwegen**.","en":"Tu viens à cause de moi ? – Oui, si tu veux.","note":"Ici, *meinetwegen* signifie « ça me va, si tu veux »."}],"source":"wegen"},{"title":"Pluriel sans article : employer von + datif","text":"Un nom au pluriel sans article ni adjectif ne montre aucune marque de génitif ; l'allemand emploie donc *von* + datif à la place.","examples":[{"de":"die Meinung **von Experten**","en":"l'avis d'experts"},{"de":"Die Preise **von Wohnungen** in Zürich sind sehr hoch.","en":"Les prix des appartements à Zurich sont très élevés."}],"source":"wegen"},{"title":"Certains noms ajoutent -ns","text":"Quelques noms masculins en *-e* ajoutent **-ns** au génitif : *der Name → des Namens*, *der Gedanke → des Gedankens*, *der Glaube → des Glaubens*.","examples":[{"de":"Die Schreibweise **des Namens** ist falsch.","en":"L'orthographe du nom est fausse."}],"source":"weak"},{"title":"Certains mots étrangers et abréviations ne prennent pas de terminaison","text":"Les mots étrangers à finale non accentuée en *-us* ou *-as* restent en général inchangés : *des Zirkus, des Atlas*. Les abréviations peuvent rester sans terminaison : *des LKW* ou *des LKWs*. N'utilisez jamais d'apostrophe pour une terminaison absente : *des Atlas'* est faux.","examples":[{"de":"die Fahrerin **des LKW**","en":"la conductrice du camion"}],"source":"s-es"},{"title":"Les noms féminins ne prennent jamais de terminaison","text":"Au génitif, seul l'article change pour les noms féminins : *die Firma → der Firma*, jamais *der Firmas*.","examples":[{"de":"die Adresse **der Bank**","en":"l'adresse de la banque"}],"source":"kasus"}],"mistakes":[{"wrong":"das Büro der Chef","right":"das Büro **des Chefs**","why":"Masculin : *des* plus *-s* sur le nom."},{"wrong":"Anna's Wohnung","right":"**Annas** Wohnung","why":"L'allemand ne met pas d'apostrophe avant le *-s*. L'apostrophe est une habitude de l'anglais."},{"wrong":"des Kollegens","right":"des **Kollegen**","why":"Les noms faibles prennent *-n*, jamais *-s*."},{"wrong":"der Firmas","right":"der **Firma**","why":"Les noms féminins ne prennent jamais de terminaison au génitif."},{"wrong":"mein Bruders Auto","right":"das Auto **meines Bruders**","why":"Seuls les noms propres se placent avant le nom. Tout le reste vient après lui, contrairement à l'anglais *my brother's car*, mais comme en français (« la voiture de mon frère »)."},{"wrong":"trotz dem Regen (in einem E-Mail)","right":"trotz **des Regens**","why":"À l'écrit, employez le génitif après *trotz* et *wegen*."},{"wrong":"Wegen ich krank bin, bleibe ich zu Hause.","right":"**Weil** ich krank bin, bleibe ich zu Hause.","why":"*wegen* est une préposition : un nom suit (*wegen **meiner Krankheit***). Devant une proposition avec un verbe, employez *weil*."},{"wrong":"Trotz es regnet, gehen wir wandern.","right":"**Obwohl** es regnet, … / **Trotz des Regens** …","why":"*trotz* se construit avec un nom au génitif. Devant une proposition avec un verbe, employez *obwohl*."},{"wrong":"trotz des schlechtes Wetters","right":"trotz des **schlechten** Wetters","why":"Après *des* ou *der* au génitif, l'adjectif se termine toujours en *-en*."}],"examples":[{"de":"Der Sitz **der Firma** ist in Zürich.","en":"Le siège de l'entreprise est à Zurich."},{"de":"Kennst du die Freundin **meines Bruders**?","en":"Tu connais la copine de mon frère ?"},{"de":"Die Farbe **des Autos** gefällt mir nicht.","en":"La couleur de la voiture ne me plaît pas."},{"de":"**Wegen der Baustelle** brauche ich zehn Minuten länger.","en":"À cause du chantier, il me faut dix minutes de plus."},{"de":"**Während der Ferien** ist das Büro geschlossen.","en":"Pendant les vacances, le bureau est fermé."},{"de":"Der Name **des Hotels** ist schwierig.","en":"Le nom de l'hôtel est difficile."},{"de":"Wir wohnen **ausserhalb der Stadt**.","en":"Nous habitons en dehors de la ville."},{"de":"Das ist der Hund **unserer Nachbarn**.","en":"C'est le chien de nos voisins."}],"later":"Le génitif avec adjectifs en détail (*trotz starken Regens*, *wegen guter Arbeit*) viendra avec le thème des terminaisons d'adjectifs.","selfcheck":{"types":{"fill":{"label":"Compléter le trou","instruction":"Mettez les mots entre parenthèses au génitif. Écrivez tout le groupe : déterminant plus nom.","example":{"q":"Das ist das Handy ___ (mein Vater).","a":"meines Vaters","why":"Masculin : *meines* plus *-s* sur le nom."}},"rewrite":{"label":"Oral → écrit","instruction":"Réécrivez la tournure orale avec *von* ou le datif en employant le génitif de l'écrit.","example":{"q":"die Tür von dem Zimmer","a":"die Tür des Zimmers","why":"Neutre : *des* plus *-s*."}},"choose":{"label":"Préposition ou conjonction ?","instruction":"Choisissez le mot entre parenthèses qui convient et écrivez seulement ce mot. Une préposition (*wegen, trotz*) est suivie d'un nom ; une conjonction (*weil, obwohl*) est suivie d'une proposition avec le verbe à la fin.","example":{"q":"Ich bleibe heute zu Hause, ___ es regnet. (wegen / weil)","a":"weil","why":"Une proposition avec un verbe (*regnet*) suit : il faut donc la conjonction *weil*."}}},"items":[{"type":"fill","q":"Die Adresse ___ (die Schule) steht auf der Website.","a":["der Schule"],"why":"Féminin : *der*, sans terminaison sur le nom."},{"type":"fill","q":"Das ist der Schreibtisch ___ (unser Praktikant).","a":["unseres Praktikanten"],"why":"*Praktikant* est un nom faible : il prend *-en*, pas *-s*."},{"type":"fill","q":"___ (wegen / der Regen) bleiben wir heute zu Hause.","a":["Wegen des Regens"],"why":"*wegen* + génitif à l'écrit. *der Regen* est masculin : *des Regens*. À l'oral, on entend aussi *wegen dem Regen*."},{"type":"fill","q":"Ich lese den Bericht ___ (das Team).","a":["des Teams"],"why":"Neutre : *des* plus *-s*."},{"type":"rewrite","q":"die Meinung von meiner Chefin","a":["die Meinung meiner Chefin"],"why":"Possessif féminin : *meiner*."},{"type":"rewrite","q":"während dem Essen","a":["während des Essens"],"why":"*während* est suivi du génitif à l'écrit. *das Essen* est neutre : *des Essens*."},{"type":"choose","q":"___ des Streiks fahren heute keine Busse. (Wegen / Weil)","a":["Wegen"],"why":"Un nom au génitif suit (*des Streiks*) : il faut donc la préposition *wegen*."},{"type":"choose","q":"Ich komme etwas später, ___ ich noch einen Termin habe. (wegen / weil)","a":["weil"],"why":"Une proposition avec le verbe à la fin suit : il faut donc *weil*."},{"type":"choose","q":"___ es kalt ist, gehen wir im See schwimmen. (Trotz / Obwohl)","a":["Obwohl"],"why":"Une proposition avec un verbe suit : il faut donc la conjonction *obwohl*."},{"type":"choose","q":"___ der Kälte gehen wir im See schwimmen. (Trotz / Obwohl)","a":["Trotz"],"why":"Un nom au génitif suit (*der Kälte*) : il faut donc la préposition *trotz*."}]},"sources":[{"id":"kasus","title":"grammis: Kasus (cas)","url":"https://grammis.ids-mannheim.de/vggf/2218"},{"id":"s-es","title":"grammis: Eines Tags oder eines Tages? Formes courtes et longues du génitif","url":"https://grammis.ids-mannheim.de/fragen/26"},{"id":"weak","title":"grammis: Autor, Doktor, Friede, Funke (noms faibles et mixtes)","url":"https://grammis.ids-mannheim.de/fragen/28"},{"id":"prep","title":"grammis: Präpositionalphrase (les prépositions et les cas qu'elles régissent)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? Datif ou génitif","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"konjunktiv-2","number":8,"added":"2026-11-06","level":"B1.1","title":"Konjunktiv","title_en":"Le Konjunktiv II (subjonctif II) : politesse, souhaits et irréel","summary":"Être poli (*Könnten Sie …?*), donner un conseil (*Du solltest …*), exprimer des souhaits et parler de ce qui n'est pas réel (*Wenn ich Zeit hätte, würde ich …*).","purpose":["Les formes verbales normales (l'indicatif) décrivent ce qui **est** réel : *Ich habe Zeit.* (J'ai le temps.) Le Konjunktiv II décrit ce qui n'est **pas** réel, ou pas encore : *Wenn ich Zeit **hätte**, …* (Si j'avais le temps, …).","Vous l'employez aussi tous les jours pour être **poli** et **moins direct** : *Ich **hätte** gern einen Kaffee.* (Je voudrais un café.) *Könnten Sie mir helfen?* (Pourriez-vous m'aider ?) Il correspond en gros au conditionnel français : *je voudrais*, *pourriez-vous* et *tu devrais*."],"logic":["La plupart des verbes emploient **würde + infinitif**, le même schéma qu'un verbe de modalité : *würde* en position 2, l'infinitif à la fin. *Ich **würde** gern in Bern **wohnen**.*","Quelques verbes très courants ont leur **propre forme en un mot**, formée sur le Präteritum avec un Umlaut : *war → **wäre***, *hatte → **hätte***, *konnte → **könnte***. Employez-les au lieu de *würde … sein / haben*.","Les terminaisons sont les mêmes pour tous : *ich -e, du -est, er/sie/es -e, wir -en, ihr -et, sie/Sie -en*.","Pour le **passé**, employez *hätte* ou *wäre* plus le Partizip II, comme au Perfekt : *Ich **hätte** dich **angerufen**.* (Je t'aurais appelé.)"],"rules":[{"title":"Les formes en un mot : wäre, hätte, würde, könnte","text":"Prenez le Präteritum (*war, hatte, wurde, konnte*), ajoutez un Umlaut et employez les terminaisons en *-e*.","table":{"caption":"Konjunktiv II des quatre verbes clés","head":["","sein","haben","werden","können"],"rows":[["ich","**wäre**","**hätte**","**würde**","**könnte**"],["du","wär(e)st","hättest","würdest","könntest"],["er / sie / es","wäre","hätte","würde","könnte"],["wir","wären","hätten","würden","könnten"],["ihr","wär(e)t","hättet","würdet","könntet"],["sie / Sie","wären","hätten","würden","könnten"]]},"examples":[{"de":"Ich **wäre** jetzt gern in den Bergen.","en":"J'aimerais être à la montagne en ce moment."},{"de":"Wir **hätten** gern mehr Ferien.","en":"Nous aimerions avoir plus de vacances."}],"source":"k2"},{"title":"würde + infinitif pour la plupart des autres verbes","text":"*würde* se place en position 2 et l'infinitif va à la fin : c'est la même parenthèse verbale qu'avec *können* ou *müssen*.","examples":[{"de":"Ich **würde** gern mehr **reisen**.","en":"J'aimerais voyager davantage."},{"de":"An deiner Stelle **würde** ich mit der Chefin **sprechen**.","en":"À ta place, je parlerais à la cheffe."}],"source":"flexion"},{"title":"Verbes de modalité : könnte, müsste, dürfte, möchte","text":"Les verbes de modalité prennent un Umlaut au Konjunktiv II : *könnte* (pourrait), *müsste* (devrait, serait obligé de), *dürfte* (pourrait, aurait le droit de), *möchte* (aimerait). **Sauf** *sollte* (devrait) et *wollte* (voudrait) : ils n'ont pas d'Umlaut et ont donc la même forme qu'au Präteritum.","examples":[{"de":"**Dürfte** ich kurz stören?","en":"Est-ce que je pourrais vous déranger un instant ?"},{"de":"Du **solltest** mehr Pausen machen.","en":"Tu devrais faire plus de pauses."},{"de":"Eigentlich **müsste** ich heute noch einkaufen.","en":"En fait, je devrais encore faire les courses aujourd'hui."}],"source":"modal"},{"title":"Quatre emplois : politesse, conseil, souhaits, conditions irréelles","text":["**Demandes polies :** *Könnten Sie …? Würden Sie …? Hätten Sie …? Ich hätte gern …*","**Conseils :** *Du solltest … An deiner Stelle würde ich …*","**Souhaits :** *Ich wäre gern … Ich hätte gern … Wenn ich doch mehr Zeit hätte!*","**Conditions irréelles :** *Wenn ich mehr Geld hätte, würde ich weniger arbeiten.*"],"examples":[{"de":"**Könnten** Sie mir bitte die Rechnung schicken?","en":"Pourriez-vous m'envoyer la facture, s'il vous plaît ?"},{"de":"**Würden** Sie das bitte noch einmal erklären?","en":"Voudriez-vous bien expliquer cela encore une fois ?"},{"de":"Wenn ich doch mehr Zeit **hätte**!","en":"Si seulement j'avais plus de temps !"}],"source":"k2"},{"title":"Phrases avec wenn : verbe à la fin, puis verbe en tête","text":"Dans la subordonnée en *wenn*, le verbe conjugué va à la **fin**. Si la subordonnée en *wenn* vient en premier, la principale **commence par le verbe** : *Wenn ich Zeit hätte, **würde** ich kommen.*","examples":[{"de":"Wenn ich mehr Zeit **hätte**, **würde** ich einen Abendkurs **besuchen**.","en":"Si j'avais plus de temps, je suivrais un cours du soir."},{"de":"Ich **würde** mitkommen, wenn ich nicht arbeiten **müsste**.","en":"Je viendrais avec vous si je ne devais pas travailler."}],"source":"flexion"},{"title":"Le passé : hätte / wäre + Partizip II","text":"Pour parler d'une chose passée qui ne s'est pas produite, employez *hätte* ou *wäre* plus le Partizip II. Le choix entre *hätte* et *wäre* est le même qu'au Perfekt (*haben* ou *sein*).","examples":[{"de":"Wenn der Zug pünktlich **gewesen wäre**, **hätte** ich das Meeting nicht **verpasst**.","en":"Si le train avait été à l'heure, je n'aurais pas manqué la réunion."},{"de":"Das **hätte** ich nicht **gedacht**.","en":"Je ne l'aurais pas cru."}],"source":"k2"}],"exceptions":[{"title":"Les verbes réguliers emploient toujours würde","text":"Pour les verbes réguliers (faibles), le Konjunktiv II en un mot a exactement la même forme que le Präteritum : *ich arbeitete* peut signifier « je travaillais » ou « je travaillerais ». Pour être clair, employez **würde** : *Wenn ich weniger arbeiten **würde**, …*","examples":[{"de":"Wenn er mehr **lernen würde**, **hätte** er bessere Noten.","en":"S'il étudiait davantage, il aurait de meilleures notes."}],"source":"synkretismus"},{"title":"Quelques formes en un mot que vous lirez et entendrez","text":"Les verbes forts ont aussi des formes en un mot. La plupart sonnent soutenues (*käme, ginge*), mais quelques-unes sont aussi courantes à l'oral : *es **gäbe*** (il y aurait), *ich **wüsste*** (je saurais), *ich **bräuchte*** (j'aurais besoin).","examples":[{"de":"**Wüssten** Sie, wo das Sitzungszimmer ist?","en":"Sauriez-vous où se trouve la salle de réunion ?"},{"de":"Es **wäre** gut, wenn es mehr Parkplätze **gäbe**.","en":"Ce serait bien s'il y avait plus de places de parc."}],"source":"flexion"}],"mistakes":[{"wrong":"Ich würde gern einen Kaffee haben.","right":"Ich **hätte** gern einen Kaffee.","why":"Avec *haben* et *sein*, employez *hätte* et *wäre*, pas *würde … haben / sein*. La version avec *würde* n'est pas fausse, mais elle sonne lourde."},{"wrong":"Wenn ich Zeit hätte, ich würde kommen.","right":"Wenn ich Zeit hätte, **würde ich** kommen.","why":"Après une subordonnée en *wenn*, la principale commence par le verbe."},{"wrong":"Wenn ich würde Zeit haben, …","right":"Wenn ich Zeit **hätte**, …","why":"Dans la subordonnée en *wenn*, le verbe va à la fin, et *haben* devient *hätte*."},{"wrong":"Ich könnte gestern nicht kommen.","right":"Ich **konnte** gestern nicht kommen.","why":"*konnte* (sans Umlaut) = pouvait, a pu. *könnte* = pourrait. L'Umlaut change le sens."},{"wrong":"Wenn ich das gewusst würde, …","right":"Wenn ich das gewusst **hätte**, …","why":"Pour le passé, employez *hätte* ou *wäre* plus le Partizip II."},{"wrong":"Wenn ich mehr Geld habe, würde ich weniger arbeiten.","right":"Wenn ich mehr Geld **hätte**, würde ich weniger arbeiten.","why":"Si la situation est irréelle, les deux parties sont irréelles. L'anglais (*if I had*), le français (*si j'avais*), l'italien (*se avessi*) et l'espagnol (*si tuviera*) changent eux aussi le verbe dans la partie en « si »."},{"wrong":"Ich hätte gestern gekommen.","right":"Ich **wäre** gestern gekommen.","why":"Au passé, *hätte* ou *wäre* suit le Perfekt : *ich bin gekommen* → *ich wäre gekommen*. L'anglais emploie *have* pour tous les verbes (*I would have come*) ; l'allemand non, il fait comme le français (« je serais venu »)."},{"wrong":"Du söllst mehr schlafen.","right":"Du **solltest** mehr schlafen.","why":"*sollen* et *wollen* ne prennent pas d'Umlaut au Konjunktiv II : *sollte*, *wollte*."}],"examples":[{"de":"Ich **hätte** gern einen Termin am Dienstag.","en":"J'aimerais un rendez-vous mardi."},{"de":"**Könntest** du mir kurz helfen?","en":"Tu pourrais m'aider un instant ?"},{"de":"Es **wäre** schön, wenn wir uns bald **sehen würden**.","en":"Ce serait bien si on se voyait bientôt."},{"de":"An deiner Stelle **würde** ich das Angebot **annehmen**.","en":"À ta place, j'accepterais l'offre."},{"de":"Ich **wäre** lieber Lehrerin geworden.","en":"J'aurais préféré devenir enseignante."},{"de":"Wenn ich in Zürich **wohnen würde**, **müsste** ich nicht so lange pendeln.","en":"Si j'habitais à Zurich, je n'aurais pas un trajet aussi long."},{"de":"**Hätten** Sie morgen Zeit für ein kurzes Gespräch?","en":"Auriez-vous le temps demain pour un court entretien ?"},{"de":"Wir **sollten** früher losfahren.","en":"Nous devrions partir plus tôt."}],"later":"Le **Konjunktiv I** (*er sei, sie habe*) sert au discours indirect, surtout dans les informations et les textes soutenus. Vous aurez seulement besoin de le reconnaître plus tard, au niveau B2.","selfcheck":{"types":{"fill":{"label":"Compléter le trou","instruction":"Mettez le verbe entre parenthèses au Konjunktiv II. Écrivez un seul mot.","example":{"q":"Ich ___ gern Urlaub. (haben)","a":"hätte","why":"*haben* → *hätte*, un seul mot, sans *würde*."}},"polite":{"label":"Formuler poliment","instruction":"Transformez l'ordre direct en question polie avec *Könnten Sie* ou *Würden Sie*. Écrivez toute la phrase. *bitte* est facultatif.","example":{"q":"Schicken Sie mir den Plan.","a":"Könnten Sie mir bitte den Plan schicken?","why":"*Könnten* vient en premier, et l'infinitif va à la fin."}},"real":{"label":"Réel ou irréel ?","instruction":"Choisissez le verbe entre parenthèses qui convient et écrivez seulement ce mot. Les choses réelles ou possibles prennent la forme normale (*habe, konnte*) ; les choses irréelles, polies ou souhaitées prennent le Konjunktiv II (*hätte, könnte*).","example":{"q":"Wenn es morgen regnet, ___ wir zu Hause. (bleiben / blieben)","a":"bleiben","why":"La pluie demain est possible : les deux parties sont donc au présent normal."}}},"items":[{"type":"fill","q":"Wenn ich du ___, würde ich das Angebot annehmen. (sein)","a":["wäre"],"why":"*sein* → *wäre*. Dans la subordonnée en *wenn*, le verbe va à la fin."},{"type":"fill","q":"___ Sie mir bitte helfen? (können)","a":["Könnten"],"why":"Question polie : *Könnten Sie …?*"},{"type":"fill","q":"Du ___ zum Arzt gehen. (sollen)","a":["solltest"],"why":"Conseil avec *sollen* : *du solltest*, sans Umlaut."},{"type":"fill","q":"Wir ___ gern ein grösseres Büro. (haben)","a":["hätten"],"why":"*wir hätten*, avec la terminaison *-en* pour *wir*."},{"type":"fill","q":"Wenn ich früher aufgestanden ___, hätte ich den Bus erreicht. (sein)","a":["wäre"],"why":"Passé : *aufstehen* forme son Perfekt avec *sein*, donc *wäre aufgestanden*."},{"type":"polite","q":"Geben Sie mir das Formular.","a":["Könnten Sie mir das Formular geben?","Könnten Sie mir bitte das Formular geben?","Könnten Sie mir das Formular bitte geben?","Würden Sie mir das Formular geben?","Würden Sie mir bitte das Formular geben?","Würden Sie mir das Formular bitte geben?"],"why":"*Könnten Sie* ou *Würden Sie* en tête, avec *geben* à la fin."},{"type":"real","q":"Wenn ich morgen Zeit ___, komme ich vorbei. (habe / hätte)","a":["habe"],"why":"Une possibilité réelle : la principale emploie la forme normale (*komme*), la subordonnée en *wenn* aussi."},{"type":"real","q":"Wenn ich mehr Zeit ___, würde ich öfter Sport machen. (habe / hätte)","a":["hätte"],"why":"Irréel : la principale a *würde*, la subordonnée en *wenn* demande donc *hätte*."},{"type":"real","q":"Gestern ___ ich nicht kommen, weil ich krank war. (konnte / könnte)","a":["konnte"],"why":"Un fait réel dans le passé : Präteritum *konnte*, sans Umlaut."},{"type":"real","q":"___ Sie mir bitte das Salz geben? (Konnten / Könnten)","a":["Könnten"],"why":"Une demande polie : Konjunktiv II *Könnten*, avec Umlaut."}]},"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"flexion","title":"grammis: Verbflexion nach Tempus und Modus (formes verbales selon le temps et le mode)","url":"https://grammis.ids-mannheim.de/progr@mm/4047"},{"id":"modal","title":"grammis: Modalverb (verbes de modalité)","url":"https://grammis.ids-mannheim.de/progr@mm/5202"},{"id":"synkretismus","title":"grammis: Formensynkretismus von Konjunktiv und Indikativ (quand subjonctif et indicatif ont la même forme)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/315"}]},{"id":"wegen-weil-deshalb-dann","number":9,"added":"2026-11-09","level":"B1.1","title":"wegen / weil / deshalb / deswegen / darum / dann","title_en":"Cause ou conséquence ? Quels mots s'échangent, et pourquoi dann est différent","summary":"Dites pourquoi avec *wegen* (+ nom), *weil* (verbe à la fin) ou *denn* ; dites ce qui en découle avec *deshalb, deswegen, darum* ; et gardez *dann* pour « puis, ensuite ».","purpose":["Donner des raisons est l'une des choses que vous faites le plus en allemand : vous excuser, expliquer une décision, argumenter dans une lettre ou une discussion de niveau B1. L'allemand a plusieurs mots pour cela. Ils diffèrent moins par le **sens** que par la **grammaire** : ce qui vient après eux, et où va le verbe.","Ce thème s'appuie sur le thème 5 (*weil, denn, deshalb*) et le thème 7 (*wegen* + génitif). Il exprime une même situation de toutes les façons, montre quels mots vous pouvez échanger et explique pourquoi *dann* n'en fait pas partie, bien qu'il leur ressemble à l'écrit comme à l'oral."],"logic":["Deux questions décident du mot. **1. Direction :** le mot introduit-il la **cause** (*pourquoi ?*) ou la **conséquence** (*et donc, que se passe-t-il ?*) ? **2. Ce qui suit :** un nom, une subordonnée avec le verbe à la fin, ou une phrase normale ?","**Cause :** **wegen** + un nom (*wegen des Regens*), **weil** + une subordonnée avec le verbe à la fin (*weil es regnet*), **denn** + une phrase normale (*denn es regnet*).","**Conséquence :** **deshalb**, **deswegen** et **darum** signifient tous *c'est pourquoi, donc*. Ils renvoient à la cause : *deswegen* est littéralement *des* + *wegen*, « à cause de cela ». En position 1, le verbe vient juste après eux.","**dann** n'est d'aucun côté. Il signifie *puis, ensuite* : ce qui vient **après dans le temps** (*zuerst … dann*), ou ce qui suit **si** une condition est remplie (*wenn … dann*). Il ne dit jamais *pourquoi*.","Test rapide : si la phrase précédente répond à ***Warum?***, utilisez *deshalb*. Si elle répond à ***Wann?*** ou à ***Unter welcher Bedingung?***, utilisez *dann*."],"rules":[{"title":"Une situation, dite de toutes les façons","text":["Prenez une cause et une conséquence : *Der Zug hat Verspätung* (cause) → *ich komme zu spät* (conséquence). Chaque mot les relie différemment.","*dann* ne convient que si vous transformez la cause en **condition** (*wenn …*) : c'est alors une possibilité, pas un fait."],"table":{"caption":"Der Zug hat Verspätung → ich komme zu spät","head":["mot","ce qui suit","exemple"],"rows":[["**wegen**","un nom (préposition ; génitif, à l’oral souvent datif)","**Wegen der Verspätung** komme ich zu spät."],["**weil**","une subordonnée, verbe à la fin (conjonction)","Ich komme zu spät, **weil** der Zug Verspätung **hat**."],["**denn**","une phrase normale, verbe en position 2 (conjonction)","Ich komme zu spät, **denn** der Zug **hat** Verspätung."],["**deshalb**, **deswegen**, **darum**","le verbe, juste après (adverbe)","Der Zug hat Verspätung, **deshalb komme** ich zu spät."],["**dann**","le verbe, juste après (adverbe de temps ou de condition)","**Wenn** der Zug Verspätung hat, **dann komme** ich zu spät."]]},"examples":[{"de":"**Wegen der Verspätung** komme ich zu spät.","en":"À cause du retard, j'arrive en retard."},{"de":"Ich komme zu spät, **weil** der Zug Verspätung **hat**.","en":"J'arrive en retard parce que le train a du retard."},{"de":"Ich komme zu spät, **denn** der Zug **hat** Verspätung.","en":"J'arrive en retard, car le train a du retard."},{"de":"Der Zug hat Verspätung, **deshalb komme** ich zu spät.","en":"Le train a du retard, c'est pourquoi j'arrive en retard."},{"de":"**Wenn** der Zug Verspätung hat, **dann komme** ich zu spät.","en":"Si le train a du retard, alors j'arrive en retard.","note":"Ici, le retard n'est qu'une possibilité. *dann* donne la conséquence de la condition, pas une cause."}],"source":"ursache"},{"title":"Lesquels pouvez-vous échanger ?","text":["**deshalb**, **deswegen** et **darum** s'échangent librement : même sens, même place, même ordre des mots. Tous trois sont de l'allemand standard. À l'écrit, *deshalb* est de loin le plus fréquent : dans le corpus de journaux et de livres allemands de l'IDS (DeReKo), il est environ cinq fois plus courant que *deswegen*.","**weil**, **denn** et **wegen** donnent tous la cause, mais la grammaire qui suit change. **weil/denn** et **deshalb** décrivent le même lien depuis des côtés opposés : inversez les deux moitiés. **dann** ne s'échange avec aucun d'eux."],"table":{"caption":"Échangeable ou non ?","head":["échange","même sens ?","ce qui change"],"rows":[["**deshalb** ↔ **deswegen** ↔ **darum**","oui","rien"],["**weil** ↔ **denn**","oui","le verbe : à la fin après *weil*, en position 2 après *denn*. Seul *weil* peut venir en premier ou répondre à *Warum?*"],["**weil** ↔ **wegen**","oui","*wegen* prend un nom au lieu d’une proposition : *weil es regnet* → *wegen des Regens*"],["**weil** / **denn** ↔ **deshalb**","oui, vu de l’autre côté","les deux moitiés s'inversent : d'abord la cause, puis *deshalb* + la conséquence"],["**dann** ↔ l'un d'eux","non","*dann* signifie *puis, ensuite* : ordre dans le temps, ou conséquence d'une condition en *wenn*"]]},"examples":[{"de":"Es regnet. **Deshalb** bleiben wir zu Hause.","en":"Il pleut. C'est pourquoi nous restons à la maison."},{"de":"Es regnet. **Darum** bleiben wir zu Hause.","en":"Il pleut. Nous restons donc à la maison.","note":"Même phrase qu'avec *deshalb* : rien d'autre ne change."},{"de":"Wir bleiben zu Hause, **weil** es **regnet**.","en":"Nous restons à la maison parce qu'il pleut."},{"de":"**Wegen des Regens** bleiben wir zu Hause.","en":"À cause de la pluie, nous restons à la maison."}],"source":"deshalb"},{"title":"wegen + nom : la cause en quelques mots","text":["**wegen** (à cause de) est une préposition : il lui faut un **nom**, pas une subordonnée. À l'écrit, il se construit avec le **génitif** (*wegen **des** Streiks, wegen **der** Baustelle*). Pour le datif à l'oral, voir les exceptions ci-dessous et le thème 7.","Pour transformer une subordonnée en *weil* en groupe avec *wegen*, cherchez le nom qu'elle contient : *weil es regnet* → *wegen des **Regens***, *weil ich erkältet bin* → *wegen meiner **Erkältung***."],"examples":[{"de":"**Wegen des Streiks** fahren heute keine Busse.","en":"À cause de la grève, il n'y a pas de bus aujourd'hui."},{"de":"Das Konzert findet **wegen des Regens** in der Halle statt.","en":"À cause de la pluie, le concert a lieu dans la salle."},{"de":"**Wegen einer Baustelle** ist die Strasse bis Freitag gesperrt.","en":"À cause d'un chantier, la route est fermée jusqu'à vendredi."},{"de":"**Wegen meiner Erkältung** kann ich heute nicht ins Training.","en":"À cause de mon rhume, je ne peux pas aller à l'entraînement aujourd'hui."},{"de":"Ich rufe **wegen der Wohnung** an.","en":"J'appelle au sujet de l'appartement.","note":"Quand vous dites pourquoi vous appelez ou écrivez, le français dit « au sujet de » et l'anglais *about* ; l'allemand dit quand même *wegen*."}],"source":"wegen"},{"title":"weil : verbe à la fin, et la réponse à Warum?","text":["**weil** introduit une subordonnée : le verbe conjugué va à la **fin**. Si la subordonnée en *weil* vient en premier, la principale commence par son verbe.","**weil** est le seul de ces mots qui peut répondre seul à une question en ***Warum?*** : *Warum? – Weil …*."],"examples":[{"de":"Ich komme heute später, **weil** mein Zug Verspätung **hat**.","en":"Aujourd'hui, j'arrive plus tard parce que mon train a du retard."},{"de":"**Weil** die Miete so hoch **ist**, **suchen** wir eine neue Wohnung.","en":"Comme le loyer est si élevé, nous cherchons un nouvel appartement."},{"de":"Warum lernst du Deutsch? – **Weil** ich in Zürich **arbeite**.","en":"Pourquoi apprends-tu l'allemand ? – Parce que je travaille à Zurich."},{"de":"Sie hat die Stelle bekommen, **weil** sie gut Französisch **spricht**.","en":"Elle a obtenu le poste parce qu'elle parle bien français."},{"de":"Ich kann nicht mitkommen, **weil** ich heute Abend arbeiten **muss**.","en":"Je ne peux pas venir parce que je dois travailler ce soir.","note":"Avec deux verbes, le verbe conjugué (*muss*) va à la fin."}],"source":"kausal"},{"title":"denn : même sens que weil, ordre des mots normal","text":["**denn** (car) donne aussi la cause, mais il ne déplace pas le verbe : il se place en **position 0**, donc le verbe reste en **position 2**.","La partie avec *denn* vient toujours **après** la phrase qu'elle explique. Elle peut commencer une nouvelle phrase (*… . Denn …*), mais elle ne peut ni venir en premier ni répondre seule à *Warum?* : utilisez *weil* pour cela."],"examples":[{"de":"Ich nehme den Zug, **denn** die Autobahn **ist** um diese Zeit immer voll.","en":"Je prends le train, car l'autoroute est toujours saturée à cette heure-ci."},{"de":"Nimm einen Schirm mit, **denn** am Nachmittag **soll** es regnen.","en":"Prends un parapluie, car il devrait pleuvoir l'après-midi."},{"de":"Wir essen heute zu Hause. **Denn** das Restaurant **ist** am Montag geschlossen.","en":"Aujourd'hui, nous mangeons à la maison. Car le restaurant est fermé le lundi.","note":"Une nouvelle phrase avec *denn* est possible, tant qu'elle vient après la phrase qu'elle explique."}],"source":"denn"},{"title":"deshalb : le choix sûr pour la conséquence","text":["**deshalb** (c'est pourquoi, donc) introduit la **conséquence** et renvoie à la cause qui précède. C'est un adverbe : en position 1, le **verbe vient juste après lui**, ou bien il se place au milieu de la phrase, après le verbe.","À l'écrit, c'est le plus courant des trois : dans le doute, utilisez *deshalb*."],"examples":[{"de":"Mein Zug hatte Verspätung. **Deshalb bin** ich zu spät gekommen.","en":"Mon train avait du retard. C'est pourquoi je suis arrivé en retard."},{"de":"Die Kita schliesst um sechs. Ich **muss deshalb** pünktlich gehen.","en":"La crèche ferme à six heures. Je dois donc partir à l'heure."},{"de":"Ich möchte in der Pflege arbeiten. **Deshalb mache** ich eine Ausbildung.","en":"J'aimerais travailler dans les soins. C'est pourquoi je fais une formation."},{"de":"Am Samstag ist der Coop sehr voll, **deshalb kaufe** ich am Freitag ein.","en":"Le samedi, il y a beaucoup de monde à la Coop, c'est pourquoi je fais mes courses le vendredi."},{"de":"Der Lift ist kaputt. Wir **nehmen deshalb** die Treppe.","en":"L'ascenseur est en panne. Nous prenons donc l'escalier."}],"source":"deshalb"},{"title":"deswegen : « à cause de cela »","text":"**deswegen** signifie exactement la même chose que *deshalb* et fonctionne de la même façon : verbe juste après lui en position 1, ou au milieu de la phrase. Ses éléments montrent le sens : *des* + *wegen*, « à cause de cela ». C'est de l'allemand standard, à l'oral comme à l'écrit.","examples":[{"de":"Ich habe schlecht geschlafen. **Deswegen bin** ich heute so müde.","en":"J'ai mal dormi. C'est pour ça que je suis si fatigué aujourd'hui."},{"de":"Es hat die ganze Nacht geschneit, **deswegen fahren** die Trams langsam.","en":"Il a neigé toute la nuit, c'est pour ça que les trams roulent lentement."},{"de":"Meine Kollegin ist krank. Ich **übernehme deswegen** ihre Kunden.","en":"Ma collègue est malade. Je reprends donc ses clients."},{"de":"Die Wohnung liegt direkt am Bahnhof. **Deswegen ist** sie so teuer.","en":"L'appartement est juste à côté de la gare. C'est pour ça qu'il est si cher."},{"de":"Sie spricht vier Sprachen. **Deswegen arbeitet** sie am Empfang.","en":"Elle parle quatre langues. C'est pour ça qu'elle travaille à la réception."}],"source":"deswegen"},{"title":"darum : même sens, mais aussi d'autres emplois","text":["**darum** signifie aussi *c'est pourquoi, donc*, avec le même ordre des mots que *deshalb*.","Attention : *darum* a d'autres sens qui n'ont rien à voir avec la cause, comme *Es geht darum* (il s'agit de) ou *sich darum kümmern* (s'en occuper). Voir les exceptions ci-dessous."],"examples":[{"de":"Im Zug kann ich lesen. **Darum fahre** ich lieber Zug als Auto.","en":"Dans le train, je peux lire. C'est pourquoi je préfère le train à la voiture."},{"de":"Ich mag meinen Job. **Darum bleibe** ich in der Firma.","en":"J'aime mon travail. C'est pourquoi je reste dans l'entreprise."},{"de":"Es war schon spät, **darum haben** wir ein Taxi genommen.","en":"Il était déjà tard, nous avons donc pris un taxi."},{"de":"Mit dem Velo bin ich in der Stadt am schnellsten. Ich **fahre darum** jeden Tag mit dem Velo zur Arbeit.","en":"En ville, c'est à vélo que je suis le plus rapide. Je vais donc tous les jours au travail à vélo."},{"de":"Der Kurs war sehr gut. **Darum empfehle** ich ihn weiter.","en":"Le cours était très bien. C'est pourquoi je le recommande."}],"source":"darum"},{"title":"deshalb …, weil : insister sur la cause","text":"Vous pouvez employer *deshalb* (ou *deswegen*, *darum*) et *weil* dans la même phrase. *deshalb* annonce alors la subordonnée en *weil* et insiste : c'est **cette** raison-là, pas une autre. Il s'accompagne souvent de *nur* ou *gerade* (seulement, justement).","examples":[{"de":"Ich bin **deshalb** nach Bern gezogen, **weil** meine Partnerin hier arbeitet.","en":"Si j'ai déménagé à Berne, c'est parce que ma compagne travaille ici."},{"de":"Er hat die Stelle nur **deswegen** bekommen, **weil** er Italienisch spricht.","en":"Il n'a obtenu le poste que parce qu'il parle italien."},{"de":"**Weil** mir kalt ist, **deshalb** ziehe ich die Winterjacke an.","en":"Comme j'ai froid, je mets ma veste d'hiver.","note":"Après une subordonnée en *weil*, *deshalb* reprend la cause. Vous pouvez l'omettre : *Weil mir kalt ist, ziehe ich …*"}],"source":"korrelat"},{"title":"dann : puis, pas parce que","text":["**dann** est un adverbe de **temps** : il dit ce qui vient **ensuite** (*zuerst … dann*) ou à un moment ultérieur. Après une subordonnée en **wenn**, il donne ce qui se passe **si** la condition est remplie (*wenn … dann*). Dans une réponse, il signifie *dans ce cas*.","L'ordre des mots est le même qu'avec *deshalb* : en position 1, le verbe vient juste après lui. Mais le sens est différent : *dann* n'explique jamais **pourquoi**."],"examples":[{"de":"Zuerst gehe ich zur Post, **dann gehe** ich einkaufen.","en":"D'abord je vais à la poste, ensuite je vais faire les courses."},{"de":"Wir essen um sieben. **Dann schauen** wir einen Film.","en":"Nous mangeons à sept heures. Ensuite, nous regardons un film."},{"de":"**Wenn** es morgen regnet, **dann bleiben** wir zu Hause.","en":"S'il pleut demain, alors nous restons à la maison."},{"de":"**Wenn** Sie Fragen haben, **dann rufen** Sie mich an.","en":"Si vous avez des questions, alors appelez-moi."},{"de":"– Der letzte Bus ist schon weg. – **Dann nehmen** wir ein Taxi.","en":"– Le dernier bus est déjà parti. – Dans ce cas, nous prenons un taxi.","note":"Une réaction à une nouvelle : *dann* = « dans ce cas ». Il présente une décision, pas une explication."}],"source":"dann"},{"title":"dann, denn ou deshalb ?","text":"*dann* et *denn* ne diffèrent que d'une lettre, et le français *alors* ou l'anglais *then* brouillent *dann* et *deshalb*. Vérifiez le sens : **denn** = *car* (la cause suit), **deshalb** = *c'est pourquoi* (la conséquence suit), **dann** = *puis, ensuite* (ce qui vient après, ou ce qui suit un *wenn*).","table":{"caption":"Trois mots qui se ressemblent","head":["mot","sens","ce qui vient après","exemple"],"rows":[["**denn**","car, parce que (cause)","une phrase normale, verbe en position 2","Ich bleibe zu Hause, **denn ich bin** krank."],["**deshalb**","c'est pourquoi (conséquence)","verbe juste après lui","Ich bin krank, **deshalb bleibe** ich zu Hause."],["**dann**","puis, alors (temps, condition)","verbe juste après lui","Ich gehe zum Arzt, **dann gehe** ich nach Hause."]]},"examples":[{"de":"Ich bleibe zu Hause, **denn** ich bin krank.","en":"Je reste à la maison, car je suis malade."},{"de":"Ich bin krank, **deshalb** bleibe ich zu Hause.","en":"Je suis malade, c'est pourquoi je reste à la maison."},{"de":"Ich gehe zum Arzt, **dann** gehe ich nach Hause.","en":"Je vais chez le médecin, ensuite je rentre à la maison."},{"de":"**Wenn** ich krank bin, **dann** bleibe ich zu Hause.","en":"Si je suis malade, alors je reste à la maison."}],"source":"dann"}],"exceptions":[{"title":"wegen + datif à l'oral","text":"À l'oral, beaucoup de gens disent *wegen **dem** Regen* au lieu de *wegen **des** Regens*, en Suisse aussi. À l'oral, on ne le compte guère comme une faute, mais à l'écrit, le génitif est le choix sûr. Avec les pronoms, le datif est normal : *wegen mir*. Plus de détails au thème 7.","examples":[{"de":"Wegen **dem** Stau bin ich zu spät gekommen. (gesprochen)","en":"À cause de l'embouteillage, je suis arrivé en retard."},{"de":"Wegen **des Staus** bin ich zu spät gekommen. (geschrieben)","en":"À cause de l'embouteillage, je suis arrivé en retard."}],"source":"wegen"},{"title":"Darum! comme réponse","text":"*Darum!* seul, en réponse à *Warum?*, est familier et sec : il refuse de donner une raison, comme « Parce que ! » ou « C'est comme ça ! » (en anglais « Because I said so! » ou « Just because! »). Pour donner une vraie raison, répondez avec *weil*.","examples":[{"de":"– Warum muss ich das machen? – Darum!","en":"– Pourquoi est-ce que je dois faire ça ? – Parce que c'est comme ça !"},{"de":"– Warum kommst du nicht mit? – **Weil** ich keine Zeit **habe**.","en":"– Pourquoi tu ne viens pas ? – Parce que je n'ai pas le temps."}],"source":"duden-darum"},{"title":"denn dans une question : aucune cause","text":"Dans une **question**, *denn* est une particule, pas un mot de cause. Il marque l'intérêt ou la surprise, et le français ne le traduit souvent pas (ou par « donc », « alors »). Le *denn* qui signifie *car* n'apparaît que dans les affirmations.","examples":[{"de":"Wo bist du **denn**?","en":"Où es-tu donc ?"},{"de":"Was ist **denn** los?","en":"Qu'est-ce qui se passe ?"},{"de":"Wie heisst **denn** deine neue Chefin?","en":"Et comment s'appelle ta nouvelle cheffe ?"}],"source":"partikel"},{"title":"darum sans cause : es geht darum, sich darum kümmern","text":"*darum* est aussi *da(r)* + *um* : il remplace *um* + une chose avec les verbes et expressions qui se construisent avec *um*. Il signifie alors *en, de cela, pour cela* et ne donne aucune cause.","examples":[{"de":"Es geht **darum**, eine Lösung zu finden.","en":"Il s'agit de trouver une solution."},{"de":"Kannst du dich **darum** kümmern?","en":"Tu peux t'en occuper ?","note":"*sich um etwas kümmern* → *sich darum kümmern*."}],"source":"darum"}],"mistakes":[{"wrong":"Ich komme zu spät, dann der Zug hat Verspätung.","right":"Ich komme zu spät, **denn** der Zug hat Verspätung.","why":"*dann* (puis) et *denn* (car) se ressemblent à l'écrit comme à l'oral. Pour une cause, écrivez *denn*, avec un *e*."},{"wrong":"Ich war krank. Dann bin ich nicht zur Arbeit gegangen.","right":"Ich war krank. **Deshalb** bin ich nicht zur Arbeit gegangen.","why":"*dann* dit seulement ce qui s'est passé ensuite, pas pourquoi. L'italien *allora*, le français *alors* et l'espagnol *entonces* peuvent signifier à la fois « ensuite » et « c'est pourquoi », et l'anglais *then* peut aussi exprimer une conséquence. L'allemand les sépare : *dann* pour le temps, *deshalb* pour la conséquence."},{"wrong":"Deswegen ich komme zu spät.","right":"Deswegen **komme ich** zu spät.","why":"*deswegen*, *deshalb* et *darum* occupent la position 1, donc le verbe vient juste après. L'anglais *so I'm late*, le français *c'est pourquoi je …*, l'italien *per questo io …* et l'espagnol *por eso yo …* mettent d'abord le sujet ; l'allemand non."},{"wrong":"Wegen der Zug Verspätung hat, komme ich zu spät.","right":"**Weil** der Zug Verspätung hat, komme ich zu spät. / **Wegen der Verspätung** komme ich zu spät.","why":"*wegen* se construit avec un nom, *weil* avec une subordonnée. La même distinction existe en français (*à cause de* / *parce que*), en anglais (*because of* / *because*), en italien (*a causa di* / *perché*) et en espagnol (*a causa de* / *porque*), mais les apprenants mélangent souvent la paire allemande."},{"wrong":"Warum kommst du nicht? – Denn ich bin krank.","right":"Warum kommst du nicht? – **Weil** ich krank **bin**.","why":"Seul *weil* peut répondre seul à *Warum?*. Une partie avec *denn* a toujours besoin d'une phrase devant elle."},{"wrong":"Ich bin müde, deshalb habe ich schlecht geschlafen.","right":"Ich habe schlecht geschlafen, **deshalb** bin ich müde.","why":"*deshalb* introduit la **conséquence** ; la cause vient avant. Mal dormir est la cause, être fatigué la conséquence. Pour garder l'ordre de la phrase fausse, utilisez *weil* : *Ich bin müde, weil ich schlecht geschlafen habe.*"},{"wrong":"Wegen dem Streik fahren heute keine Busse. (in einem Brief)","right":"Wegen **des Streiks** fahren heute keine Busse.","why":"À l'oral, le datif après *wegen* est courant, mais dans une lettre, un e-mail ou à l'examen, utilisez le génitif."}],"examples":[{"de":"**Wegen der Hitze** arbeiten wir heute nur bis drei.","en":"À cause de la chaleur, nous ne travaillons que jusqu'à trois heures aujourd'hui."},{"de":"Ich rufe dich später an, **weil** ich gerade in einer Sitzung **bin**.","en":"Je te rappelle plus tard, parce que je suis en réunion en ce moment."},{"de":"Wir nehmen das Tram, **denn** in der Altstadt gibt es keine Parkplätze.","en":"Nous prenons le tram, car il n'y a pas de places de parc dans la vieille ville."},{"de":"Mein Velo hat einen Platten. **Deshalb** komme ich heute zu Fuss.","en":"Mon vélo a un pneu crevé. C'est pourquoi je viens à pied aujourd'hui."},{"de":"Die Prüfung ist im Dezember. **Deswegen** lerne ich jeden Abend.","en":"L'examen est en décembre. C'est pour ça que j'étudie tous les soirs."},{"de":"Die Wohnung hat einen Balkon. **Darum** haben wir sie genommen.","en":"L'appartement a un balcon. C'est pour cela que nous l'avons pris."},{"de":"Zuerst mache ich die Hausaufgaben, **dann** gehe ich ins Fitness.","en":"D'abord je fais mes devoirs, ensuite je vais au fitness."},{"de":"**Wenn** du Hilfe brauchst, **dann** sag es mir.","en":"Si tu as besoin d'aide, alors dis-le-moi."}],"later":"D'autres mots de cause viennent au B1.2 et au B2 : *da* (comme, puisque : verbe à la fin, surtout à l'écrit, ne répond pas à *Warum?*), *daher* (= *deshalb*, plus soutenu), *nämlich* (la cause, après le verbe : *Ich komme nicht, ich bin **nämlich** krank.*), *aus diesem Grund* (pour cette raison), *aufgrund* + génitif (un *wegen* soutenu) et *sodass* (de sorte que).","selfcheck":{"types":{"choose":{"label":"Quel mot ?","instruction":"Écrivez le mot qui manque : *wegen*, *weil*, *denn*, *deshalb* ou *dann*. N'écrivez qu'un seul mot. Utilisez deux indices : le sens (cause, conséquence, ordre dans le temps ou condition) et ce qui suit le trou (un nom, une subordonnée avec le verbe à la fin, le sujet ou le verbe). Là où *deshalb* convient, *deswegen* et *darum* sont aussi justes.","example":{"q":"Ich trage eine Jacke, ___ es kalt ist.","a":"weil","why":"Une cause, et le verbe *ist* est à la fin → *weil*."}},"join":{"label":"Reliez les phrases","instruction":"Reliez les deux phrases avec le mot entre parenthèses. Changez l'ordre des mots là où ce mot l'exige. Une subordonnée en *weil* peut venir en premier ou en second ; *deshalb, deswegen, darum* et *dann* peuvent se placer en position 1 ou après le verbe. Écrivez toute la nouvelle phrase.","example":{"q":"Es ist schon spät. Ich nehme ein Taxi. (deshalb)","a":"Es ist schon spät, deshalb nehme ich ein Taxi.","why":"*deshalb* introduit la conséquence, et le verbe vient juste après : *nehme ich*."}},"rewrite":{"label":"Dites-le autrement","instruction":"Dites la même chose avec le mot entre parenthèses. Gardez le sens ; changez la grammaire qu'il exige : un nom après *wegen*, le verbe à la fin après *weil*, l'ordre des mots normal après *denn*, le verbe juste après *deshalb, deswegen, darum*. Avec *deshalb* et ses partenaires, la cause vient en premier. Écrivez toute la nouvelle phrase.","example":{"q":"Weil es schneit, fahren die Trams langsam. (wegen)","a":"Wegen des Schnees fahren die Trams langsam.","why":"*wegen* a besoin d'un nom : *es schneit* → *der Schnee*, au génitif *des Schnees*."}}},"items":[{"type":"choose","q":"Ich komme heute später, ___ mein Zug Verspätung hat.","a":["weil"],"why":"Une cause, et le verbe (*hat*) est à la fin → *weil*."},{"type":"choose","q":"Ich komme heute später, ___ mein Zug hat Verspätung.","a":["denn"],"why":"Une cause, mais le sujet vient ensuite et le verbe reste en position 2 → *denn*."},{"type":"choose","q":"Ich habe die B1-Prüfung bestanden. ___ bin ich heute so glücklich.","a":["Deshalb","Deswegen","Darum"],"why":"Avoir réussi est la cause, être heureux la conséquence, et le verbe vient juste après le trou → *deshalb* (ou *deswegen*, *darum*)."},{"type":"choose","q":"Zuerst kaufe ich ein, ___ koche ich.","a":["dann"],"why":"*zuerst* (d'abord) appelle ce qui vient ensuite dans le temps → *dann*. Faire les courses n'est pas la raison de cuisiner."},{"type":"choose","q":"___ des Streiks fahren heute keine Busse.","a":["Wegen"],"why":"Un nom au génitif suit (*des Streiks*), sans verbe à lui → la préposition *wegen*."},{"type":"choose","q":"Wenn es morgen regnet, ___ bleiben wir zu Hause.","a":["dann"],"why":"Après une condition en *wenn*, *dann* donne ce qui se passe si elle est remplie. *deshalb* a besoin d'un vrai fait comme cause, pas d'un « si »."},{"type":"choose","q":"Warum lernst du Deutsch? – ___ ich in Zürich arbeite.","a":["Weil"],"why":"Une réponse seule à *Warum?*, avec le verbe (*arbeite*) à la fin → *weil*. *denn* ne peut pas répondre seul à une question."},{"type":"join","q":"Die Kita schliesst um 18 Uhr. Ich muss pünktlich gehen. (deswegen)","a":["Die Kita schliesst um 18 Uhr, deswegen muss ich pünktlich gehen.","Die Kita schliesst um 18 Uhr, ich muss deswegen pünktlich gehen.","Die Kita schliesst um 18 Uhr und deswegen muss ich pünktlich gehen.","Die Kita schliesst um 18 Uhr und ich muss deswegen pünktlich gehen."],"why":"*deswegen* introduit la conséquence ; le verbe vient juste après (*muss ich*), ou bien *deswegen* se place après le verbe."},{"type":"join","q":"Ich gehe zuerst einkaufen. Ich koche. (dann)","a":["Ich gehe zuerst einkaufen, dann koche ich.","Ich gehe zuerst einkaufen und dann koche ich."],"why":"Ordre dans le temps : *dann* en position 1, verbe juste après (*koche ich*)."},{"type":"join","q":"Ich trinke keinen Kaffee mehr. Ich schlafe schlecht. (weil)","a":["Ich trinke keinen Kaffee mehr, weil ich schlecht schlafe.","Weil ich schlecht schlafe, trinke ich keinen Kaffee mehr."],"why":"*weil* envoie le verbe (*schlafe*) à la fin. Si la subordonnée en *weil* vient en premier, la principale commence par son verbe (*trinke*)."},{"type":"rewrite","q":"Ich bleibe zu Hause, weil ich krank bin. (deshalb)","a":["Ich bin krank, deshalb bleibe ich zu Hause.","Ich bin krank, ich bleibe deshalb zu Hause.","Ich bin krank und deshalb bleibe ich zu Hause.","Ich bin krank und bleibe deshalb zu Hause.","Ich bin krank und ich bleibe deshalb zu Hause."],"why":"Même lien, vu de l'autre côté : la cause (*ich bin krank*) vient en premier, puis *deshalb* + verbe + la conséquence."},{"type":"rewrite","q":"Wegen des Regens bleiben wir zu Hause. (weil)","a":["Weil es regnet, bleiben wir zu Hause.","Wir bleiben zu Hause, weil es regnet."],"why":"*weil* a besoin d'une subordonnée : *der Regen* → *es regnet*, avec le verbe à la fin."},{"type":"rewrite","q":"Ich nehme den Zug, weil die Autobahn voll ist. (denn)","a":["Ich nehme den Zug, denn die Autobahn ist voll."],"why":"*denn* garde l'ordre des mots normal : le verbe (*ist*) reste en position 2, après le sujet."},{"type":"rewrite","q":"Der Lift ist kaputt. Deshalb nehmen wir die Treppe. (darum)","a":["Der Lift ist kaputt. Darum nehmen wir die Treppe.","Der Lift ist kaputt, darum nehmen wir die Treppe.","Der Lift ist kaputt. Wir nehmen darum die Treppe.","Der Lift ist kaputt, wir nehmen darum die Treppe."],"why":"*deshalb* et *darum* s'échangent tels quels : rien d'autre ne change."},{"type":"rewrite","q":"Weil es einen Stau gab, bin ich zu spät gekommen. (wegen)","a":["Wegen des Staus bin ich zu spät gekommen.","Ich bin wegen des Staus zu spät gekommen.","Wegen eines Staus bin ich zu spät gekommen.","Ich bin wegen eines Staus zu spät gekommen.","Wegen dem Stau bin ich zu spät gekommen.","Ich bin wegen dem Stau zu spät gekommen."],"why":"*wegen* + nom : *einen Stau* → *des Staus* (génitif, pour l'écrit). *wegen dem Stau* passe très bien à l'oral."}]},"sources":[{"id":"ursache","title":"grammis: Ursache und Folge (weil marque la cause, deswegen la conséquence)","url":"https://grammis.ids-mannheim.de/progr@mm/6767"},{"id":"kausal","title":"grammis: Kausalsätze (weil répond aux questions en warum ; da ne le peut pas)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2102"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? Datif ou génitif","url":"https://grammis.ids-mannheim.de/fragen/67"},{"id":"weil","title":"grammis, dictionnaire des connecteurs : weil (subjoncteur causal, verbe à la fin)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, dictionnaire des connecteurs : denn (causal, position 0)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"adverb","title":"grammis: Nicht nacherstfähige Adverbkonnektoren (deshalb, darum : position 1 ou champ médian)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/1279"},{"id":"deshalb","title":"grammis, dictionnaire des connecteurs : deshalb (conséquence ; synonymes daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"deswegen","title":"grammis, dictionnaire des connecteurs : deswegen (conséquence ; synonymes daher, deshalb)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"darum","title":"grammis, dictionnaire des connecteurs : d(a)rum (conséquence ; autre emploi : darum comme objet en um)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"korrelat","title":"grammis: Pronominaladverbien in Konnektorfunktion (deshalb/deswegen qui annonce une subordonnée en weil)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/2602"},{"id":"dann","title":"grammis, dictionnaire des connecteurs : dann (adverbe de temps ; partenaire des subordonnées en wenn)","url":"https://grammis.ids-mannheim.de/konnektoren/406978"},{"id":"partikel","title":"grammis: Abtönungspartikeln (denn dans les questions ou la conjonction denn)","url":"https://grammis.ids-mannheim.de/progr@mm/6856"},{"id":"duden-darum","title":"Duden: darum (\"aus diesem Grunde, deswegen, deshalb\" ; Darum! comme réponse sèche, familier)","url":"https://www.duden.de/rechtschreibung/darum"},{"id":"duden-dann","title":"Duden: dann (ensuite ; dans ce cas ; si … alors)","url":"https://www.duden.de/rechtschreibung/dann"},{"id":"dereko","title":"IDS Mannheim : listes de fréquence DeReKo (deshalb environ 1,7 million, deswegen environ 0,3 million d'occurrences)","url":"https://www.ids-mannheim.de/digspra/kl/projekte/methoden/derewo/"}]},{"id":"lektion-5-arbeit-finden","number":10,"added":"2026-11-11","level":"B1.1","title":"Lektion 5 · Eine Arbeit finden","title_en":"Trouver un emploi : zu + infinitif, candidatures et entretiens d'embauche","summary":"Toute la leçon en un seul endroit : *zu* + infinitif, les prépositions de temps, les formules pour postuler et pour l'entretien d'embauche, des textes modèles pour les parties d'écoute, et des exercices avec corrigé.","purpose":["La Lektion 5 porte sur la recherche d'un emploi en Suisse : lire des offres d'emploi, rédiger une lettre de candidature, l'entretien d'embauche, parler de ce que l'on aimerait faire et bavarder à propos du travail.","La grammaire dont vous avez besoin pour cela est **zu + infinitif**. Elle permet de dire ce que vous commencez, essayez, oubliez ou aimeriez faire : *Ich versuche, eine Stelle **zu finden**.* La leçon revoit aussi les prépositions de temps *vor, bei, bis, während, innerhalb, ausserhalb*.","Cette page résume ce qu'il faut retenir et employer : la grammaire, les formules classées par situation, nos propres textes modèles pour les parties d'écoute (pas les enregistrements du livre) et des exercices avec corrigé. Les mots de la leçon se trouvent dans le Vocabulaire du cours, Lektion 5. La grille de mots de la page 69 forme le mot *STELLENANZEIGE*."],"logic":["Après de nombreux verbes, après *Es ist* ou *Ich finde es* + adjectif et après *haben* + des noms comme *Lust, Zeit, Angst*, un deuxième verbe se construit en **zu + infinitif** : *Ich habe keine Lust, am Wochenende **zu arbeiten**.*","Le premier verbe est conjugué et reste en position 2. L'infinitif en *zu* va tout à la fin de son groupe ; tout ce qui s'y rattache vient avant lui : *Fang endlich an, **Bewerbungen zu schreiben**!*","Un groupe en *zu* peut remplacer une subordonnée en *dass* quand la personne reste la même : *Ich hoffe, dass ich bald eine Stelle finde.* → *Ich hoffe, bald eine Stelle **zu finden**.*","Avec les verbes à particule séparable, *zu* se place à l'intérieur du verbe : *an**zu**fangen, vor**zu**stellen, aus**zu**probieren*.","Les verbes de modalité (*können, müssen, wollen, sollen, dürfen, möchten*) et *werden* ne sont jamais suivis de *zu* : *Ich **möchte** als Verkäufer **arbeiten**.* Mais un verbe de modalité placé à la fin d'un groupe en *zu* prend lui-même *zu* : *Ich freue mich, mich bald erholen **zu können**.*","Une virgule avant le groupe en *zu* est toujours correcte, et elle est obligatoire après *es ist …* et après un nom comme *Lust* ou *Zeit*.","Le temps : *vor* (avant), *bei / beim* (au moment de, lors de), *während* (pendant), *innerhalb* (dans un délai de), *ausserhalb* (en dehors de), *bis* (jusqu'à, d'ici), *von … an* (à partir de)."],"rules":[{"title":"Verbe + zu + infinitif","text":["Ces verbes se construisent avec un deuxième verbe en **zu** : *anfangen, beginnen, aufhören, versuchen, vergessen, hoffen, planen, vorhaben, vorschlagen, verbieten, sich freuen, sich lohnen, erwarten können, sich vorstellen können*.","La plupart des verbes allemands qui se construisent avec un deuxième verbe fonctionnent ainsi ; les principales exceptions sont les verbes de modalité (voir Exceptions)."],"examples":[{"de":"Fang endlich an, Bewerbungen **zu schreiben**!","en":"Commence enfin à écrire des candidatures !"},{"de":"Ich versuche, eine Lehrstelle **zu finden**.","en":"J'essaie de trouver une place d'apprentissage."},{"de":"Ich kann mir nicht vorstellen, nachts **zu arbeiten**.","en":"Je ne peux pas m'imaginer travailler la nuit."},{"de":"Vergiss nicht, deinen Lebenslauf **mitzuschicken**!","en":"N'oublie pas de joindre ton CV !"},{"de":"Ich freue mich, Sie **kennenzulernen**.","en":"C'est un plaisir de faire votre connaissance."},{"de":"Wir haben vor, nächstes Jahr ein eigenes Geschäft **zu eröffnen**.","en":"Nous prévoyons d'ouvrir notre propre magasin l'année prochaine."},{"de":"Es lohnt sich, das Inserat genau **zu lesen**.","en":"Ça vaut la peine de lire attentivement l'annonce."}],"source":"g98"},{"title":"Es ist / Ich finde es + adjectif + zu + infinitif","text":["Pour dire ce que vous pensez d'une activité, commencez par *Es ist* + adjectif ou *Ich finde es* + adjectif, et placez l'activité à la fin sous la forme *zu* + infinitif. *es* annonce le groupe en *zu*, la virgule est donc obligatoire.","Avec *sein* : *wichtig, notwendig, möglich, leicht, schwer, schön, praktisch, anstrengend, stressig, erlaubt, verboten*. Avec *finden* : *gut, toll, interessant, langweilig*."],"table":{"caption":"Es ist … / Ich finde es … + zu + infinitif","head":["Début","Activité (zu + infinitif à la fin)"],"rows":[["Es ist toll,","Kunden **zu beraten**."],["Es ist (nicht) stressig,","im Verkauf **zu arbeiten**."],["Es ist anstrengend,","jeden Tag um fünf Uhr **aufzustehen**."],["Es ist leicht,","mit diesem Programm Rechnungen **zu schreiben**."],["Es ist verboten,","im Lager **zu rauchen**."],["Ich finde es interessant,","neue Kolleginnen und Kollegen **kennenzulernen**."]]},"examples":[{"de":"Es ist interessant, in einem grossen Team **zu arbeiten**.","en":"C'est intéressant de travailler dans une grande équipe."},{"de":"Es ist nicht leicht, nach der Schule eine Stelle **zu finden**.","en":"Ce n'est pas facile de trouver un emploi après l'école."},{"de":"Wären Sie so nett, mir Ihre Unterlagen **zu schicken**?","en":"Seriez-vous assez aimable pour m'envoyer votre dossier ?"}],"source":"g6865"},{"title":"Nom + haben + zu + infinitif","text":"Après *haben* + un nom comme *(keine) Lust, Zeit, Interesse, Angst, den Wunsch, die Möglichkeit, die Absicht, die Hoffnung*, l'activité se construit avec *zu* + infinitif. *Spass* va généralement avec *machen* : *Es macht mir Spass, …*. Le groupe en *zu* dépend du nom, la virgule est donc obligatoire.","examples":[{"de":"Hättest du Lust, als Verkäufer **zu arbeiten**?","en":"Aurais-tu envie de travailler comme vendeur ?"},{"de":"Ich habe heute keine Zeit, die Bewerbung **fertigzuschreiben**.","en":"Je n'ai pas le temps aujourd'hui de finir d'écrire la candidature."},{"de":"Viele haben Angst, im Gespräch etwas Falsches **zu sagen**.","en":"Beaucoup de gens ont peur de dire quelque chose de faux pendant l'entretien."},{"de":"Ich habe die Absicht, mich bei der Post **zu bewerben**.","en":"J'ai l'intention de postuler à la Poste."},{"de":"Hier haben Sie die Möglichkeit, Erfahrung im Verkauf **zu sammeln**.","en":"Ici, vous avez la possibilité d'acquérir de l'expérience dans la vente."},{"de":"Es macht mir Spass, im Team **zu arbeiten**.","en":"Ça me plaît de travailler en équipe."}],"source":"g6203"},{"title":"D'une subordonnée en dass à zu + infinitif","text":["Quand la personne de la subordonnée en *dass* est la même que dans la principale, vous pouvez raccourcir la phrase : supprimez *dass* et le sujet, et placez le verbe à la fin sous la forme *zu* + infinitif. Tout le reste garde son ordre.","Quand la personne est différente, gardez la subordonnée en *dass* : *Ich hoffe, dass **du** die Stelle bekommst.*"],"table":{"caption":"subordonnée en dass → zu + infinitif","head":["subordonnée en dass","zu + infinitif"],"rows":[["Ich hoffe, dass ich bald eine Stelle finde.","Ich hoffe, bald eine Stelle **zu finden**."],["Er hat Angst, dass er Fehler macht.","Er hat Angst, Fehler **zu machen**."],["Ich freue mich, dass ich Sie kennenlerne.","Ich freue mich, Sie **kennenzulernen**."],["Ich schlage vor, dass wir den Termin verschieben.","Ich schlage vor, den Termin **zu verschieben**."],["Ich hoffe, dass du die Stelle bekommst.","(personne différente : gardez *dass*)"]]},"examples":[{"de":"Sie ist sicher, die Prüfung **zu bestehen**.","en":"Elle est sûre de réussir l'examen."},{"de":"Der Chef hofft, dass **wir** pünktlich sind.","en":"Le chef espère que nous serons à l'heure (personne différente : *dass* reste)."}],"source":"g6393"},{"title":"Où se place zu : verbes à particule séparable et deux verbes","text":["Avec un verbe à particule séparable, **zu** se place entre la particule et le verbe, et les trois éléments s'écrivent en un seul mot. Avec un verbe pronominal, *sich* (ou *mich, dich …*) vient avant le reste du groupe.","Quand le groupe se termine par deux verbes, **zu** se place seulement devant le dernier : *spazieren **zu** gehen, einkaufen **zu** gehen, sich erholen **zu** können*. C'est le verbe qui précède qui décide si le suivant prend *zu*."],"table":{"caption":"Où se place zu","head":["Infinitif","zu + infinitif"],"rows":[["anfangen","an**zu**fangen"],["aufstehen","auf**zu**stehen"],["vorstellen","sich vor**zu**stellen"],["ausprobieren","aus**zu**probieren"],["anrufen","an**zu**rufen"],["spazieren gehen","spazieren **zu** gehen"],["sich erholen können","sich erholen **zu** können"]]},"examples":[{"de":"Es ist Zeit, etwas Neues **auszuprobieren**.","en":"Il est temps d'essayer quelque chose de nouveau."},{"de":"Ich habe vergessen, Frau Hartmann **anzurufen**.","en":"J'ai oublié d'appeler Mme Hartmann."},{"de":"Es ist wichtig, **sich** gut auf das Gespräch **vorzubereiten**.","en":"Il est important de bien se préparer à l'entretien."},{"de":"Hast du Lust, am Sonntag spazieren **zu gehen**?","en":"As-tu envie d'aller te promener dimanche ?"},{"de":"Ich freue mich, mich bald am Strand erholen **zu können**.","en":"Je me réjouis de pouvoir bientôt me détendre à la plage."}],"source":"g4069"},{"title":"Prépositions de temps : quand, combien de temps, à partir de quand","text":["La leçon revoit comment dire *quand* quelque chose se passe. *während, innerhalb* et *ausserhalb* se construisent avec le génitif à l'écrit ; ils sont expliqués dans le thème 7 (Genitiv).","*bei* et *vor* se construisent avec le datif : *bei der Anreise, beim (= bei dem) Gespräch, vor dem Gespräch*. *von … an* indique le point de départ : *von Anfang an*."],"table":{"caption":"Prépositions de temps de la Lektion 5","head":["Question","Préposition","Exemple"],"rows":[["Wann?","vor + Dativ","**vor** dem Gespräch (avant)"],["Wann?","bei / beim + Dativ","**beim** Gespräch, **bei** der Anreise (pendant, au moment de)"],["Wann?","während + Genitiv","**während** des Gesprächs (pendant)"],["Bis wann?","innerhalb + Genitiv","**innerhalb** einer Woche (dans un délai de)"],["Wann nicht?","ausserhalb + Genitiv","**ausserhalb** der Öffnungszeiten (en dehors de)"],["Wie lange?","bis","**bis** Freitag, **bis** zur Einladung (jusqu'à, d'ici)"],["Ab wann?","von … an","**von** Anfang **an** (dès le début)"]]},"examples":[{"de":"Wir melden uns **innerhalb** einer Woche bei Ihnen.","en":"Nous vous recontacterons dans un délai d'une semaine."},{"de":"Sie rufen leider **ausserhalb** unserer Öffnungszeiten an.","en":"Malheureusement, vous appelez en dehors de nos heures d'ouverture."},{"de":"**Vor** dem Gespräch gehe ich noch kurz spazieren.","en":"Avant l'entretien, je vais encore faire une petite promenade."},{"de":"Schauen Sie Ihrem Gesprächspartner **von** Anfang **an** in die Augen.","en":"Regardez votre interlocuteur dans les yeux dès le début."}],"source":"g6756"}],"exceptions":[{"title":"Pas de zu après les verbes de modalité et werden","text":["Après *können, müssen, wollen, sollen, dürfen, möchten* et après *werden*, le deuxième verbe est un infinitif simple, sans *zu*. Comparez : *Ich **möchte** im Team **arbeiten**.* mais *Ich **habe Lust**, im Team **zu arbeiten**.*","Il s'agit du verbe qui vient **après** le verbe de modalité. Quand le verbe de modalité est lui-même le dernier verbe d'un groupe en *zu*, il prend *zu* : *Es ist schön, Deutsch sprechen **zu können**.* L'infinitif qui dépend du verbe de modalité (*sprechen*) reste sans *zu*."],"examples":[{"de":"Ich **kann** gut mit Kunden **umgehen**.","en":"Je sais bien m'y prendre avec les clients."},{"de":"Ich **werde** mich nächste Woche **bewerben**.","en":"Je postulerai la semaine prochaine."}],"source":"g4069"},{"title":"brauchen nicht / nur … zu","text":"*nicht brauchen … zu* signifie *nicht müssen* (ne pas être obligé de), et *nur brauchen … zu* signifie *nur müssen*. À l'oral, on omet souvent *zu* après *brauchen* ; à l'écrit, employez-le.","examples":[{"de":"Sie brauchen uns keine schriftliche Bewerbung **zu schicken**.","en":"Vous n'avez pas besoin de nous envoyer de candidature écrite."},{"de":"Sie brauchen uns nur **anzurufen**.","en":"Vous n'avez qu'à nous appeler."}],"source":"g98"}],"phrases":[{"title":"Rédiger une lettre de candidature","items":[{"de":"Bewerbung als Servicetechniker","en":"Candidature au poste de technicien de service (objet)"},{"de":"Sehr geehrte Damen und Herren","en":"Madame, Monsieur","note":"En Suisse, pas de virgule après la formule d'appel ; la lettre commence par une majuscule."},{"de":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die Stelle.","en":"C'est avec un grand intérêt que j'ai lu votre annonce, et je postule pour le poste."},{"de":"Wie Sie meinen Unterlagen entnehmen können, war ich in Portugal als Elektriker tätig.","en":"Comme vous pouvez le constater dans mon dossier, j'ai travaillé comme électricien au Portugal."},{"de":"Dort war ich für die Montage von Solaranlagen zuständig.","en":"J'y étais responsable du montage d'installations solaires."},{"de":"Ich bin es gewohnt, selbstständig und zuverlässig zu arbeiten.","en":"J'ai l'habitude de travailler de manière autonome et fiable."},{"de":"Es macht mir grosse Freude, Kunden zu beraten.","en":"C'est pour moi un grand plaisir de conseiller les clients."},{"de":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich sehr freuen.","en":"Une invitation à un entretien personnel me ferait très plaisir."},{"de":"Freundliche Grüsse","en":"Meilleures salutations","note":"Formule de clôture suisse : pas de virgule après."},{"de":"Beilagen: Lebenslauf, Diplom und Arbeitszeugnisse","en":"Annexes : CV, diplôme et certificats de travail"}]},{"title":"À l'entretien d'embauche : l'employeur demande","items":[{"de":"Kommen Sie doch bitte herein. Schön, dass Sie da sind.","en":"Entrez donc, je vous en prie. C'est un plaisir de vous accueillir."},{"de":"Nehmen Sie doch bitte Platz.","en":"Prenez place, je vous en prie."},{"de":"Erzählen Sie doch bitte etwas über sich.","en":"Parlez-nous un peu de vous, s'il vous plaît."},{"de":"Welche Aufgaben hatten Sie in Ihrer letzten Firma?","en":"Quelles étaient vos tâches dans votre dernière entreprise ?"},{"de":"Konnten Sie während Ihrer Ausbildung schon praktische Erfahrungen sammeln?","en":"Avez-vous déjà pu acquérir une expérience pratique pendant votre formation ?"},{"de":"Haben Sie auch Computerkenntnisse? Welche Sprachkenntnisse haben Sie?","en":"Avez-vous aussi des connaissances en informatique ? Quelles langues parlez-vous ?"},{"de":"Haben Sie noch Fragen?","en":"Avez-vous encore des questions ?"},{"de":"Wir melden uns innerhalb der nächsten Woche bei Ihnen.","en":"Nous vous recontacterons dans le courant de la semaine prochaine."}]},{"title":"À l'entretien d'embauche : vous répondez","items":[{"de":"Vielen Dank für die Einladung zum Gespräch.","en":"Merci beaucoup pour l'invitation à l'entretien."},{"de":"Ich habe Elektroinstallateur gelernt. Davor habe ich als Verkäufer bei einem Elektrofachhändler gearbeitet.","en":"J'ai fait un apprentissage d'installateur-électricien. Avant, j'ai travaillé comme vendeur chez un détaillant en électronique."},{"de":"Ich mache gerade meine Ausbildung fertig.","en":"Je suis en train de terminer ma formation."},{"de":"Ich war im Lager tätig. Dort war ich für die Bestellungen zuständig.","en":"J'ai travaillé à l'entrepôt. J'y étais responsable des commandes."},{"de":"Ich habe eine Schnupperlehre bei einer Bank gemacht.","en":"J'ai fait un stage d'observation dans une banque."},{"de":"Ich habe leider noch keine Berufserfahrung.","en":"Malheureusement, je n'ai pas encore d'expérience professionnelle."},{"de":"Es fällt mir leicht, mit Menschen zu sprechen.","en":"Il m'est facile de parler avec les gens."},{"de":"Ja, ich würde gern wissen, wie die Arbeitszeiten sind.","en":"Oui, j'aimerais savoir quels sont les horaires de travail."}]},{"title":"Parler de ce que l'on aimerait faire","items":[{"de":"Ich habe Lust, viel zu reisen.","en":"J'ai envie de beaucoup voyager."},{"de":"Ich habe Interesse daran, etwas Neues zu entwickeln.","en":"Développer quelque chose de nouveau m'intéresse."},{"de":"Ich kann mir gut vorstellen, im Freien zu arbeiten.","en":"Je m'imagine bien travailler en plein air."},{"de":"Ich finde es anstrengend, den ganzen Tag am Computer zu sitzen.","en":"Je trouve fatigant d'être assis devant l'ordinateur toute la journée."},{"de":"Es macht mir Spass, anderen zu helfen.","en":"Ça me fait plaisir d'aider les autres."}]},{"title":"Bavarder à propos du travail","items":[{"de":"Wie läuft's denn so in der Firma?","en":"Comment ça se passe dans l'entreprise ?"},{"de":"Wie läuft's mit der Jobsuche?","en":"Comment avance ta recherche d'emploi ?"},{"de":"Hast du immer noch so viel Arbeit?","en":"Tu as toujours autant de travail ?"},{"de":"Was machst du jetzt eigentlich genau?","en":"Qu'est-ce que tu fais exactement maintenant ?"},{"de":"Ist das nicht stressig?","en":"Ce n'est pas stressant ?"},{"de":"Hast du noch nie daran gedacht, die Stelle zu wechseln?","en":"Tu n'as jamais pensé à changer de poste ?"},{"de":"Ich habe doch eine neue Stelle als Pflegefachfrau im Spital.","en":"J'ai un nouveau poste d'infirmière à l'hôpital, tu sais."},{"de":"Ich muss im Moment eine Kollegin vertreten.","en":"En ce moment, je dois remplacer une collègue."},{"de":"Ich suche immer noch eine Stelle als Koch.","en":"Je cherche toujours un poste de cuisinier."}]},{"title":"Terminer une conversation","items":[{"de":"Oh, ich muss jetzt leider gehen.","en":"Oh, je dois malheureusement partir maintenant."},{"de":"Schade, ich muss jetzt leider dringend zum Bahnhof.","en":"Dommage, je dois malheureusement filer à la gare de toute urgence."},{"de":"Also dann tschüss. Es war schön, dich wieder einmal zu sehen.","en":"Bon, alors salut. C'était sympa de te revoir."},{"de":"Bis zum nächsten Mal!","en":"À la prochaine !"}]},{"title":"Mots suisses et dialecte de la leçon","items":[{"de":"die Schnupperlehre","en":"un court stage d'observation (quelques jours dans une entreprise)"},{"de":"die Lehrstelle, die Lehre (EFZ)","en":"une place d'apprentissage, l'apprentissage (avec le certificat fédéral de capacité)"},{"de":"die Berufsberatung, das BIZ","en":"l'orientation professionnelle, le centre d'information professionnelle"},{"de":"das Stelleninserat","en":"l'offre d'emploi"},{"de":"das Arbeitszeugnis","en":"un certificat de travail établi par un employeur"},{"de":"Chunsch druus? = Verstehst du?","en":"Tu comprends ? (suisse allemand)"},{"de":"Säg nüt! = Ja, wirklich!","en":"C'est vrai ! / Sans blague ! (suisse allemand)"},{"de":"Du chasch nöd de Föifer und s'Weggli ha. = Du kannst nicht alles haben.","en":"On ne peut pas avoir le beurre et l'argent du beurre. (suisse allemand : littéralement, on ne peut pas avoir la pièce de cinq centimes et le petit pain)"}]}],"texts":[{"title":"Roman-photo, épisode 5 : Selbst etwas dafür tun","note":"Notre propre récit, rédigé à partir des points clés imprimés dans le livre (pages 58–59). Ce n'est pas l'enregistrement.","lines":[{"de":"Lina ruft Ella an. Sie macht sich Sorgen um ihren Sohn Sascha.","en":"Lina appelle Ella. Elle se fait du souci pour son fils Sascha."},{"de":"Sascha hat einen schlechten Schulabschluss gemacht und findet keine Lehrstelle.","en":"Sascha a terminé l'école avec de mauvais résultats et ne trouve pas de place d'apprentissage."},{"de":"Lina fragt Ella, ob sie Sascha bei der Bewerbung helfen kann.","en":"Lina demande à Ella si elle peut aider Sascha pour sa candidature."},{"de":"Sascha hat eine Schnupperlehre bei MediaUniverse gemacht und kennt sich gut mit Technik aus.","en":"Sascha a fait un stage d'observation chez MediaUniverse et s'y connaît bien en technique."},{"de":"Ella hat eine Idee: Sascha soll sich als Verkäufer bewerben.","en":"Ella a une idée : Sascha devrait postuler comme vendeur."},{"de":"Sascha bewirbt sich und wird zum Vorstellungsgespräch eingeladen. Ella übt das Gespräch mit ihm.","en":"Sascha postule et est invité à un entretien d'embauche. Ella s'exerce à l'entretien avec lui."},{"de":"Dabei merkt sie: Sascha ist ein sehr guter Schauspieler.","en":"Ce faisant, elle remarque que Sascha est un très bon acteur."},{"de":"Am Ende sind Lina und Ella überrascht: Sascha hat sich an einer Schauspielschule beworben und einen Platz bekommen.","en":"À la fin, Lina et Ella sont surprises : Sascha a postulé dans une école de théâtre et a obtenu une place."}]},{"title":"Dialogue modèle : Fang endlich an!","note":"Notre propre court dialogue avec les trois structures de A1 (page 60). La répartition des répliques peut être différente dans l'enregistrement.","lines":[{"de":"Lina: Sascha, fang endlich an, Bewerbungen zu schreiben!","en":"Lina : Sascha, commence enfin à écrire des candidatures !"},{"de":"Sascha: Ich habe aber keine Idee, was ich werden will.","en":"Sascha : Mais je n'ai aucune idée de ce que je veux devenir."},{"de":"Ella: Hättest du Lust, als Verkäufer in einem Fachgeschäft zu arbeiten?","en":"Ella : Aurais-tu envie de travailler comme vendeur dans un magasin spécialisé ?"},{"de":"Sascha: Vielleicht. Es ist sicher toll, Kunden zu beraten, wenn man sich mit Technik auskennt.","en":"Sascha : Peut-être. Ce doit être super de conseiller les clients quand on s'y connaît en technique."}]},{"title":"Entretien modèle chez un détaillant en électronique","note":"Notre propre entretien modèle, construit à partir des formules de B3 (page 63). Ce n'est pas l'enregistrement.","lines":[{"de":"Frau Hartmann: Guten Tag, Herr Novak. Kommen Sie doch bitte herein. Nehmen Sie Platz.","en":"Mme Hartmann : Bonjour, Monsieur Novak. Entrez donc, je vous en prie. Prenez place."},{"de":"Herr Novak: Vielen Dank für die Einladung zum Gespräch.","en":"M. Novak : Merci beaucoup pour l'invitation à l'entretien."},{"de":"Frau Hartmann: Erzählen Sie doch bitte etwas über sich.","en":"Mme Hartmann : Parlez-moi donc un peu de vous, s'il vous plaît."},{"de":"Herr Novak: Ich habe letzten Sommer die Schule abgeschlossen. Danach habe ich eine Schnupperlehre bei einem Elektrofachhändler in Bern gemacht.","en":"M. Novak : J'ai terminé l'école l'été dernier. Ensuite, j'ai fait un stage d'observation chez un détaillant en électronique à Berne."},{"de":"Frau Hartmann: Konnten Sie dort schon praktische Erfahrungen sammeln?","en":"Mme Hartmann : Avez-vous déjà pu y acquérir une expérience pratique ?"},{"de":"Herr Novak: Ja, ich durfte Kunden beraten und Geräte im Lager einräumen. Es hat mir grosse Freude gemacht.","en":"M. Novak : Oui, j'ai pu conseiller des clients et ranger des appareils dans l'entrepôt. Cela m'a beaucoup plu."},{"de":"Frau Hartmann: Haben Sie auch technische Kenntnisse? Welche Sprachen sprechen Sie?","en":"Mme Hartmann : Avez-vous aussi des connaissances techniques ? Quelles langues parlez-vous ?"},{"de":"Herr Novak: Ich kenne mich gut mit Handys und Laptops aus. Ich spreche Deutsch, Portugiesisch und ein bisschen Französisch.","en":"M. Novak : Je m'y connais bien en téléphones portables et en ordinateurs portables. Je parle allemand, portugais et un peu français."},{"de":"Frau Hartmann: Haben Sie noch Fragen?","en":"Mme Hartmann : Avez-vous encore des questions ?"},{"de":"Herr Novak: Ja, ich würde gern wissen, wie die Arbeitszeiten am Samstag sind.","en":"M. Novak : Oui, j'aimerais savoir quels sont les horaires de travail le samedi."},{"de":"Frau Hartmann: Samstags arbeiten wir von neun bis sechzehn Uhr. Wir melden uns innerhalb der nächsten Woche bei Ihnen. Vielen Dank, dass Sie gekommen sind.","en":"Mme Hartmann : Le samedi, nous travaillons de neuf heures à seize heures. Nous vous recontacterons dans le courant de la semaine prochaine. Merci beaucoup d'être venu."},{"de":"Herr Novak: Vielen Dank auch Ihnen. Auf Wiedersehen.","en":"M. Novak : Merci à vous aussi. Au revoir."}]},{"title":"Conversation modèle : une rencontre fortuite au supermarché","note":"Notre propre dialogue, d'après la fiche de rôle de Kasimir Woźniak en D2 (page 65). Ce n'est pas l'enregistrement de D1.","lines":[{"de":"Anna: Hallo Kasimir! Wie läuft's denn so? Was machst du jetzt eigentlich genau?","en":"Anna : Salut Kasimir ! Comment ça va ? Qu'est-ce que tu fais exactement maintenant ?"},{"de":"Kasimir: Ich bin jetzt selbstständig als Übersetzer und Dolmetscher. Die Arbeit ist sehr interessant.","en":"Kasimir : Je suis maintenant traducteur et interprète indépendant. Le travail est très intéressant."},{"de":"Anna: Toll! Und hast du genug Aufträge?","en":"Anna : Super ! Et tu as assez de mandats ?"},{"de":"Kasimir: Leider nicht. Es gibt viel Konkurrenz. Deshalb muss ich nebenbei als Velokurier jobben.","en":"Kasimir : Malheureusement non. Il y a beaucoup de concurrence. C'est pourquoi je dois faire des petits boulots à côté, comme coursier à vélo."},{"de":"Anna: Ist das nicht anstrengend?","en":"Anna : Ce n'est pas fatigant ?"},{"de":"Kasimir: Doch, und mit dem Chef komme ich nicht zurecht. Ich überlege, eine Fortbildung zu machen.","en":"Kasimir : Si, et je ne m'entends pas avec le chef. J'envisage de faire une formation continue."},{"de":"Anna: Oh, ich muss jetzt leider gehen. Es war schön, dich wieder einmal zu sehen. Bis zum nächsten Mal!","en":"Anna : Oh, je dois malheureusement partir maintenant. C'était sympa de te revoir. À la prochaine !"}]},{"title":"Conversation modèle : à l'arrêt de bus","note":"Notre propre dialogue, d'après la fiche de rôle de Thomas Meier en D2 (page 65). Ce n'est pas un enregistrement.","lines":[{"de":"Teresa: Hallo Thomas! Wie läuft's mit der Jobsuche?","en":"Teresa : Salut Thomas ! Comment avance ta recherche d'emploi ?"},{"de":"Thomas: Ach, ich bin seit einem halben Jahr arbeitslos. Es gibt zurzeit kaum Stellen als Tierpfleger im Zoo.","en":"Thomas : Bof, je suis au chômage depuis six mois. Il n'y a presque pas de postes de gardien d'animaux au zoo en ce moment."},{"de":"Teresa: Das tut mir leid. Hast du schon Bewerbungen geschrieben?","en":"Teresa : Je suis désolée. Tu as déjà écrit des candidatures ?"},{"de":"Thomas: Ja, mehrere. Aber ich habe eine gute Weiterbildung besucht, und vor zwei Wochen hatte ich ein interessantes Vorstellungsgespräch.","en":"Thomas : Oui, plusieurs. Mais j'ai suivi une bonne formation continue, et il y a deux semaines, j'ai eu un entretien d'embauche intéressant."},{"de":"Teresa: Super! Ich drücke dir die Daumen.","en":"Teresa : Super ! Je croise les doigts pour toi."},{"de":"Thomas: Danke! Ich hoffe, dass ich die Stelle bekomme.","en":"Thomas : Merci ! J'espère que j'aurai le poste."}]}],"mistakes":[{"wrong":"Ich möchte zu arbeiten als Verkäufer.","right":"Ich möchte als Verkäufer arbeiten.","why":"Après un verbe de modalité, il n'y a pas de *zu*, et l'infinitif va à la fin. L'anglais *I'd like **to** work* incite les anglophones à ajouter *zu*."},{"wrong":"Ich versuche zu anrufen ihn.","right":"Ich versuche, ihn anzurufen.","why":"Avec un verbe à particule séparable, *zu* se place à l'intérieur (*anzurufen*), et l'infinitif vient en dernier, après son complément. L'anglais, l'italien et l'espagnol placent le complément après le verbe (*to call him, chiamarlo, llamarlo*)."},{"wrong":"Ich habe Lust für im Team arbeiten.","right":"Ich habe Lust, im Team zu arbeiten.","why":"Le français, l'italien et l'espagnol relient le nom au verbe par une préposition (*envie de travailler, voglia di lavorare, ganas de trabajar*) ; l'allemand emploie *zu* + infinitif à la fin de la phrase."},{"wrong":"Es ist toll zu beraten Kunden.","right":"Es ist toll, Kunden zu beraten.","why":"Tout ce qui se rattache à l'activité vient avant *zu* + infinitif. L'ordre de l'anglais (*to advise customers*) est inversé."},{"wrong":"Wir melden uns während einer Woche.","right":"Wir melden uns innerhalb einer Woche.","why":"*innerhalb* = dans un délai de (à un moment quelconque avant la fin du délai) ; *während* = pendant (tout du long). L'anglais *within* et le français *dans*, l'italien *entro*, l'espagnol *dentro de* correspondent à *innerhalb*."},{"wrong":"Sie brauchen keine Bewerbung schicken.","right":"Sie brauchen keine Bewerbung zu schicken.","why":"À l'oral, on laisse souvent tomber *zu* après *brauchen*, mais à l'écrit, employez *brauchen … zu*. Ne l'employez pas comme *müssen*, sans *zu*."},{"wrong":"Ich hoffe, dass ich bald eine Stelle zu finden.","right":"Ich hoffe, bald eine Stelle zu finden.","why":"Employez soit une subordonnée en *dass* (sujet + verbe conjugué : *dass ich … finde*), soit un groupe en *zu* (sans *dass*, sans sujet), jamais les deux dans la même proposition."},{"wrong":"Ich freue mich, mich bald zu erholen können.","right":"Ich freue mich, mich bald erholen zu können.","why":"Avec deux verbes à la fin, *zu* se place seulement devant le dernier. L'anglais *to be able to relax* met *to* en premier."}],"examples":[{"de":"Ich habe angefangen, Deutsch für den Beruf zu lernen.","en":"J'ai commencé à apprendre l'allemand pour le travail."},{"de":"Es ist nicht leicht, eine Lehrstelle als Mediamatiker zu finden.","en":"Ce n'est pas facile de trouver une place d'apprentissage de médiamaticien."},{"de":"Hast du Zeit, meinen Lebenslauf zu lesen?","en":"As-tu le temps de lire mon CV ?"},{"de":"Hör bitte auf, dir so viele Sorgen zu machen!","en":"Arrête de te faire autant de soucis, s'il te plaît !"},{"de":"Ich kann mir gut vorstellen, in einem Hotel zu arbeiten.","en":"Je m'imagine bien travailler dans un hôtel."},{"de":"Während des Gesprächs sollten Sie Ihr Handy ausschalten.","en":"Pendant l'entretien, vous devriez éteindre votre portable."},{"de":"Bei der Anreise rechnen Sie am besten einen zeitlichen Puffer ein.","en":"Pour le trajet, prévoyez de préférence une marge de temps."},{"de":"Wir sollten wirklich versuchen, nicht noch mehr Zeit zu verlieren.","en":"Nous devrions vraiment essayer de ne pas perdre encore plus de temps."}],"later":"*um … zu* (but : *Ich lerne Deutsch, **um** eine Stelle **zu** finden*) et *ohne … zu, statt … zu* viendront dans une leçon ultérieure.","selfcheck":{"types":{"zu":{"label":"zu ou pas ?","instruction":"Écrivez *zu* si la phrase en a besoin. Si aucun mot n'est nécessaire (par exemple après un verbe de modalité), écrivez un tiret : **-**.","example":{"q":"Ich habe heute keine Zeit, ___ kochen.","a":"zu","why":"Après *keine Zeit haben*, le deuxième verbe se construit avec *zu*."}},"form":{"label":"Former le verbe","instruction":"Écrivez le verbe entre parenthèses sous la forme *zu* + infinitif. Les verbes à particule séparable prennent *zu* à l'intérieur et s'écrivent en un seul mot (*anzufangen*) ; les autres verbes s'écrivent en deux mots (*zu lesen*).","example":{"q":"Ich versuche, früh ___ (aufstehen).","a":"aufzustehen","why":"*aufstehen* est à particule séparable : *auf + zu + stehen*."}},"build":{"label":"Faire une seule phrase","instruction":"Réunissez les deux parties en une seule phrase. Gardez la première partie, puis transformez la deuxième phrase en groupe *zu* + infinitif à la fin (supprimez son sujet). Écrivez la phrase entière, avec une virgule.","example":{"q":"Ich habe keine Lust / Ich arbeite am Wochenende.","a":"Ich habe keine Lust, am Wochenende zu arbeiten.","why":"*ich* disparaît, *arbeite* devient *zu arbeiten* à la fin."}},"dass":{"label":"dass ou zu ?","instruction":"Réécrivez la phrase avec *zu* + infinitif : supprimez *dass* et le sujet, placez le verbe à la fin avec *zu*. Si la personne de la subordonnée en *dass* n'est pas la même que dans la principale, ce n'est pas possible : écrivez **dass**.","example":{"q":"Ich hoffe, dass ich bald Ferien habe.","a":"Ich hoffe, bald Ferien zu haben.","why":"Même personne (*ich … ich*) : *dass ich* disparaît, *habe* devient *zu haben* à la fin."}},"card":{"label":"Phrase à partir d'une carte","instruction":"Chaque carte de la fiche de travail du cours donne un sujet, une expression et une activité. Écrivez une phrase au présent : d'abord l'expression, puis l'activité sous la forme *zu* + infinitif à la fin. Les cartes *es* commencent par *Es ist …* (ou *Es macht …*).","example":{"q":"es – leicht sein – Deutsch sprechen","a":"Es ist leicht, Deutsch zu sprechen.","why":"*es* + *leicht sein* → *Es ist leicht*, puis l'activité avec *zu* à la fin."}},"time":{"label":"Quel mot de temps ?","instruction":"Écrivez le mot qui manque : *vor, bei, beim, bis, während, innerhalb* ou *ausserhalb*. Regardez le sens (avant, pendant, dans un délai de, en dehors de, jusqu'à) et le cas de ce qui suit.","example":{"q":"___ des Unterrichts darf man nicht telefonieren.","a":"Während","why":"Pendant le cours, et *des Unterrichts* est au génitif → *während*."}},"phrase":{"label":"Compléter la formule","instruction":"Écrivez le mot qui manque dans une formule de la lettre de candidature ou de l'entretien d'embauche.","example":{"q":"Erzählen Sie doch bitte etwas über ___.","a":"sich","why":"La demande figée de l'entretien : *Erzählen Sie etwas über sich.*"}},"dialect":{"label":"Suisse allemand","instruction":"Écrivez ce que la phrase en suisse allemand signifie en allemand standard.","example":{"q":"Grüezi mitenand!","a":"Guten Tag zusammen!","why":"*Grüezi* = *Guten Tag*, *mitenand* = *miteinander, zusammen*."}}},"items":[{"type":"zu","q":"Ich kann mir vorstellen, im Team ___ arbeiten.","a":["zu"],"why":"*sich vorstellen können* se construit avec *zu* + infinitif."},{"type":"zu","q":"Ich möchte gern im Büro ___ arbeiten.","a":["-","–"],"why":"*möchten* est un verbe de modalité : pas de *zu*."},{"type":"zu","q":"Es ist anstrengend, jeden Tag Überstunden ___ machen.","a":["zu"],"why":"*Es ist* + adjectif se construit avec *zu* + infinitif."},{"type":"zu","q":"Ich werde mich morgen bei der Firma ___ melden.","a":["-","–"],"why":"*werden* ne prend jamais *zu*."},{"type":"zu","q":"Ich freue mich, bald mehr verdienen ___ können.","a":["zu"],"why":"*können* est le dernier verbe du groupe en *zu* après *sich freuen*, il prend donc *zu*."},{"type":"form","q":"Vergiss nicht, die Bewerbung heute ___ (abschicken).","a":["abzuschicken"],"why":"*abschicken* est à particule séparable : *ab + zu + schicken*."},{"type":"form","q":"Hast du Lust, am Samstag ___ (mitkommen)?","a":["mitzukommen"],"why":"*mitkommen* est à particule séparable : *mit + zu + kommen*."},{"type":"form","q":"Es ist wichtig, sich gut auf das Gespräch ___ (vorbereiten).","a":["vorzubereiten"],"why":"*vorbereiten* est à particule séparable ; *sich* reste devant : *sich … vorzubereiten*."},{"type":"form","q":"Ich habe aufgehört, abends E-Mails ___ (lesen).","a":["zu lesen"],"why":"*lesen* n'est pas à particule séparable : deux mots, *zu lesen*."},{"type":"build","q":"Es ist anstrengend / Ich stehe jeden Tag um fünf Uhr auf.","a":["Es ist anstrengend, jeden Tag um fünf Uhr aufzustehen."],"why":"Le sujet disparaît, *aufstehen* devient *aufzustehen* à la fin."},{"type":"build","q":"Ich kann mir gut vorstellen / Ich arbeite im Freien.","a":["Ich kann mir gut vorstellen, im Freien zu arbeiten."],"why":"*sich vorstellen können* + *zu* + infinitif à la fin."},{"type":"build","q":"Hör bitte auf / Du kommst immer zu spät.","a":["Hör bitte auf, immer zu spät zu kommen.","Hör bitte auf, immer zu spät zu kommen!"],"why":"*zu spät* est un adverbe ; le *zu* de l'infinitif se place juste avant *kommen*."},{"type":"build","q":"Wir haben Interesse / Wir lernen neue Kunden kennen.","a":["Wir haben Interesse, neue Kunden kennenzulernen.","Wir haben Interesse daran, neue Kunden kennenzulernen."],"why":"*kennenlernen* est à particule séparable : *kennen + zu + lernen*, en un seul mot."},{"type":"dass","q":"Ich hoffe, dass ich die Probezeit bestehe.","a":["Ich hoffe, die Probezeit zu bestehen."],"why":"Même personne : *dass ich* disparaît, *bestehe* → *zu bestehen* à la fin."},{"type":"dass","q":"Er hat Angst, dass er zu spät kommt.","a":["Er hat Angst, zu spät zu kommen."],"why":"Même personne (*er … er*). *zu spät* reste ; le *zu* de l'infinitif se place juste devant *kommen*."},{"type":"dass","q":"Ich hoffe, dass mein Chef mir mehr Lohn gibt.","a":["dass"],"why":"Personne différente (*ich* espère, *mein Chef* donne) : gardez la subordonnée en *dass*."},{"type":"dass","q":"Wir freuen uns, dass wir Sie bald im Team begrüssen.","a":["Wir freuen uns, Sie bald im Team zu begrüssen."],"why":"Même personne (*wir … wir*) : *dass wir* disparaît, *begrüssen* → *zu begrüssen*."},{"type":"dass","q":"Sie ist sicher, dass sie die Stelle bekommt.","a":["Sie ist sicher, die Stelle zu bekommen."],"why":"Même personne (*sie … sie*) : *dass sie* disparaît, *bekommt* → *zu bekommen*."},{"type":"card","q":"es – schön sein – dich sehen","a":["Es ist schön, dich zu sehen."],"why":"*Es ist schön* + *zu* + infinitif."},{"type":"card","q":"ich – versuchen – dich morgen anrufen","a":["Ich versuche, dich morgen anzurufen."],"why":"*anrufen* est à particule séparable : *anzurufen*, en un seul mot."},{"type":"card","q":"er – Angst haben – Fehler machen","a":["Er hat Angst, Fehler zu machen."],"why":"*Angst haben* + *zu* + infinitif."},{"type":"card","q":"es – teuer sein – im Zentrum wohnen","a":["Es ist teuer, im Zentrum zu wohnen."],"why":"*Es ist teuer* + *zu* + infinitif."},{"type":"card","q":"es – nicht leicht sein – eine Arbeit finden","a":["Es ist nicht leicht, eine Arbeit zu finden."],"why":"*nicht* reste avec *leicht* ; *zu finden* à la fin."},{"type":"card","q":"es – verboten sein – hier rauchen","a":["Es ist verboten, hier zu rauchen."],"why":"*Es ist verboten* + *zu* + infinitif."},{"type":"card","q":"er – hoffen – einen guten Job finden","a":["Er hofft, einen guten Job zu finden."],"why":"*hoffen* + *zu* + infinitif ; *er hofft*."},{"type":"card","q":"ich – mich freuen – Sie kennenlernen","a":["Ich freue mich, Sie kennenzulernen."],"why":"*kennenlernen* → *kennenzulernen*, en un seul mot."},{"type":"card","q":"ich – keine Lust haben – aufräumen","a":["Ich habe keine Lust, aufzuräumen.","Ich habe keine Lust aufzuräumen."],"why":"*aufräumen* est à particule séparable : *aufzuräumen*."},{"type":"card","q":"es – möglich sein – mit Karte bezahlen","a":["Es ist möglich, mit Karte zu bezahlen."],"why":"*bezahlen* n'est pas à particule séparable (*be-* reste attaché) : *zu bezahlen*."},{"type":"card","q":"ich – keine Zeit haben – ins Fitnessstudio gehen","a":["Ich habe keine Zeit, ins Fitnessstudio zu gehen."],"why":"*keine Zeit haben* + *zu* + infinitif."},{"type":"card","q":"ich – oft vergessen – die Tür abschliessen","a":["Ich vergesse oft, die Tür abzuschliessen."],"why":"*abschliessen* est à particule séparable : *abzuschliessen*."},{"type":"card","q":"es – wichtig sein – Fremdsprachen lernen","a":["Es ist wichtig, Fremdsprachen zu lernen."],"why":"*Es ist wichtig* + *zu* + infinitif."},{"type":"card","q":"ich – aufhören wollen – so viele Süssigkeiten essen","a":["Ich will aufhören, so viele Süssigkeiten zu essen."],"why":"*wollen* + *aufhören* sans *zu* ; *aufhören* prend ensuite *zu essen*."},{"type":"card","q":"es – Spass machen – mit Menschen arbeiten","a":["Es macht Spass, mit Menschen zu arbeiten."],"why":"*Es macht Spass* + *zu* + infinitif."},{"type":"card","q":"wir – am Freitag vorhaben – ins Kino gehen","a":["Wir haben am Freitag vor, ins Kino zu gehen.","Am Freitag haben wir vor, ins Kino zu gehen.","Wir haben vor, am Freitag ins Kino zu gehen."],"why":"*vorhaben* se sépare : *wir haben … vor*, puis *zu gehen*."},{"type":"card","q":"ich – es interessant finden – fremde Länder kennenlernen","a":["Ich finde es interessant, fremde Länder kennenzulernen."],"why":"*Ich finde es interessant* + *kennenzulernen*."},{"type":"card","q":"es – manchmal schwer sein – ein Visum bekommen","a":["Es ist manchmal schwer, ein Visum zu bekommen.","Manchmal ist es schwer, ein Visum zu bekommen."],"why":"*bekommen* n'est pas à particule séparable : *zu bekommen*."},{"type":"time","q":"Wir melden uns ___ einer Woche bei Ihnen.","a":["innerhalb"],"why":"Dans un délai d'une semaine (une échéance) → *innerhalb* + génitif."},{"type":"time","q":"Sie rufen leider ___ unserer Öffnungszeiten an. Wir sind ab acht Uhr wieder da.","a":["ausserhalb"],"why":"Le bureau est fermé : en dehors des heures d'ouverture → *ausserhalb*."},{"type":"time","q":"___ dem Gespräch habe ich mich gut informiert.","a":["Vor"],"why":"Avant l'entretien, et *dem Gespräch* est au datif → *vor*."},{"type":"time","q":"___ Bewerbungsgespräch sollte man den Gesprächspartner anschauen.","a":["Beim"],"why":"Au moment de l'entretien, *Bewerbungsgespräch* sans article → *beim* (= *bei dem*)."},{"type":"time","q":"Bitte schicken Sie uns Ihre Unterlagen ___ Ende Mai.","a":["bis"],"why":"Une échéance : d'ici la fin mai → *bis*."},{"type":"phrase","q":"Mit grossem ___ habe ich Ihr Inserat gelesen.","a":["Interesse"],"why":"La première phrase type d'une lettre de candidature."},{"type":"phrase","q":"Wie Sie meinen Unterlagen ___ können, war ich drei Jahre als Koch tätig.","a":["entnehmen"],"why":"*etwas einer Sache entnehmen* = constater quelque chose d'après un document ; formule figée de lettre."},{"type":"phrase","q":"Über eine ___ zu einem persönlichen Gespräch würde ich mich sehr freuen.","a":["Einladung"],"why":"La dernière phrase type d'une lettre de candidature."},{"type":"phrase","q":"Ich bin es ___, selbstständig zu arbeiten.","a":["gewohnt"],"why":"*es gewohnt sein, … zu …* = avoir l'habitude de faire quelque chose."},{"type":"dialect","q":"Chunsch druus?","a":["Verstehst du?"],"why":"*drauskommen* (suisse) = *verstehen*."},{"type":"dialect","q":"Du chasch nöd de Föifer und s'Weggli ha.","a":["Du kannst nicht alles haben."],"why":"Littéralement, la pièce de cinq centimes et le petit pain : on ne peut pas payer et garder l'argent."}]},"links":[{"text":"Thème 7 · Genitiv : *während, innerhalb, ausserhalb* et d'autres prépositions avec le génitif","href":"classroom.html#genitiv"},{"text":"Vocabulaire du cours : les mots de la Lektion 5","href":"lernwortschatz.html"}],"sources":[{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (verbes avec un infinitif avec ou sans zu)","url":"https://grammis.ids-mannheim.de/fragen/98","note":"La plupart des verbes prennent *zu* ; les verbes de modalité et *werden*, non ; *brauchen* s'emploie avec et sans *zu*."},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (approfondissement : les groupes infinitifs)","url":"https://grammis.ids-mannheim.de/progr@mm/6865","note":"Le groupe en *zu* fonctionne comme une petite proposition ; l'infinitif vient en dernier."},{"id":"g3647","title":"grammis: Verbflexion (kontrastive Grammatik) (conjugaison du verbe, grammaire contrastive)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/3647","note":"*zu* entre la particule et le radical dans les verbes à particule séparable (*abzufahren*)."},{"id":"g6203","title":"grammis: 2.3 Komma bei Nebensätzen (la virgule avec les subordonnées)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203","note":"Les groupes en *zu* comptent comme des propositions et sont séparés par une virgule, même lorsqu'ils dépendent d'un nom ou d'un mot de renvoi comme *es*."},{"id":"g6756","title":"grammis: Orientierungszeit-Perspektive (le repérage dans le temps)","url":"https://grammis.ids-mannheim.de/progr@mm/6756","note":"Prépositions de temps *vor, während, bis, ab*."},{"id":"g299310","title":"grammis: während (Präposition) (während, préposition)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393","note":"Un infinitif en *zu* remplace une subordonnée en *dass* surtout quand son sujet non exprimé est la même personne que dans la principale."},{"id":"g4069","title":"grammis: Verbflexion","url":"https://grammis.ids-mannheim.de/progr@mm/4069","note":"C'est le verbe dont dépend l'infinitif qui décide s'il prend *zu* ; avec les verbes à particule séparable, *zu* se place entre la particule et le radical."}]}];
